/**
 * EQUIPO DE LUCES: registro de las luces de la experiencia y de lo que se les puede editar (tecla L, ver ui/lightEditor.js).
 *
 * Cada luz se registra con registerRigLight(grupo, id, nombre, luz). Lo editable es:
 *   intensidad  un multiplicador sobre su intensidad normal (1 = como esta). quakeEffects.js lo aplica con rigK(luz) cada cuadro
 *   direccion   giro (az, 0-360 grados) y altura (el, grados hacia abajo) hacia donde apunta (sol y focos)
 *   posicion    desplazamiento x / y / z en metros (focos y lamparas)
 *   sombra      si proyecta sombra
 * Los ajustes se guardan en el navegador (clave petalert.lights) y se pueden copiar como JSON para dejarlos como valores por defecto.
 *
 * Grupos (que luces se ven en el editor segun la escena): 'mundo' = la casa de cajas (introduccion, orbita y cuarto), 'sala' = la sala de
 * primera persona (static/casa-luces.glb), 'cuarto' = el cuarto de tercera persona.
 */
import * as THREE from 'three'
import { EDIT_TOOLS } from '../config.js'

// Perfiles de iluminacion por momento de la experiencia (los mismos campos que exporta el editor: k, d, shadow). Un perfil solo se aplica
// mientras esta activo (setLightProfile, que llama main.js segun el paso); el resto del tiempo las luces quedan como vienen de fabrica.
// Lo que se cambie a mano en el editor (guardado en el navegador) manda sobre el perfil.
const PROFILES = {
    intro: {
        // portada e introduccion (pasos 'home' y 'start')
        'cuarto-ventana': { k: 0 },
        'cuarto-foco': { k: 0.96, d: [0.95, 1.05, 1.2] },
        lampara: { k: 1.56 },
        'cuarto-techo': { k: 0.71 },
        'sala-lampara2': { k: 1.88 },
        'cuarto-cama': { shadow: true, k: 4, d: [-0.45, 0, 0] },
        'sala-sol1': { k: 0.35 },
    },
    final: {
        // "Despues" y "Cierre"
        'cuarto-ventana': { k: 0 },
        'cuarto-foco': { k: 0.96, d: [0.95, 1.05, 1.2] },
        lampara: { k: 1.56 },
        'cuarto-techo': { k: 0.71 },
        'sala-lampara2': { k: 1.88 },
        'cuarto-cama': { shadow: true, k: 4, d: [-0.45, 0, 0] },
        'sala-sol1': { k: 0.82 },
    },
}
let profile = null // perfil activo (nombre) o null
/** Activa un perfil de luces (o null para volver a las de fabrica). Barato: solo cambia una variable; updateRig() lo aplica. */
export const setLightProfile = (name) => {
    profile = name || null
}

const KEY = 'petalert.lights'
let saved = {}
try {
    if (EDIT_TOOLS) saved = JSON.parse(localStorage.getItem(KEY) || '{}') // (con las herramientas apagadas no se leen ajustes guardados: ver EDIT_TOOLS)
} catch (e) {}
const persist = () => {
    try {
        localStorage.setItem(KEY, JSON.stringify(saved))
    } catch (e) {}
}

export const rig = [] // { id, group, label, light, kind, orig, k, d, az, el, shadow, profile, aimed }

const _p = new THREE.Vector3()
const _t = new THREE.Vector3()
const _dir = new THREE.Vector3()

/** Multiplicador de intensidad que el editor le puso a una luz (1 si no se toco). */
export const rigK = (light) => light.userData.rigK ?? 1

const attached = (object) => {
    for (let o = object; o; o = o.parent) if (o.isScene) return true
    return false
}
/** Objetivo del foco en el espacio del mundo: si el objetivo cuelga de la propia luz, gira con ella. */
const targetIsChild = (light) => light.target && light.target.parent === light

/** Hacia donde apunta la luz, en grados: az (giro, 0 a 360) y el (altura: positivo = hacia abajo). */
export function getDirection(entry) {
    const { light } = entry
    light.updateWorldMatrix(true, false)
    light.target.updateWorldMatrix(true, false)
    light.getWorldPosition(_p)
    light.target.getWorldPosition(_t)
    _dir.subVectors(_t, _p).normalize()
    const el = THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(-_dir.y, -1, 1)))
    let az = THREE.MathUtils.radToDeg(Math.atan2(_dir.x, _dir.z))
    if (az < 0) az += 360
    return { az, el }
}

/** Apunta la luz a (az, el). El sol se mueve alrededor de su objetivo; un foco gira (o mueve su objetivo). */
export function setDirection(entry, az, el) {
    const { light } = entry
    const a = THREE.MathUtils.degToRad(az)
    const e = THREE.MathUtils.degToRad(el)
    _dir.set(Math.sin(a) * Math.cos(e), -Math.sin(e), Math.cos(a) * Math.cos(e))
    light.updateWorldMatrix(true, false)
    light.target.updateWorldMatrix(true, false)
    light.getWorldPosition(_p)
    light.target.getWorldPosition(_t)
    const dist = Math.max(0.5, _p.distanceTo(_t))
    if (entry.kind === 'dir' && !targetIsChild(light)) {
        // el sol: el objetivo se queda y la luz se mueve para que su rayo llegue desde la nueva direccion
        _p.copy(_t).addScaledVector(_dir, -dist)
        light.position.copy(light.parent ? light.parent.worldToLocal(_p) : _p)
    } else if (targetIsChild(light)) {
        light.lookAt(_p.clone().add(_dir)) // (las luces miran hacia su -z; three ya cuenta el giro del padre)
    } else {
        _t.copy(_p).addScaledVector(_dir, dist)
        light.target.position.copy(light.target.parent ? light.target.parent.worldToLocal(_t) : _t)
    }
    light.updateWorldMatrix(true, false)
}

export function setIntensity(entry, k) {
    entry.k = k
    entry.light.userData.rigK = k
    remember(entry, { k })
}
export function setOffset(entry, d) {
    entry.d = d.slice()
    entry.light.position.set(entry.orig.pos.x + d[0], entry.orig.pos.y + d[1], entry.orig.pos.z + d[2])
    remember(entry, { d: entry.d })
}
export function setShadow(entry, on) {
    entry.light.castShadow = on
    remember(entry, { shadow: on })
}
export function rememberDirection(entry, az, el) {
    entry.aimed = true
    remember(entry, { az, el })
}
// Lo que se edita se guarda en la etapa donde se esta: en el perfil activo ('final:id') o, fuera de el, en la luz sola ('id'). Asi lo que se ajusta al final no cambia la introduccion.
const slot = (id) => (profile ? profile + ':' + id : id)
function remember(entry, patch) {
    const key = slot(entry.id)
    saved[key] = { ...(saved[key] || {}), ...patch }
    persist()
}

export function resetEntry(entry) {
    const { light, orig } = entry
    light.position.copy(orig.pos)
    light.quaternion.copy(orig.quat)
    if (light.target && orig.targetPos) light.target.position.copy(orig.targetPos)
    light.castShadow = orig.shadow
    entry.k = 1
    entry.d = [0, 0, 0]
    light.userData.rigK = 1
    delete saved[slot(entry.id)] // (solo lo de esta etapa)
    persist()
    entry.aimed = false
    entry.profile = '?' // (updateRig vuelve a aplicar el perfil activo, si lo hay)
}
export function resetAll() {
    rig.forEach(resetEntry)
}

/** Los ajustes (solo lo que se cambio) listos para copiar. */
export function exportRig() {
    return JSON.stringify(saved, null, 2)
}

/** Registra una luz como editable. Devuelve la misma luz. */
export function registerRigLight(group, id, label, light) {
    const kind = light.isDirectionalLight ? 'dir' : light.isSpotLight ? 'spot' : light.isPointLight ? 'point' : light.isHemisphereLight ? 'hemi' : 'other'
    const entry = {
        id,
        group,
        label,
        light,
        kind,
        orig: {
            pos: light.position.clone(),
            quat: light.quaternion.clone(),
            targetPos: light.target ? light.target.position.clone() : null,
            shadow: light.castShadow,
        },
        k: 1,
        d: [0, 0, 0],
        profile: '?', // perfil que ya tiene aplicado ('?' = ninguno todavia: updateRig lo aplica cuando la luz ya esta en la escena)
        aimed: false, // si ya se le cambio la direccion
    }
    rig.push(entry)
    return light
}

/** Pone cada luz como toca en la etapa actual. Se llama cada cuadro, es barato: solo hace algo cuando cambia el perfil. */
export function updateRig() {
    for (const entry of rig) if (entry.profile !== profile && attached(entry.light)) applyProfile(entry)
}

/**
 * Ajustes de una luz en la etapa actual, de menor a mayor prioridad: lo que el usuario guardo para todas las etapas, el perfil de la
 * etapa y lo que el usuario guardo en esa etapa. (Sin perfil activo solo cuenta lo primero: la introduccion queda como la dejaste.)
 */
function applyProfile(entry) {
    const { light, orig } = entry
    const s = { ...saved[entry.id], ...(profile && PROFILES[profile]?.[entry.id]), ...(profile && saved[slot(entry.id)]) }
    entry.profile = profile
    entry.k = s.k ?? 1
    light.userData.rigK = entry.k
    entry.d = s.d ? s.d.slice() : [0, 0, 0]
    light.position.set(orig.pos.x + entry.d[0], orig.pos.y + entry.d[1], orig.pos.z + entry.d[2])
    light.castShadow = s.shadow ?? orig.shadow
    if (s.az != null && s.el != null) {
        setDirection(entry, s.az, s.el)
        entry.aimed = true
    } else if (entry.aimed) {
        light.quaternion.copy(orig.quat) // (la direccion de otra etapa vuelve a la de fabrica)
        if (light.target && orig.targetPos) light.target.position.copy(orig.targetPos)
        entry.aimed = false
    }
}
