/**
 * MINIJUEGO de la gata: huye entre tres escondites y queda acorralada.
 */
import { audio } from '../audio/audio.js'
import { lerp, rand } from '../core/utils.js'
import { player } from './player.js'
import { cat, catHideSpots, placePet, setPetMood } from '../three/characters.js'
import { openWardrobe } from '../three/thirdRoom.js'

const clamp01 = (x) => Math.min(1, Math.max(0, x))
const smooth = (x) => x * x * (3 - 2 * x)
/**
 * Altura de la gata durante una carrera: corre pegada al suelo y solo salta al llegar a un mueble (cama) o al bajarse de el,
 * en un tramo corto con un saltito, en vez de subir volando de un punto al otro.
 */
function dashHeight(o, s) {
    const ya = o.a[1]
    const yb = o.b[1]
    if (ya === yb) return ya
    const jump = Math.min(0.8, o.len * 0.4) // largo del tramo donde sube o baja (m)
    const fromA = s * o.len
    const toB = (1 - s) * o.len
    const k = yb > ya ? clamp01(1 - toB / jump) : clamp01(fromA / jump) // 0..1 dentro del tramo del salto
    const base = yb > ya ? ya + (yb - ya) * smooth(k) : ya + (yb - ya) * smooth(k)
    return base + 0.14 * Math.sin(Math.PI * k) * (k > 0 && k < 1 ? 1 : 0) // el saltito
}

export const catChase = {
    spot: 1,
    flees: 0,
    dash: null,
    cornered: false,
    route: [2, 0],
    final: 0, // donde queda acorralada al final de la ruta (0 armario, 1 cama, 2 escritorio)
    runSpeed: 4.5,
    scare: 2.2,
    reset() {
        this.flees = 0
        this.cornered = false
        this.dash = null
        // ruta distinta cada vez, y tambien el lugar donde queda acorralada (el armario 0, sobre la cama 1 o debajo del escritorio 2):
        // desde el escondite donde empieza huye a otros y el ultimo de la ruta es donde se queda
        const pickFinal = Math.random()
        this.final = pickFinal < 0.34 ? 0 : pickFinal < 0.67 ? 1 : 2
        const starts = [1, 2].filter((s) => s !== this.final)
        this.spot = starts[Math.floor(Math.random() * starts.length)]
        const other = this.spot === 1 ? 2 : 1
        const pick = Math.random()
        if (this.final === 0) this.route = pick < 0.4 ? [other, 0] : pick < 0.8 ? [other, this.spot, 0] : [0]
        else this.route = pick < 0.5 ? [this.final] : [0, this.final] // directo, o pasando antes por el armario
        this.runSpeed = rand(3.9, 5.2) // y corre mas rapido o mas despacio
        this.scare = rand(1.9, 2.6) // a que distancia huye
        openWardrobe(false, true)
        let e = catHideSpots[this.spot]
        placePet(cat, e[0], e[1], e[2], rand(0, 6), 0.6)
    },
    update(e) {
        let t = cat.userData
        // debajo del escritorio (0.37 m libres) se agacha para no meter la cabeza en el tablero; en el resto camina normal
        const wantY = !this.dash && this.spot === 2 ? 0.43 : 0.6
        cat.scale.y += (wantY - cat.scale.y) * Math.min(1, e * 10)
        if (this.dash) {
            let o = this.dash
            o.t += e / o.dur
            let s = Math.min(1, o.t)
            t.base.x = lerp(o.a[0], o.b[0], s)
            t.base.z = lerp(o.a[2], o.b[2], s)
            // corre pegada al suelo: sube de altura de forma pareja (sin salto) y el rebote del trote lo pone `walking`
            t.base.y = dashHeight(o, s)
            t.walking = true
            t.run = true
            cat.position.copy(t.base)
            cat.rotation.y = Math.atan2(o.b[0] - o.a[0], o.b[2] - o.a[2])
            if (s >= 1) {
                t.walking = false
                t.run = false
                this.dash = null
                this.spot = o.to
                if (this.cornered) {
                    if (this.final === 0) cat.rotation.y = 0 // dentro del armario, de lado (no atraviesa el fondo)
                    setPetMood(cat, {
                        wag: 0.2,
                        shiver: 0.7,
                        eyes: 1.4,
                    })
                }
            }
            return
        }
        if (this.cornered) return
        if (Math.hypot(player.pos.x - t.base.x, player.pos.z - t.base.z) < (this.scare || 2.2)) {
            const o = this.route[Math.min(this.flees, this.route.length - 1)]
            if (this.flees >= this.route.length - 1) this.cornered = true // este es su ultimo escondite
            this.flees++
            if (o === 0) openWardrobe(true) // el armario se abre para que se meta
            else if (this.spot === 0) openWardrobe(false) // sale del armario: se cierra
            let s = catHideSpots[this.spot],
                r = catHideSpots[o]
            this.dash = {
                len: Math.hypot(r[0] - s[0], r[2] - s[2]),
                a: s,
                b: r,
                t: 0,
                to: o,
                dur: Math.hypot(r[0] - s[0], r[2] - s[2]) / (o === 0 ? this.runSpeed * 0.72 : this.runSpeed), // corriendo por el suelo; al armario un poco mas despacio (da tiempo a que se abra)
            }
            audio.meow()
        }
    },
}
