// ---- Afuera de la casa: el mismo escenario con el que empieza el "Antes" (la calle y el porche) ----
const OUT_FROM = new THREE.Vector3(10.6, 1.65, -2.35) // la camara empieza lejos y se acerca despacio
const OUT_TO = new THREE.Vector3(8.4, 1.5, -2.2)
const OUT_LOOK = new THREE.Vector3(4.6, 1.0, -2)
const OUT_SECONDS = 28 // lo que tarda en acercarse
// Vista cercana (primeros auxilios y reto): el usuario y las mascotas quedan al centro y bien de cerca
const CLOSE_POS = new THREE.Vector3(7.5, 1.35, -1.85)
const CLOSE_LOOK = new THREE.Vector3(4.8, 0.85, -1.85)
// Mientras hay un titulo grande arriba, la camara va un poco mas alta: asi el personaje queda mas abajo y el texto no lo tapa
const CLOSE_LOW_POS = new THREE.Vector3(7.5, 1.7, -1.85)
const CLOSE_LOW_LOOK = new THREE.Vector3(4.8, 1.2, -1.85)
let closeLowered = false
let lastQuiz = -1
const SIDE_K = 0.2 // en la introduccion, cuanto se corre la escena hacia la derecha de la pantalla (fraccion del ancho): el texto va a la izquierda
let outsideTime = 0
let outsideFocus = 'side' // 'side': escena a la derecha, con la camara acercandose despacio; 'close': centrada y mas cerca
/** Camara de la introduccion (pos, look) segun el tiempo: se acerca despacio y se desplaza de lado (sin girar) lo justo para que el
 * usuario y las mascotas queden a la derecha de la pantalla (+z los manda a la derecha). */
const sidePose = () => {
    const pos = OUT_FROM.clone().lerp(OUT_TO, clamp(outsideTime / OUT_SECONDS, 0, 1))
    const width = 2 * Math.max(2, pos.x - PERSON_SPOT.x) * Math.tan((camera.fov * Math.PI) / 360) * (innerWidth / innerHeight)
    const shift = !isCompact() ? SIDE_K * width : 0
    return [pos.setZ(pos.z + shift), OUT_LOOK.clone().setZ(OUT_LOOK.z + shift)]
}
const outsideDrift = (dt) => {
    outsideTime += dt
    if (outsideFocus === 'close') cineGo(closeLowered ? CLOSE_LOW_POS : CLOSE_POS, closeLowered ? CLOSE_LOW_LOOK : CLOSE_LOOK, 1.3)
    else cineGo(...sidePose(), 1.6)
}

// El porche (medido en la escena): la casa queda en x ~ 3.4, la reja del frente en x = 6 (con la entrada en z -2.2 .. -1.4) y las rejas de
// los lados en z = -3 y z = 3. Las mascotas pasean solo dentro de este rectangulo, lejos de las rejas, y esquivan al usuario y entre si.
// (hacia la reja del frente quedan tapadas por el muro bajo, por eso se quedan del lado de la casa)
const PORCH = { x0: 4.0, x1: 5.0, z0: -2.65, z1: -0.35 }
const PERSON_SPOT = { x: 5.4, z: -2.05 }
const distToSegment = (px, pz, ax, az, bx, bz) => {
    const dx = bx - ax
    const dz = bz - az
    const k = clamp(((px - ax) * dx + (pz - az) * dz) / (dx * dx + dz * dz || 1), 0, 1)
    return Math.hypot(px - (ax + k * dx), pz - (az + k * dz))
}
const walkers = []
let lookTime = 0
/** Cada mascota espera un rato, escoge un lugar libre del porche y camina despacio hacia el, mirando a su alrededor al llegar. */
function wanderTick(dt) {
    lookTime += dt
    // el usuario tambien mira a su alrededor: gira el cuerpo despacio a un lado y a otro
    person.rotation.y = Math.PI / 2 + Math.sin(lookTime * 0.42) * 0.5 + Math.sin(lookTime * 0.17 + 1) * 0.2
    walkers.forEach((w, i) => {
        const a = w.pet.userData
        if (a.walking) return
        w.wait -= dt
        if (w.wait > 0) return
        const other = walkers[1 - i].pet.userData
        const op = other.path && other.path.length ? other.path[0] : other.base
        for (let tries = 0; tries < 16; tries++) {
            const x = PORCH.x0 + Math.random() * (PORCH.x1 - PORCH.x0)
            const z = PORCH.z0 + Math.random() * (PORCH.z1 - PORCH.z0)
            const far = Math.hypot(x - a.base.x, z - a.base.z) > 0.45
            const freeSpot = Math.hypot(x - PERSON_SPOT.x, z - PERSON_SPOT.z) > 0.75 && Math.hypot(x - op.x, z - op.z) > 0.6
            const freePath =
                distToSegment(PERSON_SPOT.x, PERSON_SPOT.z, a.base.x, a.base.z, x, z) > 0.6 &&
                distToSegment(other.base.x, other.base.z, a.base.x, a.base.z, x, z) > 0.45
            if (far && freeSpot && freePath) {
                walkPath(w.pet, [{ x, z, ry: Math.PI / 2 + (Math.random() * 2 - 1) * 1.5 }], w.speed)
                w.wait = 1.4 + Math.random() * 2.4
                return
            }
        }
        w.wait = 0.5
    })
}
const outsideTick = (dt) => {
    outsideDrift(dt)
    wanderTick(dt)
}

/** El usuario y sus mascotas, ya afuera, frente a la puerta cerrada, mirando hacia la camara. */
function placeOutside() {
    setDoorOpen(false, true)
    resetPerson()
    person.visible = true
    person.scale.setScalar(0.85)
    person.position.set(PERSON_SPOT.x, 0, PERSON_SPOT.z)
    person.rotation.y = Math.PI / 2
    placePet(dog, 4.7, 0, -2.45, Math.PI / 2 - 0.3, 0.5)
    placePet(cat, 4.6, 0, -1.0, Math.PI / 2 + 0.3, 0.48)
    dog.visible = cat.visible = true
    setPetMood(dog, { wag: 1.8, eyes: 1.05 })
    setPetMood(cat, { wag: 1.4, eyes: 1.05 })
    lookTime = 0
    walkers.length = 0
    walkers.push({ pet: dog, wait: 0.8, speed: 0.85 }, { pet: cat, wait: 1.9, speed: 0.7 })
    state.curExit = () => {
        resetPerson()
        walkers.length = 0
        dog.visible = cat.visible = true
    }
}

steps.despIntro = {
    stage: 3,
    w: 0.05,
    prev: 'sizePick',
    next: 'guide',
    enter() {
        setCameraMode('cine')
        outsideFocus = 'side'
        outsideTime = 0
        cineSet(...sidePose())
        placeOutside()
        state.curTick = outsideTick
        // la misma decoracion del texto de cierre del "Antes": etiqueta, titulo y texto que aparecen uno tras otro
        const text = content.despIntro
        const el = showDynamic(
            '<div class="closefx quick"><span class="kick">' +
                text.kick +
                '</span><h2>' +
                text.title +
                '</h2><p>' +
                text.text +
                '</p><button class="btn big cta">' +
                text.cta +
                '</button></div>',
        )
        qs('.cta', el).addEventListener('click', () => {
            audio.blip()
            goTo('guide')
        })
    },
}

// El kit 3D (la misma maleta de la casa) sube desde abajo de la pantalla: va pegado a la camara, abajo al centro, y la hoja sale de el
const KIT_SCALE = 0.2
const KIT_REST = new THREE.Vector3(0, -0.36, -1) // en el espacio de la camara (m): se ve solo la parte de arriba, bajo la hoja
const KIT_HIDDEN = -0.42 // cuanto mas abajo empieza (y termina al cerrarse)
const easeOut = (k) => 1 - (1 - Math.min(1, Math.max(0, k))) ** 3
/** Pone el kit 3D frente a la camara. Devuelve { tick(dt), close(), dispose() }. */
function createGuideKit() {
    const bag = createBackpack()
    bag.scale.setScalar(KIT_SCALE)
    const holder = new THREE.Group()
    holder.add(bag)
    bag.rotation.x = 0.35 // inclinada hacia la camara para verle la tapa
    mainScene.add(holder)
    let time = 0
    let closeAt = null
    const offset = new THREE.Vector3()
    return {
        tick(dt) {
            time += dt
            // sube con rebote suave, abre la tapa cuando sale la hoja y, al cerrarse, la cierra y baja
            let rise = easeOut(time / 1.5)
            let lid = easeOut((time - 1.2) / 1.2)
            if (closeAt != null) {
                const c = time - closeAt
                lid *= 1 - easeOut(c / 0.8)
                rise *= 1 - easeOut((c - 1.1) / 1.1)
            }
            setBagLid(bag, lid)
            offset.copy(KIT_REST)
            offset.y += KIT_HIDDEN * (1 - rise)
            holder.position.copy(offset).applyQuaternion(camera.quaternion).add(camera.position)
            holder.quaternion.copy(camera.quaternion)
        },
        close() {
            if (closeAt == null) closeAt = time
        },
        dispose() {
            holder.removeFromParent()
        },
    }
}

steps.guide = {
    stage: 3,
    w: 0.4,
    prev: 'despIntro',
    next: 'quiz',
    enter() {
        // sigue en el mismo lugar de afuera: el kit sale de abajo y de el sale una hoja con los primeros auxilios
        const wasCine = state.mode === 'cine'
        setCameraMode('cine')
        outsideFocus = 'close' // ya con el kit, la camara se centra y se acerca a los personajes
        if (!wasCine) {
            outsideTime = 0
            cineSet(...sidePose())
        } else cineStart()
        placeOutside()
        const guideText = content.guide
        let kit = null
        state.curTick = (dt) => {
            outsideTick(dt)
            kit?.tick(dt)
        }
        // primero un titulo y subtitulo (arriba, como las demas indicaciones): es hora de usar el kit, pero como usarlo bien
        closeLowered = true
        showStopLabel(guideText.pre.t, guideText.pre.s, true)
        const timers = []
        const leave = state.curExit
        state.curExit = () => {
            timers.forEach(clearTimeout)
            hideStopLabel()
            closeLowered = false
            kit?.dispose()
            leave?.()
        }
        timers.push(
            setTimeout(() => {
                if (state.cur !== 'guide') return
                hideStopLabel()
                closeLowered = false
                kit = createGuideKit()
                openSheet()
            }, 4200),
        )

        // La hoja: primero se escoge a quien ayudar (perro o gato) y de ahi salen, una por una, sus indicaciones: un dibujo grande y
        // una frase corta, con Regresar y Continuar (en la ultima, Listo, que vuelve a la eleccion).
        const done = new Set()
        const openSheet = () => {
            const root = showDynamic(
                '<div class="kitrise"><div class="sheet" role="document"><div id="gView" class="gview"></div></div></div>',
            )
            const view = qs('#gView', root)
            audio.whoosh()
            timers.push(setTimeout(() => state.cur === 'guide' && audio.ding(), 1500))
            const swap = (html) => {
                view.classList.remove('swap')
                view.innerHTML = html
                void view.offsetWidth // reinicia el fundido
                view.classList.add('swap')
            }
            const showChoice = () => {
                const both = done.size === guideText.tabs.length
                swap(
                    '<h2 class="gpick">' +
                        guideText.pick +
                        '</h2><div class="gpets">' +
                        guideText.tabs
                            .map(
                                (tab, i) =>
                                    '<button class="gpet' +
                                    (done.has(i) ? ' seen' : '') +
                                    '" data-i="' +
                                    i +
                                    '">' +
                                    '<img class="pet" src="' +
                                    import.meta.env.BASE_URL +
                                    (tab.id === 'cat' ? 'icono-gato.png' : 'icono-perro.png') +
                                    '" alt="" draggable="false">' +
                                    '<b>' +
                                    tab.label +
                                    '</b><small>' +
                                    tab.intro +
                                    '</small><i class="tick" aria-hidden="true"></i></button>',
                            )
                            .join('') +
                        '</div><div class="gfoot"><p id="gMsg">' +
                        (both ? guideText.done : guideText.hint) +
                        '</p><button class="btn' +
                        (both ? ' coral' : ' ghost') +
                        '" id="gNext">Continuar</button></div>',
                )
                qsa('.gpet', view).forEach((button) =>
                    button.addEventListener('click', () => {
                        audio.blip()
                        showTip(+button.dataset.i, 0)
                    }),
                )
                qs('#gNext', view).addEventListener('click', finish)
            }
            const showTip = (petIndex, n) => {
                const tab = guideText.tabs[petIndex]
                const tip = tab.steps[n]
                const last = n === tab.steps.length - 1
                swap(
                    '<header class="ghead">' +
                        petFaces[tab.id] +
                        '<h2>' +
                        tab.label +
                        '</h2><span class="gdots">' +
                        tab.steps.map((s, k) => '<i' + (k === n ? ' class="on"' : k < n ? ' class="past"' : '') + '></i>').join('') +
                        '</span></header><div class="gtip"><figure>' +
                        illustrations[tip.ill]() +
                        '</figure><h3>' +
                        tip.t +
                        '</h3><p>' +
                        tip.d +
                        '</p></div><div class="gfoot"><button class="btn ghost" data-a="prev">Regresar</button><button class="btn' +
                        (last ? ' coral' : '') +
                        '" data-a="next">' +
                        (last ? 'Listo' : 'Continuar') +
                        '</button></div>',
                )
                qs('[data-a=prev]', view).addEventListener('click', () => {
                    audio.blip()
                    if (n === 0) showChoice()
                    else showTip(petIndex, n - 1)
                })
                qs('[data-a=next]', view).addEventListener('click', () => {
                    audio.blip()
                    if (!last) return showTip(petIndex, n + 1)
                    done.add(petIndex)
                    audio.ding()
                    showChoice()
                })
            }
            // al continuar, la hoja se cierra y se mete otra vez en el kit, que baja; entonces sigue la retroalimentacion
            let closing = false
            const finish = () => {
                if (closing) return
                closing = true
                audio.blip()
                qs('.kitrise', root).classList.add('closing')
                kit.close()
                timers.push(setTimeout(() => state.cur === 'guide' && goTo('quiz'), 2300))
            }
            showChoice()
        }
    },
}
/**
 * RETROALIMENTACION: en el mismo escenario de afuera (desenfocado). La pregunta se escribe como a maquina y,
 * cuando termina, las tarjetas con las respuestas aparecen una despues de la otra, centradas en la pagina.
 */
steps.quiz = {
    stage: 3,
    w: 0.8,
    prev: 'guide',
    next: 'close',
    enter() {
        const wasCine = state.mode === 'cine'
        setCameraMode('cine')
        outsideFocus = 'close'
        if (!wasCine) {
            outsideTime = 0
            cineSet(CLOSE_POS, CLOSE_LOOK)
        } else cineStart()
        placeOutside()
        state.curTick = outsideTick
        const quizText = content.quiz
        // hay varias preguntas pero solo sale una por experiencia: al azar y distinta a la de la vez anterior
        if (session.quizQ == null) {
            let pick = Math.floor(Math.random() * quizText.questions.length)
            if (pick === lastQuiz) pick = (pick + 1) % quizText.questions.length
            session.quizQ = lastQuiz = pick
        }
        const question = quizText.questions[session.quizQ]
        const timers = []
        const leave = state.curExit
        state.curExit = () => {
            timers.forEach(clearTimeout)
            hideStopLabel()
            closeLowered = false
            document.body.classList.remove('blurred')
            if (leave) leave()
        }
        // antes de la pregunta: titulo y subtitulo (la camara va un poco mas arriba para que el texto no tape al personaje)
        closeLowered = true
        showStopLabel(quizText.pre.t, quizText.pre.s, true)
        timers.push(
            setTimeout(() => {
                if (state.cur !== 'quiz') return
                hideStopLabel()
                closeLowered = false
                document.body.classList.add('blurred')
                showQuiz()
            }, 3600),
        )
        const letters = ['a', 'b', 'c']
        const showQuiz = () => {
        const order = shuffle([0, 1, 2])
        const root = showDynamic(
            '<div class="quiz"><div class="qcard card"><h2 class="qtype" aria-label="' +
                question.q +
                '"></h2><p class="qhint">' +
                quizText.hint +
                '</p></div><div class="flips">' +
                order
                    .map((index, position) => {
                        const option = question.opts[index]
                        return (
                            '<button class="flip" data-ok="' +
                            (option.ok ? 1 : 0) +
                            '" aria-label="Opción ' +
                            letters[position] +
                            '"><span class="face front"><b>' +
                            letters[position] +
                            '</b><span>' +
                            option.text +
                            '</span></span><span class="face back ' +
                            (option.ok ? 'ok' : 'no') +
                            '"><strong>' +
                            (option.ok ? quizText.good : quizText.bad) +
                            '</strong><span>' +
                            option.fb +
                            '</span></span></button>'
                        )
                    })
                    .join('') +
                '</div><div class="quizfoot"><button class="btn" id="qNext" disabled>' +
                quizText.cta +
                '</button><small id="qMsg">' +
                quizText.wait +
                '</small></div></div>',
        )

        // la pregunta aparece con un fundido; luego la ayuda y las tarjetas, una tras otra
        const title = qs('.qtype', root)
        title.textContent = question.q
        title.classList.add('done')
        timers.push(setTimeout(() => qs('.qhint', root).classList.add('show'), 700))
        qsa('.flip', root).forEach((card, i) =>
            timers.push(
                setTimeout(() => {
                    card.classList.add('in')
                    audio.blip()
                }, 1100 + i * 650),
            ),
        )
        timers.push(setTimeout(() => qs('.quizfoot', root).classList.add('in'), 1100 + 3 * 650))

        qsa('.flip', root).forEach((card) =>
            card.addEventListener('click', () => {
                if (card.classList.contains('flipped')) return
                card.classList.add('flipped')
                if (card.dataset.ok === '1') {
                    audio.ok()
                    qs('#qNext', root).disabled = false
                    qs('#qMsg', root).textContent = ''
                    cat.userData.hop = 1
                    dog.userData.hop = 1
                } else {
                    audio.no()
                }
            }),
        )
        qs('#qNext', root).addEventListener('click', () => {
            audio.blip()
            transitionTo('close')
        })
        }
    },
}

