/**
 * LINEA DE TIEMPO (arriba): una linea como la que va debajo de "PetAlert" en el inicio. Recta al principio, irregular y fuerte en el
 * "Durante" (el sismo), que se va calmando a lo largo del "Despues" hasta quedar recta en el "Cierre". Se llena con el progreso.
 */
import { clamp, damp, qs, qsa } from '../core/utils.js'

const MID = 15 // altura de la linea central (el viewBox mide 30 de alto)
const WIDTH = 460 // ancho del viewBox del svg
// Altura de las irregularidades segun la posicion (x del viewBox): recta en el inicio, un temblor leve al final del "Antes", el sismo
// fuerte en el "Durante" y una calma gradual a lo largo del "Despues"; el "Cierre" vuelve a quedar recto
const ENVELOPE = [
    [0, 0],
    [138, 0],
    [160, 1.6],
    [182, 3.2],
    [196, 13.5],
    [240, 14],
    [262, 10.5],
    [290, 6],
    [320, 3],
    [346, 1.2],
    [362, 0],
    [WIDTH, 0],
]
const amplitudeAt = (x) => {
    for (let i = 1; i < ENVELOPE.length; i++) {
        const [x1, y1] = ENVELOPE[i]
        if (x <= x1) {
            const [x0, y0] = ENVELOPE[i - 1]
            return y0 + ((y1 - y0) * (x - x0)) / (x1 - x0)
        }
    }
    return 0
}
// vertices [x, y]: separacion y altura irregulares (con una semilla fija, para que siempre salga igual) dentro de esa envolvente
const buildShape = () => {
    let seed = 7
    const rand = () => (seed = (seed * 16807) % 2147483647) / 2147483647
    const shape = [[0, MID]]
    let x = 138
    let up = true
    for (;;) {
        x += 3.5 + rand() * 4.5
        if (x >= 358) break
        const amp = amplitudeAt(x) * (0.45 + 0.55 * rand())
        shape.push([+x.toFixed(1), +(MID + (up ? -amp : amp)).toFixed(1)])
        up = !up
    }
    shape.push([362, MID], [WIDTH, MID])
    return shape
}
const SHAPE = buildShape()
const seismo = {
    len: 1,
    p: 0,
    tp: 0,
    cum: [0],
}
export function buildSeismo() {
    const path = SHAPE.map(([x, y], i) => (i ? 'L' : 'M') + x + ' ' + y).join(' ')
    seismo.cum = [0] // largo acumulado de la linea hasta cada vertice: asi el avance coincide con las etapas
    for (let i = 1; i < SHAPE.length; i++) {
        seismo.cum.push(seismo.cum[i - 1] + Math.hypot(SHAPE[i][0] - SHAPE[i - 1][0], SHAPE[i][1] - SHAPE[i - 1][1]))
    }
    qs('#sBase').setAttribute('d', path)
    qs('#sFill').setAttribute('d', path)
    seismo.len = qs('#sFill').getTotalLength()
    qs('#sFill').style.strokeDasharray = seismo.len
    qs('#sFill').style.strokeDashoffset = seismo.len
    drawnP = NaN
}
let sFill = null // (los elementos se buscan una sola vez: antes se buscaban 4 veces por cuadro)
let sDot = null
let drawnP = NaN // el avance que se dibujo la ultima vez: si no cambio, no se toca el SVG (getPointAtLength fuerza el calculo de la linea)
export function updateSeismo(dt) {
    seismo.p = damp(seismo.p, seismo.tp, 3, dt)
    if (Math.abs(seismo.p - drawnP) < 0.0002) return
    drawnP = seismo.p
    sFill ||= qs('#sFill')
    sDot ||= qs('#sDot')
    // el avance (0 a 1) es horizontal: se convierte al largo recorrido sobre la linea
    const x = clamp(seismo.p, 0, 1) * WIDTH
    let i = 0
    while (i < SHAPE.length - 2 && x > SHAPE[i + 1][0]) i++
    const k = clamp((x - SHAPE[i][0]) / (SHAPE[i + 1][0] - SHAPE[i][0]), 0, 1)
    const length = seismo.cum[i] + (seismo.cum[i + 1] - seismo.cum[i]) * k
    const scale = seismo.len / seismo.cum[SHAPE.length - 1]
    sFill.style.strokeDashoffset = seismo.len - length * scale
    const a = sFill.getPointAtLength(clamp(length * scale, 0.001, seismo.len))
    sDot.setAttribute('cx', a.x)
    sDot.setAttribute('cy', a.y)
}
export function setStage(stage, weight) {
    seismo.tp = (stage + weight) / 5
    qsa('#stages button').forEach((a, o) => {
        a.classList.toggle('on', o === stage)
        a.setAttribute('aria-current', o === stage ? 'step' : 'false')
    })
    qs('#seismo').setAttribute(
        'aria-label',
        'Progreso: etapa ' + ['Inicio', 'Antes', 'Durante', 'Después', 'Cierre'][stage],
    )
}
