/**
 * CONTORNO DE LUZ DE LAS MASCOTAS: en lugar de un ovalo de luz sobre Cacao y Nube, la propia silueta de la mascota brilla (un borde
 * dorado electrico que se mueve un poco). Se arma con "cascarones" invertidos: una copia de cada malla con huesos, inflada a lo largo
 * de su normal suavizada y dibujada por detras, en tres capas (nucleo brillante, aureola y resplandor ancho).
 *
 *   trackPetGlow(objeto, element, { seen })   la mascota (o cualquier objeto, p. ej. la mochila del kit) brilla mientras `element` (el boton clicable) este en pantalla; mas fuerte al pasar
 *                                          el cursor; verde si seen() devuelve true
 *   updatePetGlows(dt, time)               se llama cada cuadro (quakeEffects.js)
 */
import * as THREE from 'three'
import { damp } from '../core/utils.js'
import { showScene } from './renderer.js'

const LAYERS = [
    // varias capas muy transparentes, cada una mas ancha: el borde se difumina poco a poco (sin linea dura)
    { grow: 1, color: '#ffe27a', opacity: 0.28 },
    { grow: 2, color: '#ffcf4a', opacity: 0.18 },
    { grow: 3.4, color: '#ffbb2e', opacity: 0.125 },
    { grow: 5.2, color: '#ffc04d', opacity: 0.078 },
    { grow: 7.4, color: '#ffd37a', opacity: 0.042 },
]
const GREEN = ['#a6ffd0', '#7cecb0', '#4fd897', '#6fe0a8', '#a0efc4']
// colores ya creados: antes se creaba un THREE.Color nuevo por capa y por cuadro, y el recolector de basura congelaba la imagen a ratos
const LAYER_COLORS = LAYERS.map((layer) => new THREE.Color(layer.color))
const GREEN_COLORS = GREEN.map((color) => new THREE.Color(color))
const uniforms = { uTime: { value: 0 } }

// Intensidad de los resplandores (0 = apagado, 1 = normal, 2 = el doble): se edita en vivo con F2 (ui/walkTuner.js) y se guarda en el navegador
// (el aura se hizo bastante mas fuerte: antes intensity 0.25 y bag 0.2 apenas se veian sobre fondos claros; la clave del navegador cambio a
// 'petalert.glow2' para que ajustes viejos guardados con F2 no la tapen)
export const GLOW_DEFAULT = { petFill: 0.3, intensity: 0.3, bag: 0.28, kit: 0, kitLight: 0.9, bagLight: 0.6 } // kitLight: luz propia del objeto del kit que se presenta (solo a el) // intensity: contorno de las mascotas; kit: halo amarillo de los objetos del kit
export const glowTuning = { ...GLOW_DEFAULT }
try {
    Object.assign(glowTuning, JSON.parse(localStorage.getItem('petalert.glow2') || '{}'))
} catch (e) {}
export const saveGlowTuning = () => {
    try {
        localStorage.setItem('petalert.glow2', JSON.stringify(glowTuning))
    } catch (e) {}
}

/** Normales suavizadas (las de los vertices que estan en el mismo lugar se promedian): el cascaron no se abre en las aristas del modelo. */
const smoothCache = new WeakMap()
function outlineGeometry(source) {
    if (smoothCache.has(source)) return smoothCache.get(source)
    const geometry = source.clone()
    const pos = geometry.attributes.position
    const nor = geometry.attributes.normal
    const sums = new Map()
    const key = (i) => Math.round(pos.getX(i) * 2000) + ',' + Math.round(pos.getY(i) * 2000) + ',' + Math.round(pos.getZ(i) * 2000)
    for (let i = 0; i < pos.count; i++) {
        const k = key(i)
        const s = sums.get(k) || [0, 0, 0]
        s[0] += nor.getX(i)
        s[1] += nor.getY(i)
        s[2] += nor.getZ(i)
        sums.set(k, s)
    }
    const smooth = new Float32Array(pos.count * 3)
    for (let i = 0; i < pos.count; i++) {
        const s = sums.get(key(i))
        const len = Math.hypot(s[0], s[1], s[2]) || 1
        smooth.set([s[0] / len, s[1] / len, s[2] / len], i * 3)
    }
    geometry.setAttribute('aSmooth', new THREE.BufferAttribute(smooth, 3))
    geometry.computeBoundingSphere()
    smoothCache.set(source, geometry)
    return geometry
}

function outlineMaterial(color, opacity, thickness) {
    const material = new THREE.MeshBasicMaterial({
        color,
        side: THREE.BackSide,
        transparent: true,
        opacity,
        depthWrite: false,
        toneMapped: false,
        fog: false,
    })
    material.userData.base = opacity
    material.onBeforeCompile = (shader) => {
        shader.uniforms.uTime = uniforms.uTime
        shader.uniforms.uThick = { value: thickness }
        material.userData.thick = shader.uniforms.uThick
        shader.vertexShader =
            'attribute vec3 aSmooth;\nuniform float uTime;\nuniform float uThick;\n' +
            shader.vertexShader.replace(
                '#include <skinning_vertex>',
                `#include <skinning_vertex>
                vec3 smoothN = aSmooth;
                #ifdef USE_SKINNING
                    smoothN = (skinMatrix * vec4(smoothN, 0.0)).xyz;
                #endif
                float jig = 0.88 + 0.28 * (0.5 + 0.5 * sin(dot(position, vec3(91.0, 67.0, 53.0)) + uTime * 11.0));
                transformed += normalize(smoothN) * uThick * jig;`,
            )
    }
    return material
}

const entries = []

function buildGlow(root) {
    const parts = []
    // grosor del contorno: el mismo en todo el objeto (en metros del mundo): ~2 % de su tamano (antes 1.4 %: se perdia en pantallas chicas)
    root.updateMatrixWorld(true)
    const size = new THREE.Box3().setFromObject(root).getSize(new THREE.Vector3())
    const worldThick = Math.max(size.x, size.y, size.z) * 0.015
    const pos = new THREE.Vector3()
    const quat = new THREE.Quaternion()
    const scale = new THREE.Vector3()
    const meshes = []
    root.traverse((mesh) => mesh.isMesh && !mesh.userData.isHull && mesh.geometry.attributes.normal && meshes.push(mesh))
    meshes.forEach((mesh) => {
        const skinned = mesh.isSkinnedMesh && mesh.skeleton
        const geometry = outlineGeometry(mesh.geometry)
        mesh.matrixWorld.decompose(pos, quat, scale)
        const unit = worldThick / ((scale.x + scale.y + scale.z) / 3 || 1) // (en unidades del propio modelo)
        LAYERS.forEach((layer, i) => {
            const material = outlineMaterial(layer.color, layer.opacity, unit * layer.grow)
            const hull = skinned ? new THREE.SkinnedMesh(geometry, material) : new THREE.Mesh(geometry, material)
            if (skinned) hull.bind(mesh.skeleton, mesh.bindMatrix)
            hull.frustumCulled = false
            hull.renderOrder = -2 + i // por detras del objeto
            hull.layer = i
            hull.unit = unit
            hull.source = mesh
            hull.userData.isHull = true
            // la medalla (placa con el nombre) brilla la mitad: es una pieza pequena y su contorno se sumaba al del collar
            for (let o = mesh; o; o = o.parent) {
                if (/placa|medalla/i.test(o.name)) hull.userData.medal = true
                if (o === root) break
            }
            mesh.parent.add(hull)
            parts.push(hull)
        })
    })
    return parts
}
export function trackPetGlow(object, element, { seen = () => false, tuning = 'intensity' } = {}) {
    // tuning: que control de glowTuning manda en la intensidad de este brillo ('intensity' = mascotas, 'bag' = el maletin del kit)
    entries.push({ pet: object, element, seen, tuning, parts: null, k: 0, green: 0 })
}

/**
 * Las mascotas se auto-iluminan un poco (petFill, editable con F2): se aclaran las sombras de su cuerpo (debajo de la cabeza, las patas) y se ven
 * mejor contra el fondo. La luz propia es del color de cada pieza (pelo, collar, nariz...), no blanca: al shader se le suma su propio color
 * (con el color de los vertices y la textura) multiplicado por petFill.
 */
const litPets = []
const fillOf = new WeakMap() // el uniform de luz propia de cada mascota (en la escena de cierre ya hay luces propias: ahi no se suma nada)
let fillCount = 0
export function lightPets(list) {
    litPets.push(...list)
}
function patchPetMaterial(material, uniform) {
    material.onBeforeCompile = (shader) => {
        shader.uniforms.petFill = uniform
        shader.fragmentShader = shader.fragmentShader
            .replace('#include <common>', '#include <common>\nuniform float petFill;')
            .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\ntotalEmissiveRadiance += diffuseColor.rgb * petFill;')
    }
    const key = 'petFill-' + ++fillCount // (una clave por material: ver interiorLook.js)
    material.customProgramCacheKey = () => key
    material.needsUpdate = true
}
const fillChecked = new WeakMap() // cuando se reviso por ultima vez si hay mallas nuevas por parchar
function updatePetFill(pet, time) {
    let uniform = fillOf.get(pet)
    if (!uniform) fillOf.set(pet, (uniform = { value: 0 }))
    let top = pet
    while (top.parent) top = top.parent
    uniform.value = top === showScene ? 0 : (glowTuning.petFill ?? 0) * 0.5
    // recorrer todos los huesos y mallas cada cuadro era caro: basta con revisar si hay mallas nuevas cada medio segundo
    if (time - (fillChecked.get(pet) ?? -1) < 0.5) return
    fillChecked.set(pet, time)
    pet.traverse((mesh) => {
        if (!mesh.isMesh || mesh.userData.isHull || !mesh.material || mesh.userData.fillPatched) return
        mesh.userData.fillPatched = true
        const list = Array.isArray(mesh.material) ? mesh.material : [mesh.material]
        const copies = list.map((m) => {
            if (!m.isMeshStandardMaterial) return m
            const copy = m.clone() // (cada pieza usa sus propios materiales)
            patchPetMaterial(copy, uniform)
            return copy
        })
        mesh.material = Array.isArray(mesh.material) ? copies : copies[0]
    })
}
export function updatePetGlows(dt, time) {
    uniforms.uTime.value = time
    litPets.forEach((pet) => pet && updatePetFill(pet, time))
    for (let n = entries.length - 1; n >= 0; n--) {
        const e = entries[n]
        const on = e.element.isConnected && !e.element.hidden
        if (!on && e.k < 0.01) {
            // ya se apago: se quita todo (si el boton sigue en el DOM pero oculto, se vuelve a armar cuando aparezca)
            e.parts?.forEach((hull) => {
                hull.removeFromParent()
                hull.material.dispose()
            })
            e.parts = null
            if (!e.element.isConnected) entries.splice(n, 1)
            continue
        }
        const hover = on && e.element.matches(':hover')
        e.k = damp(e.k, on ? (hover ? 1.35 : 1) : 0, 6, dt)
        e.green = damp(e.green, on && e.seen() ? 1 : 0, 6, dt)
        if (on && !e.parts) e.parts = buildGlow(e.pet)
        if (!e.parts) continue
        const pulse = 0.92 + 0.08 * Math.sin(time * 2.4)
        e.parts.forEach((hull) => {
            const src = hull.source
            hull.position.copy(src.position)
            hull.quaternion.copy(src.quaternion)
            hull.scale.copy(src.scale)
            hull.visible = src.visible
            const layer = LAYERS[hull.layer]
            hull.material.color.copy(LAYER_COLORS[hull.layer]).lerp(GREEN_COLORS[hull.layer], e.green)
            hull.material.opacity = Math.min(1, hull.material.userData.base * e.k * pulse * (glowTuning[e.tuning] ?? glowTuning.intensity) * (hull.userData.medal ? 0.5 : 1))
            if (hull.material.userData.thick) hull.material.userData.thick.value = hull.unit * layer.grow * (hover ? 1.35 : 1)
        })
    }
}

/**
 * Luz propia de un objeto (un objeto del kit que se presenta, o el maletin al abrirse y cerrarse) (solo de el, no de la sala): el objeto se auto-ilumina un poco (k de 0 a 1; sus colores y
 * su textura brillan, sin lavar el dibujo), asi se ve mejor contra el fondo. Cada objeto usa sus propios materiales (se copian la primera vez).
 */
export function setObjectLight(item, k) {
    item.userData.lit = k
    if (k < 0.002 && !item.userData.litOn) return
    item.userData.litOn = k >= 0.002
    item.traverse((mesh) => {
        if (!mesh.isMesh || !mesh.material) return
        const list = Array.isArray(mesh.material) ? mesh.material : [mesh.material]
        if (!mesh.userData.litCopy) {
            mesh.userData.litCopy = true
            const copies = list.map((m) => {
                if (!m.isMeshStandardMaterial) return m
                const copy = m.clone()
                // clone() duplica tambien los planos de recorte: la copia dejaba de seguir al plano de la boca de la mochila (kitGlb.js) y
                // los objetos del kit, ya vistos, se salian de la mochila al guardarse. Se vuelve a usar el mismo plano.
                copy.clippingPlanes = m.clippingPlanes
                return copy
            })
            mesh.material = Array.isArray(mesh.material) ? copies : copies[0]
        }
        ;(Array.isArray(mesh.material) ? mesh.material : [mesh.material]).forEach((m) => {
            if (!m.isMeshStandardMaterial) return
            if (m.map) m.emissiveMap = m.map // el dibujo (etiquetas, tarjetas) brilla con sus propios colores
            m.emissive.set(m.map ? '#ffffff' : m.color)
            m.emissiveIntensity = k * 0.55
        })
    })
}
