/**
 * EDITOR DE ILUMINACION (tecla L): abre un panel con las luces de la escena que se esta viendo y deja cambiar de cada una su
 * intensidad, hacia donde apunta (giro y altura), su posicion y si proyecta sombra. Al abrir una luz se dibuja una guia en la
 * escena (flecha del sol, cono del foco, esfera de la lampara) para ver donde esta y hacia donde alumbra.
 *
 * Los cambios se ven al instante y se guardan en este navegador (ver three/lightRig.js). "Copiar ajustes" deja el JSON en el
 * portapapeles para pasarlo y dejarlo como valores por defecto; "Restablecer" vuelve a las luces de siempre.
 */
import * as THREE from 'three'
import { EDIT_TOOLS } from '../config.js'
import { state } from '../core/state.js'
import {
    exportRig,
    getDirection,
    rememberDirection,
    resetAll,
    resetEntry,
    rig,
    setDirection,
    setIntensity,
    setOffset,
    setShadow,
} from '../three/lightRig.js'

const GROUP_NAMES = { mundo: 'Casa (introduccion y orbita)', sala: 'Sala', cuarto: 'Cuarto' }
const KIND_NAMES = { dir: 'direccional', spot: 'foco', point: 'puntual', hemi: 'ambiente' }

const CSS = `
#lightEd{position:fixed;left:12px;top:12px;bottom:12px;width:310px;z-index:80;display:none;flex-direction:column;background:rgba(14,20,34,.93);color:#eef3ff;font:12px/1.35 system-ui,sans-serif;border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,.35);backdrop-filter:blur(6px)}
#lightEd.open{display:flex}
#lightEd header{padding:10px 12px 6px;font-weight:700;font-size:13px}
#lightEd header small{display:block;font-weight:400;color:#9fb0d0;margin-top:2px}
#lightEd .list{overflow:auto;padding:0 8px;flex:1}
#lightEd details{border-top:1px solid rgba(255,255,255,.1);padding:4px 4px 6px}
#lightEd summary{cursor:pointer;padding:4px 0;font-weight:600;list-style:none;display:flex;justify-content:space-between;gap:8px}
#lightEd summary::-webkit-details-marker{display:none}
#lightEd summary span:last-child{color:#ffc986;font-weight:500}
#lightEd .row{display:grid;grid-template-columns:78px 1fr 44px;gap:6px;align-items:center;margin:3px 0}
#lightEd .row label{color:#b9c6e2}
#lightEd .row output{text-align:right;color:#ffc986}
#lightEd input[type=range]{width:100%;accent-color:#ff8a6f}
#lightEd .sec{margin:8px 0 2px;color:#8fa2c9;font-size:11px;text-transform:uppercase;letter-spacing:.04em}
#lightEd .grp{padding:8px 4px 2px;color:#8fa2c9;font-size:11px;text-transform:uppercase;letter-spacing:.04em}
#lightEd .btns{display:flex;gap:6px;padding:8px 12px 12px;flex-wrap:wrap}
#lightEd button{background:#2a3a5c;color:#fff;border:0;border-radius:8px;padding:6px 10px;cursor:pointer;font:inherit}
#lightEd button:hover{background:#3a4f7c}
#lightEd .none{padding:14px 6px;color:#9fb0d0}
`

let panel = null
let list = null
let open = false
let signature = ''
let frame = 0
let helper = null
let helperOwner = null

const visibleInTree = (object) => {
    for (let o = object; o; o = o.parent) {
        if (o.visible === false) return false
        if (o.isScene) return o === state.scene
    }
    return false
}
const shown = () => rig.filter((entry) => visibleInTree(entry.light))

function build() {
    const style = document.createElement('style')
    style.textContent = CSS
    document.head.appendChild(style)
    panel = document.createElement('div')
    panel.id = 'lightEd'
    panel.innerHTML =
        '<header>Iluminacion<small>L abre y cierra. Los cambios se guardan en este navegador. Abre una luz para ver su guia en la escena.</small></header><div class="list"></div>' +
        '<div class="btns"><button data-act="copy">Copiar ajustes</button><button data-act="reset">Restablecer todo</button><button data-act="close">Cerrar</button></div>'
    list = panel.querySelector('.list')
    panel.addEventListener('click', (event) => {
        const act = event.target.dataset?.act
        if (act === 'close') toggle(false)
        else if (act === 'reset') {
            resetAll()
            signature = ''
            fill()
        } else if (act === 'copy') {
            navigator.clipboard?.writeText(exportRig())
            event.target.textContent = 'Copiado'
            setTimeout(() => (event.target.textContent = 'Copiar ajustes'), 1200)
        }
    })
    // el panel no debe mover la camara ni el personaje
    ;['pointerdown', 'wheel', 'keydown'].forEach((name) => panel.addEventListener(name, (event) => event.stopPropagation()))
    document.body.appendChild(panel)
}

function row(parent, label, min, max, step, value, onInput, decimals = 2) {
    const wrap = document.createElement('div')
    wrap.className = 'row'
    const name = document.createElement('label')
    name.textContent = label
    const input = document.createElement('input')
    input.type = 'range'
    input.min = min
    input.max = max
    input.step = step
    input.value = value
    const out = document.createElement('output')
    out.textContent = Number(value).toFixed(decimals)
    input.addEventListener('input', () => {
        const v = Number(input.value)
        out.textContent = v.toFixed(decimals)
        onInput(v)
    })
    wrap.append(name, input, out)
    parent.appendChild(wrap)
    return { input, out }
}

function section(entry) {
    const details = document.createElement('details')
    const summary = document.createElement('summary')
    const intensity = document.createElement('span')
    intensity.textContent = '×' + entry.k.toFixed(2)
    const name = document.createElement('span')
    name.textContent = entry.label
    summary.append(name, intensity)
    details.appendChild(summary)
    const kind = document.createElement('div')
    kind.className = 'sec'
    kind.textContent = KIND_NAMES[entry.kind] || entry.kind
    details.appendChild(kind)

    row(details, 'Intensidad', 0, 4, 0.01, entry.k, (v) => {
        setIntensity(entry, v)
        intensity.textContent = '×' + v.toFixed(2)
    })
    if (entry.kind === 'dir' || entry.kind === 'spot') {
        const dir = getDirection(entry)
        let az = dir.az
        let el = dir.el
        const apply = () => {
            setDirection(entry, az, el)
            rememberDirection(entry, az, el)
        }
        row(details, 'Giro (°)', 0, 360, 1, az, (v) => ((az = v), apply()), 0)
        row(details, 'Altura (°)', -90, 90, 1, el, (v) => ((el = v), apply()), 0)
        const hint = document.createElement('div')
        hint.className = 'sec'
        hint.textContent = 'Altura: 0 = horizontal, 90 = hacia abajo'
        details.appendChild(hint)
    }
    if (entry.kind === 'spot' || entry.kind === 'point') {
        const d = entry.d.slice()
        const move = () => setOffset(entry, d)
        row(details, 'Mover X (m)', -8, 8, 0.05, d[0], (v) => ((d[0] = v), move()))
        row(details, 'Mover Y (m)', -8, 8, 0.05, d[1], (v) => ((d[1] = v), move()))
        row(details, 'Mover Z (m)', -8, 8, 0.05, d[2], (v) => ((d[2] = v), move()))
    }
    if (entry.kind !== 'hemi' && entry.kind !== 'other') {
        const wrap = document.createElement('div')
        wrap.className = 'row'
        const label = document.createElement('label')
        label.textContent = 'Sombra'
        const box = document.createElement('input')
        box.type = 'checkbox'
        box.checked = entry.light.castShadow
        box.addEventListener('change', () => setShadow(entry, box.checked))
        wrap.append(label, box)
        details.appendChild(wrap)
    }
    const reset = document.createElement('button')
    reset.textContent = 'Restablecer esta luz'
    reset.addEventListener('click', () => {
        resetEntry(entry)
        signature = ''
        fill()
    })
    details.appendChild(reset)
    details.addEventListener('toggle', () => (details.open ? select(entry) : helperOwner === entry && select(null)))
    return details
}

function fill() {
    const entries = shown()
    signature = entries.map((entry) => entry.id).join('|')
    select(null)
    list.textContent = ''
    if (!entries.length) {
        const none = document.createElement('div')
        none.className = 'none'
        none.textContent = 'Esta escena no tiene luces editables.'
        list.appendChild(none)
        return
    }
    let group = ''
    for (const entry of entries) {
        if (entry.group !== group) {
            group = entry.group
            const title = document.createElement('div')
            title.className = 'grp'
            title.textContent = GROUP_NAMES[group] || group
            list.appendChild(title)
        }
        list.appendChild(section(entry))
    }
}

/** La guia de la luz abierta (flecha del sol, cono del foco, esfera de la lampara). */
function select(entry) {
    if (helper) {
        helper.removeFromParent()
        helper.dispose?.()
        helper = null
    }
    helperOwner = entry
    if (!entry || !open) return
    const { light } = entry
    if (entry.kind === 'dir') helper = new THREE.DirectionalLightHelper(light, 1.2, '#ffd27a')
    else if (entry.kind === 'spot') helper = new THREE.SpotLightHelper(light, '#ffd27a')
    else if (entry.kind === 'point') helper = new THREE.PointLightHelper(light, 0.18, '#ffd27a')
    if (helper) {
        helper.traverse((o) => o.material && ((o.material.depthTest = false), (o.material.toneMapped = false)))
        helper.renderOrder = 999
        state.scene.add(helper)
    }
}

export function toggle(force) {
    if (!panel) build()
    open = force ?? !open
    panel.classList.toggle('open', open)
    if (open) fill()
    else select(null)
}

/** Se llama cada cuadro: mantiene la guia en su lugar y actualiza la lista si cambio la escena. */
export function updateLightEditor() {
    if (!open) return
    helper?.update?.()
    if (++frame % 15 === 0 && shown().map((entry) => entry.id).join('|') !== signature) fill()
}

addEventListener('keydown', (event) => {
    if (!EDIT_TOOLS) return // (editor apagado: ver EDIT_TOOLS en config.js)
    if (event.code !== 'KeyL' || event.ctrlKey || event.metaKey || event.altKey) return
    const t = event.target
    if (t && (t.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(t.tagName) && t.type !== 'range' && t.type !== 'checkbox')) return
    event.preventDefault()
    toggle()
})
