/**
 * PUNTO DE ENTRADA
 * 1. Importa los pasos (cada archivo de steps/ se registra solo en `steps`).
 * 2. Construye la escena 3D mostrando la pantalla de carga.
 * 3. Arranca el bucle de animacion (frame) y abre el paso 'home'.
 */
import { audio } from './audio/audio.js'
import { EDIT_TOOLS } from './config.js'
import { state } from './core/state.js'
import { setLazy } from './core/lazyAssets.js'
import { damp, qs } from './core/utils.js'

// Pasos de la experiencia, en orden de aparicion (ver steps/navigation.js)
import './steps/intro.js'
import './steps/before.js'
import './steps/antesEnd.js'
import './steps/during.js'
import './steps/sizes.js'
import './steps/after.js'
import './steps/ending.js'

import { goTo, steps } from './steps/navigation.js'
import { fovBoost, updateCamera } from './systems/camera.js'
import { updateBeacon, updatePrompt } from './systems/interaction.js'
import { updateRipples } from './systems/ripples.js'
import { player, updatePlayer } from './systems/player.js'
import { quake, updateQuake } from './systems/quake.js'
import { tour, tourFovOffset } from './systems/scrollTour.js'
import { updateBooks, updateQuakeEffects } from './systems/quakeEffects.js'
import { cat, createCharacters, dog, updateCharacters } from './three/characters.js'
import { loadCatHD, loadCatModel, setCatRigCamera } from './three/models/catGlb.js'
import { loadDogHD, loadDogModel, setRigCamera } from './three/models/dogGlb.js'
import { loadKitModel } from './three/models/kitGlb.js'
import { loadPersonHD, loadPersonModel } from './three/models/personGlb.js'
import { loadTrackModel } from './three/models/trackGlb.js'
import * as harness from './three/models/harness.js'
import { loadHarnessModel } from './three/models/harness.js'
import { loadAccessoryModels } from './three/models/accessories.js'
import { setLightProfile } from './three/lightRig.js'
import { camera, interiorLights, renderer, resize } from './three/renderer.js'
import { buildShowrooms, layoutSizes } from './three/showrooms.js'
import { livingRoom, loadLivingRoom, updateLivingRoom } from './three/livingRoom.js'
import { loadThirdRoom, setThirdDoor, setWardrobe, thirdRoom, updateThirdRoom } from './three/thirdRoom.js'
import { loadNeighborhoodPlants } from './three/neighborhood.js'
import { buildHouse, world } from './three/world.js'
import { updateBanner } from './ui/banner.js'
import './ui/controls.js'
import { positionTip, updateHotspots } from './ui/hotspots.js'
import { keepLabelClear } from './ui/hud.js'
import { updateLightEditor } from './ui/lightEditor.js' // (editor de iluminacion: tecla L)
import { buildSeismo, updateSeismo } from './ui/seismo.js'

setRigCamera(camera) // el perro mira y le ladra a la camara
setCatRigCamera(camera) // y el gato la mira y le maulla

// Botones de depuracion del perro, del gato y del personaje: solo se muestran con npm run dev
if (EDIT_TOOLS && import.meta.env.DEV) {
    qs('#debugBtn').hidden = false
    qs('#debugCatBtn').hidden = false
    qs('#debugUserBtn').hidden = false
}

// Atajo para depurar: en la consola escribe  petalert.goTo('quiz')  para saltar a un paso.
window.petalert = {
    goTo,
    steps,
    state,
    player,
    // herramientas para probar cosas desde la consola (p. ej. petalert.tools.dog)
    tools: {
        get dog() {
            return dog
        },
        get cat() {
            return cat
        },
        camera,
        tour, // el recorrido por scroll (p. ej. petalert.tools.tour.target = 0.5)
        livingRoom,
        harness,
        thirdRoom, // la habitacion de tercera persona (p. ej. petalert.tools.thirdRoom.parts)
        setThirdDoor,
        setWardrobe,
    },
}

// Campo de vision base de cada modo de camara (el zoom de la transicion se suma encima).
const BASE_FOV = { fp: 68, show: 36, stage: 36, cine: 50, orbit: 34, tp: 34 }

// Pasos del final (etapas "Despues" y "Cierre"): ahi se usa el perfil de luces 'final' (ver three/lightRig.js)
const FINAL_STEPS = new Set(['despIntro', 'guide', 'quiz', 'close', 'about'])
// y la portada y la introduccion usan el perfil 'intro'
const INTRO_STEPS = new Set(['home', 'start'])

let lastFrame = performance.now()
renderer.shadowMap.autoUpdate = false // (las sombras se piden a mano en frame(): ver abajo)
let shadowFrame = 0
let fovEase = 0 // segundos que quedan de suavizado del campo de vision al salir del escenario

// Calidad automatica: si el equipo no llega a ~40 cuadros por segundo, baja la resolucion de dibujo poco a poco (nunca la sube,
// para que no oscile). Asi la experiencia sigue fluida en computadoras o celulares lentos.
const MIN_PIXEL_RATIO = 0.75
const SLOW_FRAME_MS = 25
let slowMs = 0
let slowFrames = 0
function adaptQuality(frameMs) {
    if (frameMs > 250) return // el navegador estaba en pausa (otra pestana) o cargando: no cuenta
    slowMs += frameMs
    slowFrames++
    if (slowMs < 2000) return
    const average = slowMs / slowFrames
    slowMs = slowFrames = 0
    const ratio = renderer.getPixelRatio()
    if (average > SLOW_FRAME_MS && ratio > MIN_PIXEL_RATIO) {
        renderer.setPixelRatio(Math.max(MIN_PIXEL_RATIO, ratio - 0.25))
        resize()
    }
}

/**
 * Un cuadro de animacion. El siguiente se pide ANTES de hacer nada: si algun sistema falla en un cuadro, la experiencia sigue en vez de congelarse para siempre
 * (el error se avisa en la consola, y solo las primeras veces).
 */
let frameErrors = 0
function frame(now) {
    requestAnimationFrame(frame)
    try {
        renderFrame(now)
    } catch (error) {
        if (frameErrors++ < 5) console.error('Error en un cuadro de animacion', error)
    }
}
/** Actualiza todos los sistemas y dibuja. */
function renderFrame(now) {
    adaptQuality(now - lastFrame)
    const dt = Math.min(0.05, (now - lastFrame) / 1000)
    lastFrame = now
    state.time += dt

    // Logica
    updatePlayer(dt)
    if (state.curTick) {
        state.curTick(dt)
    }
    updateQuake(dt)
    updateBooks(dt)
    updateQuakeEffects(dt)
    updateBeacon(dt)
    updateRipples(dt)
    setLightProfile(FINAL_STEPS.has(state.cur) ? 'final' : INTRO_STEPS.has(state.cur) ? 'intro' : null)
    updateLightEditor()
    updateCharacters(dt)
    updateLivingRoom(dt)
    updateThirdRoom(dt, quake.k)
    updateCamera(dt)

    // Zoom de la transicion de reinicio
    fovBoost.v = damp(fovBoost.v, fovBoost.t, 3, dt)
    let fov = BASE_FOV[state.mode] + fovBoost.v * 26 + tourFovOffset()
    // en pantallas verticales (celular y tablet) la camara de primera y tercera persona abre el campo de vision para que se vea el mismo ancho
    // de escena que en una pantalla horizontal (el escenario, el kit y las vitrinas calculan su propio encuadre)
    if (state.mode === 'fp' || state.mode === 'tp' || state.mode === 'cine') {
        const aspect = innerWidth / innerHeight
        const widen = Math.min(state.mode === 'tp' ? 2.4 : 1.7, Math.max(1, 1.35 / aspect)) // (la vista de arriba de la habitacion admite mas)
        fov = (2 * Math.atan(Math.tan((fov * Math.PI) / 360) * widen) * 180) / Math.PI
    }
    // en el escenario (kit y rastreo) el campo de vision se acomoda suave, para que no haya salto al entrar o salir
    const smooth = state.mode === 'stage' || state.mode === 'cine'
    const nextFov = smooth || fovEase > 0 ? damp(camera.fov, fov, 3, dt) : fov
    if (fovEase > 0) fovEase -= dt
    if (smooth) fovEase = 1.6
    if (Math.abs(camera.fov - nextFov) > 0.02) {
        camera.fov = nextFov
        camera.updateProjectionMatrix()
    }

    // Interfaz
    updateSeismo(dt)
    updatePrompt()
    updateBanner()

    // Dibujo. Los mapas de sombras (el sol, el foco y las lamparas, que son varios y cada uno redibuja toda la sala) se actualizan cada dos cuadros:
    // casi no se nota y la carga de dibujo baja mucho. Durante el sismo, que todo se mueve, se actualizan en cada cuadro.
    // Las lamparas puntuales dibujan la sala 6 veces cada una (un cubo de sombras) y casi no cambian: se actualizan cada 4 cuadros.
    shadowFrame++
    const shaking = quake.active || quake.k > 0.01
    renderer.shadowMap.needsUpdate = shaking || shadowFrame % 2 === 0
    for (const light of interiorLights) {
        if (!light.isPointLight || !light.castShadow) continue
        light.shadow.autoUpdate = false
        light.shadow.needsUpdate = shaking || shadowFrame % 4 === 0
    }
    renderer.render(state.scene, camera)
    updateHotspots()
    positionTip()
    keepLabelClear()
}

const pause = (ms = 60) => new Promise((resolve) => setTimeout(resolve, ms))

/**
 * Construye todo para poder mostrar la barra de carga con el avance REAL: los archivos se descargan a la vez (no uno detras de otro) y la barra
 * sube segun lo que ya llego (cada recurso pesa lo que pesa su archivo). Solo se espera por lo que la portada y la introduccion necesitan; la
 * habitacion de la etapa "Durante", el arnes y la camilla bajan despues, en segundo plano (ver core/lazyAssets.js).
 */
async function boot() {
    const bar = qs('#loadBar')
    const message = qs('#loaderMsg')
    resize()
    buildSeismo()
    // peso de cada recurso (KB aproximados de sus archivos) + lo que cuesta armar los personajes y las vitrinas
    const WEIGHT = { kit: 1120, plants: 345, living: 1880, person: 375, track: 625, dog: 155, cat: 150, build: 300 }
    const TOTAL = Object.values(WEIGHT).reduce((sum, w) => sum + w, 0)
    let done = 0
    const advance = (key) => {
        done += WEIGHT[key]
        bar.style.width = Math.min(100, (done / TOTAL) * 100).toFixed(1) + '%'
    }
    const task = (key, promise) => promise.then((value) => (advance(key), value))
    try {
        bar.style.width = '2%'
        // los modelos de la maleta, el usuario, los collares y las mascotas bajan a la vez mientras se arma la calle
        const kit = task('kit', loadKitModel()) // maleta y objetos del kit (static/maleta.glb)
        const models = Promise.all([
            kit,
            task('person', loadPersonModel()), // el usuario con huesos (static/usuario.glb)
            task('track', loadTrackModel()), // collares, placas, rastreadores, microchip y jeringa (static/rastreo.glb)
            task('dog', loadDogModel()),
            task('cat', loadCatModel()),
        ])
        models.catch(() => {}) // (el error se maneja mas abajo, donde se espera; asi no queda un aviso suelto si falla antes)
        // (la sala arma su maleta con el modelo del kit: tiene que estar cargado antes. Si no, la sala usaba la mochila sencilla de cajas, azul con una cruz roja)
        await Promise.all([task('plants', loadNeighborhoodPlants()), kit]) // las plantas del vecindario (static/plantas.glb); si no carga, la calle queda solo con arboles
        buildHouse()

        message.textContent = 'Cargando la sala…'
        await task('living', loadLivingRoom())
        // la casa de cajas es solo un respaldo: la habitacion del .glb la reemplaza (si no carga, se vuelve a mostrar: ver mas abajo)
        world.old.visible = false

        message.textContent = 'Acomodando a las mascotas…'
        await models
        await pause()
        createCharacters()
        loadCatHD() // la capa de detalle del gato se descarga aparte, sin esperar (si falla se queda el low poly)
        loadDogHD() // y la del perro
        loadPersonHD() // y la del usuario

        message.textContent = 'Guardando el kit de emergencia…'
        await pause()
        buildShowrooms()
        layoutSizes(null)
        advance('build')

        bar.style.width = '100%'
        message.textContent = 'Todo listo'
        await pause(250)
    } catch (error) {
        message.textContent = 'Ocurrió un error al preparar la escena. Recarga la página.'
        console.error(error)
        return
    }
    requestAnimationFrame(frame)
    audio.init() // prepara el audio: la musica de la portada suena en cuanto el navegador lo permite
    goTo('home')
    qs('#loader').classList.add('out')
    setTimeout(() => {
        qs('#loader').hidden = true
    }, 800)
    // En segundo plano, ya con la portada en pantalla: la habitacion de la etapa "Durante" (static/escenario-luces.glb), el arnes y la camilla/transportadora
    setLazy(
        Promise.all([
            loadThirdRoom().catch((error) => {
                console.warn('No cargo static/escenario-luces.glb: se usa la casa de cajas.', error)
                world.old.visible = true
            }),
            loadHarnessModel(), // arnes y correa animados (static/arnes.glb)
            loadAccessoryModels(), // camilla y transportadora animadas (static/camilla.glb y static/transportadora.glb)
        ]),
    )
    // y los shaders se compilan sin trabar la escena (asi no hay tirones la primera vez que aparece cada cosa)
    requestIdleCallback?.(() => renderer.compileAsync?.(state.scene, camera).catch(() => {}), { timeout: 3000 })
}
boot()
