/**
 * VECINDARIO alrededor de la casa del .glb, armado como una calle de barrio: casas pegadas unas a otras,
 * con la fachada sobre el anden (sin antejardin), anden de baldosa roja, calle angosta, poste de luz
 * con cables y tanques de agua en las terrazas. Todo es decorado (sin colisiones), solo en primera persona.
 *
 * Mapa (metros): la casa esta en x -2.2..6 y mira al este (+x); su reja da a la linea de fachada x = 6.
 *   x 6..8.2      anden            x 8.2..14      calle (corre a lo largo de z)
 *   x 14..16.2    anden de enfrente, con casas de enfrente (fachada en x = 16.2, miran al oeste)
 * Las casas vecinas tienen tres estilos, tomados de una foto de referencia:
 *   A  ladrillo rojo con porton de barras blancas, ventana de barras y banda de celosias arriba
 *   B  enchape de mosaico beige/naranja con garaje de listones blancos
 *   C  piedra gris con ventanal de vidrio azul y rejas de forja
 *   D  casa blanca de dos pisos (para variar el perfil de la calle)
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { mergeVertices } from 'three/examples/jsm/utils/BufferGeometryUtils.js'
import { getMaterial } from './helpers.js'

// ---------------------------------------------------------------- utilidades
let seed = 7
const rand = () => {
    seed = (seed * 16807) % 2147483647 // aleatorio repetible: la calle siempre se ve igual
    return seed / 2147483647
}
const pick = (list) => list[Math.floor(rand() * list.length)]

/** Textura dibujada con canvas 2D, repetible. */
function canvasTexture(draw, size = 256) {
    const canvas = document.createElement('canvas')
    canvas.width = canvas.height = size
    draw(canvas.getContext('2d'), size)
    const tex = new THREE.CanvasTexture(canvas)
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping
    tex.anisotropy = 4
    return tex
}
const TEX = {}
const textures = () => {
    if (TEX.brick) return TEX
    // ladrillo terracota de juntas beige (como la textura de referencia): ladrillos largos con el borde un poco biselado y cada uno de un tono
    TEX.brick = canvasTexture((g, s) => {
        g.fillStyle = '#bdb0a2' // mortero
        g.fillRect(0, 0, s, s)
        const rows = 10
        const cols = 3
        const rh = s / rows
        const cw = s / cols
        const tones = [[184, 112, 90], [194, 124, 98], [176, 104, 84], [166, 98, 80], [198, 134, 108]] // terracota apagado (poco saturado)
        for (let r = 0; r < rows; r++)
            for (let c = -1; c <= cols; c++) {
                const [R, G, B] = pick(tones)
                const k = 0.94 + rand() * 0.12
                const x = c * cw + (r % 2) * (cw / 2) + 3
                const y = r * rh + 3
                const w = cw - 6
                const h = rh - 6
                const grad = g.createLinearGradient(x, y, x, y + h)
                grad.addColorStop(0, `rgb(${(R * k * 1.06) | 0},${(G * k * 1.06) | 0},${(B * k * 1.06) | 0})`)
                grad.addColorStop(1, `rgb(${(R * k * 0.9) | 0},${(G * k * 0.9) | 0},${(B * k * 0.9) | 0})`)
                g.fillStyle = grad
                g.beginPath()
                g.roundRect(x, y, w, h, 5)
                g.fill()
                g.strokeStyle = 'rgba(255,225,200,0.28)' // luz del borde de arriba
                g.lineWidth = 1.5
                g.beginPath()
                g.moveTo(x + 5, y + 1.5)
                g.lineTo(x + w - 5, y + 1.5)
                g.stroke()
            }
    }, 512)
    TEX.mosaic = canvasTexture((g, s) => {
        const n = 16
        for (let y = 0; y < n; y++)
            for (let x = 0; x < n; x++) {
                g.fillStyle = pick(['#c99a6b', '#d8b48a', '#b98055', '#e0a56e', '#c4b09a', '#a8805a'])
                g.fillRect((x * s) / n + 1, (y * s) / n + 1, s / n - 2, s / n - 2)
            }
    })
    TEX.stone = canvasTexture((g, s) => {
        g.fillStyle = '#8f9094'
        g.fillRect(0, 0, s, s)
        let y = 0
        while (y < s) {
            const h = 14 + rand() * 12
            let x = -rand() * 30
            while (x < s) {
                const w = 30 + rand() * 42
                g.fillStyle = pick(['#c9c9c4', '#b6b7b3', '#d8d8d3', '#a9aaa6', '#bdbdb8'])
                g.fillRect(x + 1, y + 1, w - 2, h - 2)
                x += w
            }
            y += h
        }
    })
    // anden de baldosa beige (como la textura de piso de referencia): baldosas grandes de tonos apenas distintos, con la junta mas oscura
    TEX.sidewalk = canvasTexture((g, s) => {
        g.fillStyle = '#b89d82' // junta
        g.fillRect(0, 0, s, s)
        const n = 2
        for (let y = 0; y < n; y++)
            for (let x = 0; x < n; x++) {
                const px = (x * s) / n + 3
                const py = (y * s) / n + 3
                const size = s / n - 6
                const grad = g.createLinearGradient(px, py, px + size, py + size)
                const base = pick(['#dcc4a8', '#d3b99c', '#e0cbb0', '#cdb294'])
                grad.addColorStop(0, base)
                grad.addColorStop(1, pick(['#cfb596', '#d8c0a4', '#c9ad8e']))
                g.fillStyle = grad
                g.fillRect(px, py, size, size)
            }
    }, 512)
    return TEX
}
/** Material con textura repetida segun el tamano real de la superficie (metros). */
function texturedMaterial(key, w, h, tileSize) {
    const tex = textures()[key].clone()
    tex.needsUpdate = true
    tex.repeat.set(w / tileSize, h / tileSize)
    return new THREE.MeshStandardMaterial({ map: tex, roughness: 0.92, metalness: 0 })
}
/** Caja sin sombras (el decorado no debe ensombrecer la casa principal). */
function box(w, h, d, color) {
    const m = new THREE.Mesh(
        new THREE.BoxGeometry(w, h, d),
        typeof color === 'string' ? getMaterial(color) : color,
    )
    return m
}
const at = (obj, x, y, z) => (obj.position.set(x, y, z), obj)
/**
 * Caja por sus extremos (x0..x1, y0..y1, z0..z1). Las piezas de una fachada se arman asi: cada una empieza donde termina la
 * vecina (se tocan por la cara, sin cruzarse), y no hay dos superficies en el mismo plano que parpadeen.
 */
function slab(parent, [x0, x1], [y0, y1], [z0, z1], color) {
    return parent.add(at(box(x1 - x0, y1 - y0, z1 - z0, color), (x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2))
}
const SIDEWALK_H = 0.165 // altura del anden: lo que esta en la fachada se apoya sobre el, no dentro de el
/** Hace que una superficie le gane a otra casi pegada (a pocos milimetros) y no parpadee cuando se ve de lejos (z-fighting). */
function preferOver(material, level = 1) {
    material.polygonOffset = true
    material.polygonOffsetFactor = -level
    material.polygonOffsetUnits = -level
    return material
}

// ---------------------------------------------------------------- piezas de fachada (plano de fachada en x = 0, hacia +x)
const WHITE = '#f4f6fa'
const DARK = '#1b2438'

/** Ventana con marco blanco y barras: horizontales (barsH) o verticales (barsV). */
function addWindow(g, { z, y, w, h, barsH = 0, barsV = 0, glass = DARK }) {
    const t = 0.08 // grosor del marco
    const [y0, y1, z0, z1] = [y - h / 2, y + h / 2, z - w / 2, z + w / 2]
    slab(g, [0, 0.1], [y0 - t, y0], [z0 - t, z1 + t], WHITE) // marco: abajo, arriba y los dos lados (el vidrio queda dentro del hueco)
    slab(g, [0, 0.1], [y1, y1 + t], [z0 - t, z1 + t], WHITE)
    slab(g, [0, 0.1], [y0, y1], [z0 - t, z0], WHITE)
    slab(g, [0, 0.1], [y0, y1], [z1, z1 + t], WHITE)
    slab(g, [0.02, 0.06], [y0, y1], [z0, z1], glass)
    for (let i = 1; i <= barsH; i++) {
        const yy = y0 + (h * i) / (barsH + 1)
        slab(g, [0.06, 0.14], [yy - 0.025, yy + 0.025], [z0, z1], WHITE)
    }
    for (let i = 1; i <= barsV; i++) {
        const zz = z0 + (w * i) / (barsV + 1)
        slab(g, [0.06, 0.14], [y0, y1], [zz - 0.0225, zz + 0.0225], WHITE)
    }
}
/** Porton de garaje: marco blanco con barras horizontales o listones verticales. */
function addGate(g, { z, w, h, vertical = false }) {
    const y0 = SIDEWALK_H // el porton se apoya sobre el anden
    const top = y0 + h
    const p = 0.04 // medio poste
    const [zl, zr] = [z - w / 2 + p, z + w / 2 - p] // el hueco entre los dos postes
    slab(g, [0.04, 0.16], [y0, top], [z - w / 2 - p, zl], WHITE) // postes
    slab(g, [0.04, 0.16], [y0, top], [zr, z + w / 2 + p], WHITE)
    slab(g, [0.04, 0.16], [top - 0.08, top], [zl, zr], WHITE) // dintel entre los postes
    slab(g, [0, 0.08], [y0, top - 0.08], [zl, zr], DARK) // fondo oscuro
    if (vertical) {
        const n = Math.round(w / 0.17)
        for (let i = 0; i < n; i++) {
            const zc = z - w / 2 + 0.1 + (i * (w - 0.2)) / (n - 1)
            slab(g, [0.08, 0.17], [y0 + 0.08, top - 0.08], [zc - 0.05, zc + 0.05], WHITE)
        }
        slab(g, [0.17, 0.25], [y0 + 0.35, y0 + 0.45], [zl, zr], WHITE) // travesano por delante de los listones
    } else {
        const n = Math.round(h / 0.27)
        slab(g, [0.08, 0.16], [y0, top - 0.08], [z - 0.03, z + 0.03], WHITE) // division de las dos hojas
        for (let i = 0; i < n; i++) {
            const yc = y0 + 0.18 + (i * (h - 0.3)) / (n - 1)
            slab(g, [0.08, 0.16], [yc - 0.03, yc + 0.03], [zl, z - 0.03], WHITE) // las barras se parten en la division
            slab(g, [0.08, 0.16], [yc - 0.03, yc + 0.03], [z + 0.03, zr], WHITE)
        }
    }
}
function addMeterBox(g, z, y = 1.2) {
    slab(g, [0, 0.14], [y - 0.275, y + 0.275], [z - 0.16, z + 0.16], WHITE)
    slab(g, [0.14, 0.22], [y - 0.02, y + 0.18], [z - 0.08, z + 0.08], '#9aa1ad') // el breaker va por delante de la caja
}
function addLouvers(g, w, y) {
    const half = (w - 0.3) / 2
    slab(g, [0, 0.06], [y - 0.16, y + 0.16], [-half, half], DARK)
    slab(g, [0.04, 0.16], [y + 0.16, y + 0.2], [-half, half], WHITE)
    slab(g, [0.04, 0.16], [y - 0.2, y - 0.16], [-half, half], WHITE)
    const n = Math.floor((w - 0.5) / 0.2)
    for (let i = 0; i < n; i++) {
        const zc = -(w - 0.5) / 2 + i * 0.2
        slab(g, [0.06, 0.16], [y - 0.15, y + 0.15], [zc - 0.035, zc + 0.035], WHITE)
    }
}
/** Tanque de agua negro sobre la terraza. */
function addTank(g, x, z, roofY) {
    const tank = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.45, 1.1, 14), getMaterial('#2b3040'))
    tank.position.set(x, roofY + 1, z)
    g.add(tank)
    ;[-0.3, 0.3].forEach((dz) => g.add(at(box(0.08, 0.45, 0.08, '#6b7280'), x, roofY + 0.225, z + dz))) // (patas: de la azotea al fondo del tanque, sin entrar en el)
}

// ---------------------------------------------------------------- plantas (decorado de la calle)
// Estilo de dibujos suaves y redondeados: arboles de copa de esferas, matas de hojas largas en macetas de barro, arbustos y macetas pequenas
// de colores (topiario, cactus, flor...). Cada pieza tiene su origen en la base (y = 0) y se apoya sobre el anden. Las geometrias se comparten.
let plantSeed = 11
const prand = () => {
    plantSeed = (plantSeed * 16807) % 2147483647 // (aleatorio propio: no mueve el de las texturas de las casas)
    return plantSeed / 2147483647
}
const GEO = new Map()
const geo = (key, make) => (GEO.has(key) ? GEO.get(key) : (GEO.set(key, make()), GEO.get(key)))
const part = (geometry, color, x, y, z) => at(new THREE.Mesh(geometry, getMaterial(color)), x, y, z)
const GREEN = ['#628c4c', '#70995a', '#59834a', '#7aa263'] // (verdes apagados, en la familia del verde de las plantas de adentro: #4f7f3f)
/**
 * "Esfera" irregular (una mata de follaje, no una bola perfecta): una esfera con los vertices empujados hacia adentro o afuera segun un
 * relieve suave que depende de la variante. Se sueldan los vertices antes de calcular las normales para que no se vea la costura.
 */
function blobGeometry(r, variant, amp) {
    let g = new THREE.SphereGeometry(r, 18, 14)
    g.deleteAttribute('uv')
    g.deleteAttribute('normal')
    g = mergeVertices(g)
    const pos = g.attributes.position
    const p = new THREE.Vector3()
    const a = 2.1 + variant * 0.7
    const b = 1.3 + variant * 0.45
    for (let i = 0; i < pos.count; i++) {
        p.fromBufferAttribute(pos, i).normalize()
        const bump =
            Math.sin(p.x * a + variant * 1.9) * Math.cos(p.y * b + variant * 0.7) * 0.55 +
            Math.sin(p.z * (a + 1.3) - variant) * Math.sin(p.x * (b + 2.1) + variant * 2.3) * 0.45
        p.multiplyScalar(r * (1 + amp * bump))
        pos.setXYZ(i, p.x, p.y, p.z)
    }
    g.computeVertexNormals()
    // textura del follaje: el color varia de una zona a otra de la mata (manchas de hojas mas claras y mas oscuras) y es un poco mas claro arriba
    const colors = new Float32Array(pos.count * 3)
    for (let i = 0; i < pos.count; i++) {
        p.fromBufferAttribute(pos, i).divideScalar(r)
        const n = Math.sin(p.x * 9 + variant) * Math.sin(p.y * 8 - variant * 1.3) * 0.5 + Math.sin(p.z * 11 + variant * 2) * Math.cos(p.x * 7) * 0.5
        const k = Math.min(1.12, Math.max(0.72, 0.9 + 0.13 * n + 0.08 * p.y))
        colors.set([k, k, k], i * 3)
    }
    g.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    return g
}
const foliage = new Map()
const foliageMaterial = (color) => {
    if (!foliage.has(color)) foliage.set(color, new THREE.MeshStandardMaterial({ color, vertexColors: true, roughness: 0.92, metalness: 0 }))
    return foliage.get(color)
}
const BLOBS = 6 // variantes de forma
/** Corteza muy suave: vetas verticales apenas insinuadas en grises claros (se multiplican por el color del tronco). */
let barkMaterial = null
function bark() {
    if (barkMaterial) return barkMaterial
    const c = document.createElement('canvas')
    c.width = 64
    c.height = 128
    const g = c.getContext('2d')
    g.fillStyle = '#e8e8e8'
    g.fillRect(0, 0, c.width, c.height)
    for (let i = 0; i < 34; i++) {
        const x = prand() * c.width
        g.strokeStyle = `rgba(120,120,120,${0.05 + prand() * 0.07})`
        g.lineWidth = 1.5 + prand() * 2.5
        g.beginPath()
        g.moveTo(x, 0)
        for (let y = 0; y <= c.height; y += 16) g.lineTo(x + (prand() - 0.5) * 5, y)
        g.stroke()
    }
    for (let i = 0; i < 14; i++) {
        g.fillStyle = 'rgba(255,255,255,0.04)'
        g.fillRect(prand() * c.width, prand() * c.height, 1.5, 6 + prand() * 14)
    }
    const map = new THREE.CanvasTexture(c)
    map.wrapS = map.wrapT = THREE.RepeatWrapping
    map.repeat.set(2, 2)
    map.anisotropy = 4
    barkMaterial = new THREE.MeshStandardMaterial({ color: '#8f6d4a', map, roughness: 0.95, metalness: 0 })
    return barkMaterial
}
/** Pieza de follaje irregular: forma, giro y proporciones distintos en cada una (asi dos matas vecinas nunca son iguales). */
function blob(r, color, x, y, z, amp = 0.18) {
    const variant = Math.floor(prand() * BLOBS)
    const mesh = at(new THREE.Mesh(geo(`b${r}-${variant}-${amp}`, () => blobGeometry(r, variant, amp)), foliageMaterial(color)), x, y, z)
    mesh.rotation.set(prand() * Math.PI, prand() * Math.PI * 2, prand() * Math.PI)
    mesh.scale.set(0.9 + prand() * 0.3, 0.82 + prand() * 0.3, 0.9 + prand() * 0.3)
    return mesh
}

/**
 * Plantas de la ambientacion (static/plantas.glb, hecho en Blender): la planta larga (aloe en maceta), la flor, y la planta de hojas. Cada una se mide y se escala a una altura real (m), con la base en y = 0, y las casas usan copias (las mallas y
 * los materiales se comparten). Si el archivo no carga, la calle queda solo con los arboles.
 */
const PLANT_HEIGHT = { aloe: 1.15 } // (solo se usa la planta larga: las otras del archivo se quitaron del vecindario)
let plants = null
export async function loadNeighborhoodPlants() {
    try {
        const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + 'plantas.glb')
        const root = gltf.scene
        // el material de las hojas (Hoja) viene sin color en el archivo (en Blender es un degradado hecho con nodos que no se exporta): se le pone una
        // textura propia con el verde apagado de las plantas de adentro de la casa (#4f7f3f): degradado (mas claro hacia la punta y los bordes),
        // nervadura central, nervios laterales que suben hacia la punta, vetas finas y motas. En las hojas u va a lo ancho y v de la punta (0) a la base (1).
        const leafTexture = (() => {
            const c = document.createElement('canvas')
            c.width = 128
            c.height = 256
            const g = c.getContext('2d')
            for (let x = 0; x < c.width; x++) {
                const edge = (Math.abs(x / (c.width - 1) - 0.5) * 2) ** 1.6 // 0 en el centro, 1 en el borde
                const mix = (a, b) => Math.round(a + (b - a) * edge)
                const grad = g.createLinearGradient(0, 0, 0, c.height)
                grad.addColorStop(0, `rgb(${mix(80, 104)},${mix(122, 146)},${mix(62, 80)})`) // la punta
                grad.addColorStop(1, `rgb(${mix(60, 80)},${mix(98, 120)},${mix(48, 64)})`) // la base
                g.fillStyle = grad
                g.fillRect(x, 0, 1, c.height)
            }
            g.fillStyle = 'rgba(160,195,125,0.32)' // nervadura central
            g.fillRect(c.width / 2 - 2, 0, 4, c.height)
            g.lineWidth = 1.4
            for (let y = 36; y < c.height + 40; y += 15) {
                g.strokeStyle = 'rgba(36,74,38,0.3)' // nervios laterales (suben hacia la punta)
                g.beginPath()
                g.moveTo(c.width / 2, y)
                g.lineTo(6, y - 38)
                g.moveTo(c.width / 2, y)
                g.lineTo(c.width - 6, y - 38)
                g.stroke()
            }
            for (let i = 0; i < 46; i++) {
                const x = prand() * c.width
                g.strokeStyle = prand() < 0.5 ? 'rgba(30,60,30,0.1)' : 'rgba(170,205,140,0.1)'
                g.lineWidth = 1 + prand()
                g.beginPath()
                g.moveTo(x, 0)
                g.lineTo(x + (prand() - 0.5) * 6, c.height)
                g.stroke()
            }
            for (let i = 0; i < 380; i++) {
                g.fillStyle = prand() < 0.5 ? 'rgba(25,55,25,0.08)' : 'rgba(180,210,150,0.08)'
                g.fillRect(prand() * c.width, prand() * c.height, 2, 2)
            }
            const t = new THREE.CanvasTexture(c)
            t.flipY = false
            t.anisotropy = 4
            return t
        })()
        // la maceta no trae coordenadas de textura: se le calculan en cilindro (u alrededor, v de abajo hacia arriba) y se le pone ceramica crema (la de
        // las materas de adentro, #e9dcc0) con granito fino, motitas y dos bandas de esmalte
        const potTexture = (() => {
            const c = document.createElement('canvas')
            c.width = 256
            c.height = 128
            const g = c.getContext('2d')
            g.fillStyle = '#e9dcc0'
            g.fillRect(0, 0, c.width, c.height)
            for (let i = 0; i < 1400; i++) {
                g.fillStyle = prand() < 0.6 ? 'rgba(150,118,84,0.1)' : 'rgba(255,250,235,0.14)'
                g.fillRect(prand() * c.width, prand() * c.height, 1 + prand() * 2, 1 + prand() * 2)
            }
            g.fillStyle = 'rgba(160,125,90,0.09)'
            g.fillRect(0, 20, c.width, 7)
            g.fillRect(0, 100, c.width, 5)
            const t = new THREE.CanvasTexture(c)
            t.wrapS = THREE.RepeatWrapping
            t.anisotropy = 4
            return t
        })()
        root.traverse((o) => {
            if (o.isMesh && o.material?.name === 'Hoja') o.material.map = leafTexture
            if (o.isMesh && o.material?.name === 'Maceta') {
                const pos = o.geometry.attributes.position
                const box = new THREE.Box3().setFromBufferAttribute(pos)
                const uv = new Float32Array(pos.count * 2)
                for (let i = 0; i < pos.count; i++) {
                    uv[i * 2] = Math.atan2(pos.getX(i), pos.getZ(i)) / (Math.PI * 2) + 0.5
                    uv[i * 2 + 1] = (pos.getY(i) - box.min.y) / (box.max.y - box.min.y)
                }
                o.geometry.setAttribute('uv', new THREE.BufferAttribute(uv, 2))
                o.material.map = potTexture
                o.material.color.set('#ffffff') // (el color viene de la textura)
                o.material.roughness = 0.8
            }
        })
        const fromNodes = (names) => {
            const g = new THREE.Group()
            names.forEach((n) => g.add(root.getObjectByName(n).clone(true)))
            return g
        }
        const single = (name) => {
            const g = root.getObjectByName(name).clone(true)
            g.position.set(0, 0, 0) // (en el archivo estan en fila, cada una en su lugar)
            return g
        }
        const sources = {
            aloe: fromNodes([...Array.from({ length: 16 }, (_, i) => `Hoja_${String(i + 1).padStart(2, '0')}`), 'Maceta', 'Tierra']),
        }
        plants = {}
        for (const [kind, source] of Object.entries(sources)) {
            const holder = new THREE.Group()
            holder.add(source)
            holder.updateMatrixWorld(true)
            const bounds = new THREE.Box3().setFromObject(holder)
            const center = bounds.getCenter(new THREE.Vector3())
            source.position.set(-center.x, -bounds.min.y, -center.z) // centrada y apoyada en y = 0
            holder.scale.setScalar(PLANT_HEIGHT[kind] / (bounds.max.y - bounds.min.y))
            plants[kind] = holder
        }
    } catch (error) {
        console.warn('No cargo static/plantas.glb: el vecindario queda solo con arboles.', error)
        plants = null
    }
}
/** Una copia de una planta, con giro y tamano un poco distintos cada vez. */
function plantOf(kind) {
    const plant = new THREE.Group()
    const copy = plants[kind].clone(true)
    copy.scale.multiplyScalar(0.88 + prand() * 0.3)
    plant.add(copy)
    plant.rotation.y = prand() * Math.PI * 2
    return plant
}
/** Arbol de calle: tronco con tres ramas, copa de follaje irregular y un cantero en el anden (borde de concreto como el del anden, con el pasto un poco mas abajo). */
function makeTree(scale = 1) {
    const g = new THREE.Group()
    const EDGE = '#cfd3da'
    const R = 0.6 // medio lado del cantero
    const t = 0.1 // grosor del borde
    slab(g, [-R, R], [0, 0.1], [-R, -R + t], EDGE)
    slab(g, [-R, R], [0, 0.1], [R - t, R], EDGE)
    slab(g, [-R, -R + t], [0, 0.1], [-R + t, R - t], EDGE)
    slab(g, [R - t, R], [0, 0.1], [-R + t, R - t], EDGE)
    slab(g, [-R + t, R - t], [0, 0.06], [-R + t, R - t], '#76975a') // el pasto, dentro del borde
    const mound = blob(0.46, '#82a565', 0, 0.06, 0, 0.1) // un montoncito de pasto, no una losa plana
    mound.scale.set(1, 0.16, 1)
    mound.rotation.set(0, prand() * Math.PI * 2, 0)
    g.add(mound)
    const base = 0.07
    g.add(at(new THREE.Mesh(geo('trunk', () => new THREE.CylinderGeometry(0.1, 0.16, 2.0, 10)), bark()), 0, base + 1.0, 0))
    ;[[-0.5, 0.25], [0.5, -0.1], [0, 0.55]].forEach(([tx, tz]) => {
        const branch = at(new THREE.Mesh(geo('branch', () => new THREE.CylinderGeometry(0.045, 0.08, 1.1, 8)), bark()), tx * 0.45, base + 2.35, tz * 0.45)
        branch.rotation.z = -tx * 0.9
        branch.rotation.x = tz * 0.9
        g.add(branch)
    })
    ;[
        [0, 3.3, 0, 0.8], [-0.7, 3.0, 0.1, 0.55], [0.7, 3.05, -0.1, 0.55], [0.1, 3.0, 0.7, 0.5], [-0.1, 3.05, -0.7, 0.5],
        [-0.4, 3.75, 0.2, 0.5], [0.45, 3.7, -0.15, 0.5],
    ].forEach(([x, y, z, r], i) => g.add(blob(r, GREEN[i % GREEN.length], x, y, z, 0.2)))
    g.scale.setScalar(scale)
    return g
}
/** Plantas frente a una casa (en su espacio: fachada en x = 0, hacia +x; z a lo ancho): la planta larga en un borde y, casi siempre, otra en el otro borde (nunca juntas: antes se amontonaban tres o cuatro). */
function addHousePlants(g, w, index) {
    if (!plants) return
    const edge = w / 2 - 0.45
    const side = index % 2 === 0 ? 1 : -1
    const x = 0.6 // por delante de todas las piezas de la fachada (llegan hasta x = 0.25)
    const y = SIDEWALK_H
    const add = (z, dx = 0) => {
        const plant = plantOf('aloe')
        plant.position.set(x + dx, y, z)
        g.add(plant)
    }
    add(side * edge)
    if (prand() < 0.9) add(-side * edge, 0.05)
}
// ---------------------------------------------------------------- casas
// Proporciones de la casa de la experiencia (static/casa3.glb): pared de 2.55 m, puerta de 2.1 x 1.0 m,
// ventanas de 1.25 m de alto con el borde de abajo a 0.6 m del piso.
const FLOOR_H = 2.55
const DOOR_H = 2.1
const DOOR_W = 1
const WIN_H = 1.25
const WIN_Y = 0.6 + WIN_H / 2
const STYLES = {
    A: { w: 6.6, floors: 1 },
    B: { w: 5.2, floors: 1 },
    C: { w: 6.6, floors: 1 },
    D: { w: 6, floors: 2 },
}

/**
 * Casa con la fachada en x = 0 mirando a +x y el cuerpo hacia -x. Ocupa z -w/2..w/2.
 */
/** Cuerpos de las casas de los lados (casi transparentes solo cuando se esta dentro de la casa: ver setSideHouseGhost). */
const ghostMaterials = []
/** Materiales del vecindario que llevan un brillo propio (luz general de afuera): quakeEffects.js les pone la intensidad cada cuadro. */
export const neighborhoodGlow = []
let ghostK = 0
/** k = 1: las casas de los lados se ven a traves (adentro de la casa); k = 0: opacas (afuera). Cambia poco a poco. */
export function setSideHouseGhost(on, dt) {
    ghostK += (((on ? 1 : 0) - ghostK) * Math.min(1, dt * 4))
    ghostMaterials.forEach((m) => {
        m.opacity = 1 - 0.9 * ghostK
        m.depthWrite = ghostK < 0.5
    })
}

function makeHouse(style, ghost = false) {
    const { w, floors } = STYLES[style]
    const g = new THREE.Group()
    const H = floors === 2 ? FLOOR_H * 2 + 0.2 : FLOOR_H // mismas alturas que la casa de la experiencia
    const depth = 8.2

    // cuerpo (las casas de los lados de la casa principal son casi transparentes: asi se ve la luz que entra por las ventanas laterales)
    // (el cuerpo termina 2 cm detras del plano de fachada: asi la fachada y las piezas apoyadas en ella no comparten plano con el)
    const body = at(
        box(
            depth - 0.02,
            H,
            w,
            ghost
                ? (ghostMaterials[ghostMaterials.push(new THREE.MeshStandardMaterial({ color: '#e9e4dc', transparent: true, opacity: 1, roughness: 0.9 })) - 1])
                : '#e9e4dc',
        ),
        -(depth + 0.02) / 2,
        H / 2,
        0,
    )
    if (ghost) body.renderOrder = 2
    g.add(body)
    // plano de fachada con la textura del estilo
    const material =
        style === 'A'
            ? texturedMaterial('brick', w, H, 1.2)
            : style === 'B'
              ? texturedMaterial('mosaic', w, H, 1)
              : style === 'C'
                ? texturedMaterial('stone', w, H, 1.4)
                : getMaterial('#f1ece4').clone()
    preferOver(material, 1) // la fachada va a 2 cm del cuerpo: el polygonOffset evita que los dos se mezclen a lo lejos
    const facade = new THREE.Mesh(new THREE.PlaneGeometry(w, H).rotateY(Math.PI / 2), material)
    facade.position.set(0, H / 2, 0)
    g.add(facade)
    // terraza con antepecho: la losa apoya sobre el cuerpo y llega justo hasta el plano de fachada (del ancho exacto de la casa, sin
    // montarse sobre la vecina), y el antepecho apoya sobre la losa
    slab(g, [-depth, 0], [H, H + 0.2], [-w / 2, w / 2], '#cfd3da')
    slab(g, [-0.18, 0], [H + 0.2, H + 0.6], [-w / 2, w / 2], style === 'B' ? '#c9a77c' : style === 'C' ? '#b6b7b3' : WHITE)

    if (style === 'A') {
        addLouvers(g, w, H - 0.22)
        addGate(g, { z: -w / 2 + 1.55, w: 2.6, h: DOOR_H })
        addMeterBox(g, 0)
        addWindow(g, { z: w / 2 - 1.75, y: WIN_Y, w: 1.9, h: WIN_H, barsH: 3 })
        addTank(g, -2.5, 0.8, H + 0.2)
    } else if (style === 'B') {
        addWindow(g, { z: -w / 2 + 0.95, y: WIN_Y, w: 1.4, h: WIN_H, barsV: 7 })
        addMeterBox(g, -0.5, 1.1)
        addGate(g, { z: w / 2 - 1.5, w: 2.4, h: DOOR_H, vertical: true })
        addTank(g, -3, -0.5, H + 0.2)
    } else if (style === 'C') {
        // ventanal de vidrio azul con rejas de forja
        const wz = 0.2
        addWindow(g, { z: wz, y: WIN_Y, w: 4.24, h: WIN_H, glass: '#2a4fa8' }) // (marco de 4.4 m de ancho en total)
        for (let i = 0; i <= 4; i++) slab(g, [0.06, 0.14], [WIN_Y - WIN_H / 2, WIN_Y + WIN_H / 2], [wz - 2.025 + i, wz - 1.975 + i], DARK)
        ;[-1, 1].forEach((dz) => {
            const ring = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.035, 8, 24), getMaterial(DARK))
            ring.rotation.y = Math.PI / 2
            ring.position.set(0.175, WIN_Y, wz + dz) // (por delante de las barras: las toca sin atravesarlas)
            g.add(ring)
        })
        slab(g, [0, 0.14], [0.3, 0.8], [w / 2 - 0.8, w / 2 - 0.2], '#b6b3ab') // caja de contadores (al lado del ventanal, sin tocarlo)
        slab(g, [0, 0.14], [SIDEWALK_H, SIDEWALK_H + DOOR_H], [-w / 2 + 0.1, -w / 2 + 1.1], '#cfd3da') // puerta
    } else {
        // casa blanca de dos pisos
        ;[WIN_Y, WIN_Y + FLOOR_H + 0.1].forEach((y) => {
            addWindow(g, { z: -w / 4, y, w: 1.6, h: WIN_H, barsV: 3, glass: '#7fa6d6' })
            addWindow(g, { z: w / 4, y, w: 1.6, h: WIN_H, barsV: 3, glass: '#7fa6d6' })
        })
        slab(g, [0, 0.5], [FLOOR_H - 0.01, FLOOR_H + 0.11], [-w / 2, w / 2], '#cfd3da') // losa del segundo piso
        slab(g, [0, 0.14], [SIDEWALK_H, SIDEWALK_H + DOOR_H], [-DOOR_W / 2, DOOR_W / 2], '#cfd3da') // puerta
    }
    return g
}

/** Fila de casas contiguas a lo largo de z. */
function row(parent, { x, face, zStart, dir, styles, ghost = 0 }) {
    let z = zStart
    styles.forEach((style, i) => {
        const w = STYLES[style].w
        const house = makeHouse(style, i < ghost) // las primeras ghost casas son transparentes
        house.position.set(x, 0, z + (dir * w) / 2)
        house.rotation.y = face === 1 ? 0 : Math.PI
        addHousePlants(house, w, i)
        parent.add(house)
        z += dir * w
    })
}

/** Poste de luz de concreto con cables. */
function makePole(parent, x, z, z2) {
    // el poste se apoya sobre el anden (no queda enterrado en el)
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 9, 10), getMaterial('#aeb2b8'))
    pole.position.set(x, SIDEWALK_H + 4.5, z)
    parent.add(pole)
    const radiusAt = (y) => 0.14 + 0.06 * (1 - (y - SIDEWALK_H) / 9) // radio del poste a esa altura
    // travesanos: dos mitades que nacen en la superficie del poste (antes una sola viga lo atravesaba)
    ;[[8.3, 1.8], [7.7, 1.4]].forEach(([y, length]) => {
        const r = radiusAt(y)
        const half = length / 2 - r
        ;[-1, 1].forEach((side) => parent.add(at(box(0.12, 0.12, half, '#6b7280'), x, y, z + side * (r + half / 2))))
    })
    // cables hasta el siguiente poste (el del centro sale de la superficie del poste, no de su eje)
    ;[-0.7, 0, 0.7].forEach((off) => {
        const trim = off === 0 ? radiusAt(8.2) : 0
        const len = Math.abs(z2 - z) - 2 * trim
        const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, len, 4), getMaterial('#1b2438'))
        cable.rotation.x = Math.PI / 2
        cable.position.set(x + off * 0.3, 8.2 - Math.abs(off) * 0.3, (z + z2) / 2)
        parent.add(cable)
    })
}

export function buildNeighborhood(parent) {
    const flat = (w, d, material, x, y, z) => {
        const p = new THREE.Mesh(new THREE.PlaneGeometry(w, d), material)
        p.rotation.x = -Math.PI / 2
        p.position.set(x, y, z)
        p.receiveShadow = true
        parent.add(p)
    }
    // calle angosta y andenes de baldosa roja con sardinel
    flat(5.8, 160, preferOver(getMaterial('#6d7280').clone(), 1), 11.1, 0.005, 0)
    // anden: UN solo bloque con la baldosa en la cara de arriba (antes eran una tapa y un bloque a 5 mm uno del otro)
    const walk = (x) => {
        const side = getMaterial('#cfd3da')
        const top = texturedMaterial('sidewalk', 2.2, 160, 1.6)
        parent.add(at(new THREE.Mesh(new THREE.BoxGeometry(2.2, SIDEWALK_H, 160), [side, side, top, side, side, side]), x, SIDEWALK_H / 2, 0))
    }
    walk(7.1) // x 6..8.2
    walk(15.1) // x 14..16.2
    // sardineles: pegados al anden (sin hueco ni cruce) y apoyados sobre la calle
    parent.add(at(box(0.18, 0.195, 160, '#e4e8f0'), 8.29, 0.005 + 0.0975, 0))
    parent.add(at(box(0.18, 0.195, 160, '#e4e8f0'), 13.91, 0.005 + 0.0975, 0))

    // misma acera que la casa principal: casas vecinas pegadas a ambos lados (fachada en x = 6)
    row(parent, {
        x: 6,
        face: 1,
        zStart: 3.1, // (3 cm separada de la pared de la casa principal: antes las dos paredes quedaban en el mismo plano y se mezclaban)
        dir: 1,
        styles: ['B', 'A', 'C', 'D', 'B', 'A', 'C', 'B', 'D', 'A'],
        ghost: 2,
    })
    row(parent, {
        x: 6,
        face: 1,
        zStart: -3.1,
        dir: -1,
        styles: ['A', 'C', 'B', 'D', 'A', 'B', 'C', 'A', 'D', 'B'],
        ghost: 2,
    })
    // casas de enfrente (fachada en x = 16.2, miran al oeste)
    row(parent, {
        x: 16.2,
        face: -1,
        zStart: -34,
        dir: 1,
        styles: ['C', 'B', 'A', 'D', 'B', 'C', 'A', 'B', 'D', 'A', 'C'],
    })

    // arboles en los andenes (cerca del sardinel, lejos de los postes)
    const tree = (x, z, scale = 1) => {
        parent.add(at(makeTree(scale), x, SIDEWALK_H, z))
    }
    ;[-17, -11, -5.5, 6, 9.5, 17.5, 24, 35].forEach((z, i) => tree(7.5, z, 0.9 + (i % 3) * 0.1))
    ;[-20, -12, -4, 8, 16, 26].forEach((z, i) => tree(14.7, z, 0.9 + (i % 3) * 0.1))

    // luz general de afuera: un brillo propio en todo el vecindario (calle, andenes y casas), sin tocar el interior de la casa principal
    const marked = new Map() // (las plantas repiten los mismos materiales: se marca una sola copia de cada uno)
    const mark = (material) => {
        if (!material.isMeshStandardMaterial || material.userData.glow) return material
        if (marked.has(material)) return marked.get(material)
        const own = ghostMaterials.includes(material) ? material : material.clone() // (los cuerpos transparentes se conservan: son los que cambia setSideHouseGhost)
        marked.set(material, own)
        own.userData.glow = true
        own.emissive.copy(own.color)
        if (own.map) own.emissiveMap = own.map
        own.emissiveIntensity = 0
        neighborhoodGlow.push(own)
        return own
    }
    parent.traverse((o) => {
        if (!o.isMesh || !o.material) return
        if (Array.isArray(o.material)) {
            const own = new Map() // (el anden repite un mismo material en varias caras: se marca una sola vez)
            o.material = o.material.map((m) => own.get(m) ?? (own.set(m, mark(m)), own.get(m)))
        } else o.material = mark(o.material)
    })

    // postes de luz con cables, como en la foto
    makePole(parent, 7.9, -7, 12)
    makePole(parent, 7.9, 12, 31)
    makePole(parent, 14.3, 2, -17)
}
