/**
 * PERSONAJES: instancias de Cacao (dog), Nube (cat) y el usuario (person)
 * mas utilidades para colocarlos, hacerlos caminar y cambiar su estado de animo.
 */
import { petPalettes } from '../config.js'
import { state } from '../core/state.js'
import { angleDiff, damp } from '../core/utils.js'
import { createPerson } from './models/person.js'
import { createPersonFromModel, hasPersonModel, updatePersonRig } from './models/personGlb.js'
import { allPets, createCat, createDog } from './models/pets.js'
import { createContactShadow, createFearBubble } from './models/props.js'
import * as THREE from 'three'
import { catJumpCurve, catJumpRate, updateCatRig } from './models/catGlb.js'
import { jumpCurve, jumpRate, updateDogRig } from './models/dogGlb.js'
import { kitLidDuration, setBagLid } from './models/kitGlb.js'
import { glowTuning, lightPets, setObjectLight } from './petGlow.js'
import { mainScene, renderer } from './renderer.js'
import { createPetShadow } from './petShadow.js'
import { LAYOUT, groundY } from './thirdRoom.js'
import { KIT_MOUTH, kitItemTime, showrooms } from './showrooms.js'

export let dog
export let cat
export let person
export const fearBubbles = []
export const catHideSpots = LAYOUT.catSpots // junto a la puerta, sobre la cama y sobre la mesa (ver thirdRoom.js)
export function placePet(pet, x, y, z, rotY, scale) {
    let i = pet.userData
    i.path = null
    i.walking = false
    i.pop = null
    i.ty = null
    i.faceTo = null
    i.lie = 0 // (acostado, miradas y jadeo nerviosos: se apagan al colocar a la mascota; ver systems/nerves.js)
    i.glance = 0
    i.pantOn = false
    i.sc = scale || 1
    i.base.set(x, y, z)
    pet.position.set(x, y, z)
    pet.rotation.y = rotY || 0
    pet.scale.setScalar(scale || 1)
    pet.scale.y = scale || 1
}
export function popIn(pet) {
    let t = pet.userData
    pet.visible = true
    t.pop = 0
    t.hop = 1
    pet.scale.setScalar(0.001)
}
/** La mascota se lame una pata durante `seconds` (sube, se mantiene y baja solo; ver a.groom en dogGlb.js y catGlb.js). */
export function groomPet(pet, seconds = 3) {
    const a = pet.userData
    a.groomT = 0
    a.groomDur = seconds
}
export function walkPath(pet, path, speed) {
    let o = pet.userData
    o.path = path.map((s) => Object.assign({}, s))
    o.speed = speed || 3.4
    o.walking = true
    o.faceTo = null
}
export function setPetMood(pet, mood) {
    let a = pet.userData
    a.wag = mood.wag != null ? mood.wag : 1
    a.shiver = mood.shiver || 0
    a.eyes.forEach((o) => o.scale.setScalar(mood.eyes || 1))
}
export function createCharacters() {
    dog = createDog(petPalettes.cacao)
    cat = createCat(petPalettes.nube)
    lightPets([dog, cat]) // luz propia suave: las sombras del cuerpo no los oscurecen
    person = hasPersonModel() ? createPersonFromModel() : createPerson() // con huesos (static/usuario.glb) o de formas simples
    person.visible = false
    mainScene.add(dog, cat, person)
    // sombra de contacto suave bajo cada una (oclusion falsa en las patas): la sombra del sol sola deja a las mascotas "flotando"
    ;[
        [dog, 0.62, 1.05, 0.3],
        [cat, 0.5, 0.8, 0.3],
    ].forEach(([pet, w, d, k]) => {
        const contact = createContactShadow(w, d, k, true) // chica y definida: solo bajo las patas
        pet.add(contact)
        pet.userData.contact = contact
        pet.userData.contactK = k
        // sombra con la silueta real, para donde ninguna luz la proyecta (dentro del armario): ver petShadow.js
        pet.userData.realShadow = createPetShadow(renderer, mainScene, pet, { skew: [-0.05, 0], strength: 0.36 })
    })
    catHideSpots.forEach((e) => {
        let t = createFearBubble()
        t.position.set(e[0], e[1] + 1.4, e[2])
        t.visible = false
        mainScene.add(t)
        fearBubbles.push(t)
    })
}
export function updateCharacters(dt) {
    if (person && person.userData.rig && person.visible) updatePersonRig(person, dt) // el usuario: caminar, agacharse y sentarse
    if (
        (allPets.forEach((t) => {
            let a = t.userData
            if (a.groomDur) {
                // acicalarse: sube rapido, se mantiene y baja rapido (a.groom de 0 a 1)
                a.groomT += dt
                const k = a.groomT / a.groomDur
                if (k >= 1 || a.walking) {
                    a.groomDur = 0
                    a.groom = 0
                } else a.groom = Math.min(1, k * 6, (1 - k) * 6)
            }
            if (a.rig) (a.rig.kind === 'cat' ? updateCatRig : updateDogRig)(t, dt) // perro con huesos: traduce cola/cabeza/patas a movimiento de huesos
            if (a.path && a.path.length) {
                let s = a.path[0]
                a.ty = s.y || 0
                let r = s.x - a.base.x,
                    i = s.z - a.base.z,
                    n = Math.hypot(r, i),
                    d = a.speed * dt
                if (n <= d) {
                    a.base.x = s.x
                    a.base.z = s.z
                    a.path.shift()
                    if (!a.path.length) {
                        a.walking = false
                        a.faceTo = s.ry != null ? s.ry : null
                    }
                } else {
                    a.base.x += (r / n) * d
                    a.base.z += (i / n) * d
                    t.rotation.y += angleDiff(t.rotation.y, Math.atan2(r, i)) * Math.min(1, dt * 10)
                }
            } else {
                if (a.faceTo != null) {
                    t.rotation.y += angleDiff(t.rotation.y, a.faceTo) * Math.min(1, dt * 8)
                }
            }
            if ((a.ty != null && (a.base.y = damp(a.base.y, a.ty, 7, dt)), a.pop != null)) {
                a.pop = Math.min(1, a.pop + dt * 2.4)
                let s = a.pop - 1,
                    r = 1 + 2.70158 * s * s * s + 1.70158 * s * s,
                    i = (a.sc || 1) * Math.max(0.001, r)
                t.scale.set(i, i, i)
                if (a.pop >= 1) {
                    a.pop = null
                }
            }
            if (a.type === 'dog' && a.tail) {
                a.tail.rotation.z = Math.sin(state.time * 9 + a.ph) * 0.5 * a.wag
            } else if (a.tail) {
                a.tail.rotation.y = Math.sin(state.time * 3 + a.ph) * 0.35 * a.wag
            }
            // modo "asustado": se mezcla poco a poco (antes cambiaba de golpe al cruzar 0.3 y la cabeza y la cola daban un salto seco
            // cada vez que el temblor subia y bajaba por ese valor, p. ej. en las pantallas de tamanos)
            a.scaredK = damp(a.scaredK || 0, a.shiver > 0.3 ? 1 : 0, 4, dt)
            if (a.head) {
                const k = a.scaredK
                a.head.rotation.y = Math.sin(state.time * 0.8 + a.ph) * 0.25 * (1 - k) + Math.sin(state.time * 2 + a.ph) * 0.12 * k
                a.head.rotation.z = Math.sin(state.time * 1.3 + a.ph) * 0.05 * (1 - k)
            }
            // temblor del cuerpo: se nota pero muy poquito (antes eran 3 mm, luego mucho); mas fuerte mientras mas asustada esta la mascota
            t.position.x =
                a.base.x + (a.shiver ? Math.sin(state.time * 55 + a.ph) * 0.02 * a.shiver * t.scale.x : 0)
            t.position.z = a.base.z + (a.shiver ? Math.sin(state.time * 47 + a.ph * 2) * 0.014 * a.shiver * t.scale.x : 0)
            // al caminar rebota un poco; al correr (a.run) rebota mas y mas rapido, como un galope
            let o = a.rig
                ? (a.rig.bobY || 0) * t.scale.x // el perro con huesos rebota al ritmo de sus pasos
                : a.walking
                  ? Math.abs(Math.sin(state.time * (a.run ? 22 : 13) + a.ph)) * (a.run ? 0.17 : 0.07) * t.scale.x
                  : 0
            // en el cuarto (orbita y tercera persona) las mascotas que estan en el piso suben a la altura de la alfombra y del piso: antes las patas la atravesaban
            const ground = (state.mode === 'tp' || state.mode === 'orbit') && (a.ty == null || a.ty < 0.05) && a.base.y < 0.05 ? groundY(a.base.x, a.base.z) : 0
            if (a.hop > 0) {
                const cat = a.rig?.kind === 'cat'
                a.hop = Math.max(0, a.hop - dt * (a.rig ? (cat ? catJumpRate : jumpRate)() : 2.2))
                const lift = a.rig
                    ? (cat ? catJumpCurve : jumpCurve)(1 - a.hop).lift
                    : Math.sin((1 - a.hop) * Math.PI) * 0.35
                t.position.y = a.base.y + ground + o + lift * t.scale.x
            } else {
                t.position.y = a.base.y + ground + o
            }
            if (a.rig) t.position.y -= (a.rig.drop || 0) * t.scale.x // la pata mas baja siempre toca el piso
            // la sombra de contacto se queda en el piso (o en el asiento) aunque la mascota rebote o salte; se desvanece al subir
            if (a.contact) {
                const lifted = t.position.y - a.base.y - ground
                a.contact.position.y = (a.base.y + ground + 0.012 - t.position.y) / (t.scale.y || 1)
                a.contact.material.opacity = a.contactK * Math.max(0.25, 1 - lifted * 2.2)
            }
            // dentro del armario (a la izquierda del cuarto) ninguna luz llega a la repisa: ahi la sombra es la silueta real de la mascota
            if (a.realShadow) {
                const inWardrobe = state.mode === 'tp' && a.base.x < -1.7 && a.base.z > 1.2 && a.base.z < 2.3
                // (sobre la cama del cuarto no se usa la silueta: la sombra de contacto basta y no queda una mancha oscura bajo las patas)
                a.realShadow.update(inWardrobe, a.base.y)
                if (a.contact && inWardrobe) a.contact.material.opacity *= 0.35 // (la mancha redonda queda como un toque de oclusion bajo las patas)
            }
        }),
        showrooms.fin && showrooms.fin.visible)
    ) {
        let t = showrooms.fin.motes.geometry.attributes.position
        for (let a = 0; a < t.count; a++) {
            let o = t.getY(a) + dt * (0.28 + (a % 5) * 0.09)
            if (o > 6) {
                o = -0.2
            }
            t.setY(a, o)
            t.setX(a, t.getX(a) + Math.sin(state.time * 0.8 + a) * 0.002)
        }
        t.needsUpdate = true
    }
    if (showrooms.kit && showrooms.kit.visible) {
        const kit = showrooms.kit
        let squash = 0 // la mochila se "infla" un poco cuando sale o entra un objeto
        if (kit.timelineOn) kit.timeline += dt
        // plano a la altura de la boca de la maleta (en el mundo): lo de abajo no se dibuja mientras esta dentro
        kit.updateWorldMatrix(true, false)
        kitMouth.setFromNormalAndCoplanarPoint(
            kitUp,
            kit.localToWorld(kitPoint.set(0, 1.5 * kit.bag.scale.y + kit.bag.position.y, 0)),
        )
        kit.items.forEach((item) => {
            const a = item.userData
            if (a.stage === 'in' || a.stage === 'stored') {
                item.visible = false
                return
            }
            if (a.stage === 'emerging' || a.stage === 'storing') {
                const emerging = a.stage === 'emerging'
                const kitAnim = item.userData.kitAnim
                if (kitAnim) {
                    // Animacion del archivo de Blender, exacta: salir sigue la linea de tiempo del archivo (la
                    // misma para la tapa y todos los objetos); guardar es esa misma animacion al reves.
                    item.position.copy(a.base)
                    item.quaternion.identity()
                    item.scale.setScalar(1)
                    if (emerging) {
                        if (kit.timeline < 0) {
                            item.visible = false
                            return
                        }
                        item.visible = true
                        // todos los objetos salen a la vez: cada uno reproduce su animacion desde su inicio en el mismo instante
                        const own = kitItemTime(kit, kitAnim)
                        kitAnim.setTime(own)
                        kitClip(kitAnim, own)
                        // efecto de salida: destello y chispas en la boca al empezar, y el objeto brilla mientras sale
                        if (!a.burstDone && kit.timeline >= (kit.itemStart ?? kitAnim.t0)) {
                            a.burstDone = true
                            spawnKitBurst(kit)
                        }
                        const u = (own - kitAnim.t0) / Math.max(0.05, kitAnim.tClear - kitAnim.t0)
                        setItemGlow(item, u < 1 ? 1 : 0.9 * (1 - Math.min(1, (u - 1) * 2)))
                        if (own >= kitAnim.t1) a.stage = 'out'
                    } else {
                        a.stime -= dt
                        item.visible = true
                        kitAnim.setTime(a.stime)
                        kitClip(kitAnim, a.stime)
                        if (a.stime <= kitAnim.t0) {
                            a.stage = 'stored'
                            item.visible = false
                        }
                    }
                    return
                }
                a.t += dt / (emerging ? 0.9 : 0.6)
                if (a.t < 0) {
                    item.visible = false
                    return
                }
                item.visible = true
                const k = Math.min(1, a.t)
                if (emerging) {
                    const e = easeOutBack(k)
                    item.position.lerpVectors(KIT_MOUTH, a.base, e)
                    item.position.y += Math.sin(k * Math.PI) * 0.9
                    item.scale.setScalar(Math.max(0.001, e))
                } else {
                    const e = k * k * (3 - 2 * k)
                    item.position.lerpVectors(a.from, KIT_MOUTH, e)
                    item.position.y += Math.sin(k * Math.PI) * 0.5
                    item.scale.setScalar(Math.max(0.001, 1 - e))
                }
                item.rotation.y += dt * 3
                squash = Math.max(squash, Math.sin(Math.min(1, k * 2) * Math.PI))
                if (k >= 1) {
                    a.stage = emerging ? 'out' : 'stored'
                    if (!emerging) item.visible = false
                }
                return
            }
            // out: flota suavemente (los del modelo de Blender se quedan donde termina su animacion)
            if (!a.kitAnim) {
                item.position.y = a.base.y + Math.sin(state.time * 1.6 + a.ph) * 0.08
                item.rotation.y += dt * 0.6
            } else {
                a.kitAnim.clip.constant = 1000 // ya esta afuera: sin recorte
                if (a.glow) setItemGlow(item, damp(a.glow, 0, 4, dt)) // el brillo de la salida se apaga
                // quieto en su lugar: solo gira si el usuario lo arrastra (before.js: a.rx, a.ry y sus velocidades vx, vy).
                // Fisica: al soltarlo sigue girando por inercia y se frena por friccion; la inclinacion vuelve a 0
                // como un resorte amortiguado. Al dejar de verlo vuelve suave a su posicion.
                if (a.sel) {
                    if (a.dragging) {
                        if (performance.now() - (a.dragT || 0) > 90) a.vx = a.vy = 0 // sujeto y quieto: sin inercia
                    } else {
                        a.ry = (a.ry || 0) + (a.vy || 0) * dt
                        a.vy = (a.vy || 0) * Math.exp(-4 * dt) // friccion alta: la inercia dura poco
                        a.vx = (a.vx || 0) + (-16 * (a.rx || 0) - 5 * (a.vx || 0)) * dt
                        a.rx = Math.max(-1.4, Math.min(1.4, (a.rx || 0) + a.vx * dt))
                    }
                } else {
                    a.vx = a.vy = 0
                    a.dragging = false
                    a.rx = damp(a.rx || 0, 0, 6, dt)
                    a.ry = damp(a.ry || 0, Math.round((a.ry || 0) / (2 * Math.PI)) * 2 * Math.PI, 6, dt)
                }
                item.rotation.set(a.rx || 0, a.ry || 0, 0)
            }
            const o = damp(
                item.scale.x,
                a.sel ? 1.35 : item.children.length && a.base.y === 2.6 ? 1.15 : 1,
                8,
                dt,
            )
            item.scale.setScalar(o)
        })
        // Entrada: la mochila cae, rebota y gira hasta quedar de frente
        kit.intro = Math.min(1, kit.intro + dt / 1.5)
        const k = kit.intro
        const fall = Math.min(1, k / 0.45)
        const bounce = Math.min(1, Math.max(0, (k - 0.45) / 0.55))
        kit.bag.position.y =
            k < 0.45 ? 2.6 * (1 - fall * fall) : 0.35 * Math.sin(bounce * Math.PI) * (1 - bounce)
        kit.bag.rotation.y = 0 // la maleta no gira: cae, rebota y queda de frente
        updateKitBursts(kit, dt)
        if (k >= 0.45 && bounce < 0.35) squash = Math.max(squash, 1.6 * Math.sin((bounce / 0.35) * Math.PI))
        // Tapa: se levanta y se inclina hacia atras al abrir
        const lidDur = kitLidDuration()
        if (kit.timelineOn && lidDur && kit.timeline < lidDur && kit.lidTarget) {
            kit.open = Math.min(1, Math.max(0, kit.timeline / lidDur)) // se abre en su segundo exacto del archivo
        } else {
            kit.open = damp(kit.open, kit.lidTarget, 7, dt)
        }
        if (kit.bag.userData.mixer) {
            setBagLid(kit.bag, kit.open) // maleta del .glb: la animacion de su tapa
        } else {
            kit.lid.position.set(0, 1.42 + 0.5 * kit.open, -0.3 * kit.open)
            kit.lid.rotation.x = -1.0 * kit.open
            kit.handle.position.set(0, 1.78 + 0.5 * kit.open, -0.3 * kit.open)
            kit.handle.rotation.x = -1.0 * kit.open
        }
        // el maletin se auto-ilumina solo mientras se abre o se cierra su tapa y mientras salen o se guardan los objetos (y se apaga al quedar quieto)
        const lidMoving = (kit.open > 0.01 && kit.open < 0.99) || Math.abs(kit.lidTarget - kit.open) > 0.02
        const itemsMoving = kit.items.some((item) => item.userData.stage === 'emerging' || item.userData.stage === 'storing') // salen o se guardan objetos
        kit.bagLit = damp(kit.bagLit || 0, lidMoving || itemsMoving ? glowTuning.bagLight : 0, 8, dt)
        setObjectLight(kit.bag, kit.bagLit)
        kit.bag.scale.set(1 + 0.05 * squash, 1 - 0.06 * squash, 1 + 0.05 * squash)
    }
}

// ---- Efecto de salida de los objetos del kit ----
// Brillo calido (emisivo) del objeto mientras sale de la maleta: g de 0 a 1.
const GLOW_COLOR = new THREE.Color('#ffd9a0')
function setItemGlow(item, g) {
    const a = item.userData
    if (!a.glowMats) {
        a.glowMats = []
        item.traverse((o) => {
            if (!o.isMesh) return
            ;(Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => {
                if (m.emissive && !a.glowMats.includes(m)) a.glowMats.push(m)
            })
        })
    }
    a.glow = g < 0.01 ? 0 : g
    a.glowMats.forEach((m) => {
        m.emissive.copy(GLOW_COLOR)
        m.emissiveIntensity = a.glow * 0.22
    })
}
// Halo suave de luz que se abre desde la boca de la maleta y motas que suben (texturas con degradado, sin bordes duros).
function softTexture(stops) {
    const c = document.createElement('canvas')
    c.width = c.height = 128
    const g = c.getContext('2d')
    const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64)
    stops.forEach(([at, alpha]) => grad.addColorStop(at, `rgba(255,232,180,${alpha})`))
    g.fillStyle = grad
    g.fillRect(0, 0, 128, 128)
    return new THREE.CanvasTexture(c)
}
let haloTex = null
let moteTex = null
const haloGeo = new THREE.PlaneGeometry(1.8, 1.8)
const SPARKS = 14
const BURST_TIME = 1.6
function spawnKitBurst(kit) {
    haloTex ||= softTexture([[0, 0], [0.4, 0.05], [0.68, 0.32], [0.85, 0.1], [1, 0]])
    moteTex ||= softTexture([[0, 0.9], [0.35, 0.35], [1, 0]])
    const mouthY = 1.5 * kit.bag.scale.y + kit.bag.position.y
    const ring = new THREE.Mesh(
        haloGeo,
        new THREE.MeshBasicMaterial({
            map: haloTex,
            transparent: true,
            opacity: 0.4,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            side: THREE.DoubleSide,
        }),
    )
    ring.rotation.x = -Math.PI / 2
    ring.position.set(0, mouthY, 0)
    const pos = new Float32Array(SPARKS * 3)
    const vel = []
    for (let i = 0; i < SPARKS; i++) {
        const ang = Math.random() * Math.PI * 2
        const r = Math.random() * 0.5
        pos.set([Math.cos(ang) * r, mouthY, Math.sin(ang) * r], i * 3)
        vel.push([Math.cos(ang) * 0.25, 0.7 + Math.random() * 1, Math.sin(ang) * 0.25])
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    const sparks = new THREE.Points(
        geo,
        new THREE.PointsMaterial({
            map: moteTex,
            color: '#fff1c9',
            size: 0.07,
            transparent: true,
            opacity: 0.6,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
        }),
    )
    kit.add(ring, sparks)
    ;(kit.bursts ||= []).push({ ring, sparks, vel, t: 0 })
}
function updateKitBursts(kit, dt) {
    if (!kit.bursts || !kit.bursts.length) return
    kit.bursts = kit.bursts.filter((b) => {
        b.t += dt
        const k = b.t / BURST_TIME
        if (k >= 1) {
            kit.remove(b.ring, b.sparks)
            b.ring.material.dispose()
            b.sparks.geometry.dispose()
            b.sparks.material.dispose()
            return false
        }
        const ease = 1 - (1 - k) ** 3
        b.ring.scale.setScalar(1 + 1.6 * ease)
        b.ring.material.opacity = 0.4 * Math.sin(Math.min(1, k * 4) * Math.PI * 0.5) * (1 - k) ** 2 // aparece y se desvanece despacio
        const p = b.sparks.geometry.attributes.position
        for (let i = 0; i < SPARKS; i++) {
            p.setXYZ(i, p.getX(i) + b.vel[i][0] * dt, p.getY(i) + b.vel[i][1] * dt, p.getZ(i) + b.vel[i][2] * dt)
            b.vel[i][1] -= 0.8 * dt
        }
        p.needsUpdate = true
        b.sparks.material.opacity = 0.6 * (1 - k) ** 1.5
        return true
    })
}
// Recorte de los objetos del kit con la boca de la maleta (mientras estan dentro, en el segundo "time" del archivo)
const kitMouth = new THREE.Plane()
const kitUp = new THREE.Vector3(0, 1, 0)
const kitPoint = new THREE.Vector3()
function kitClip(kitAnim, time) {
    if (time < kitAnim.tClear) kitAnim.clip.copy(kitMouth)
    else kitAnim.clip.constant = 1000
}
const easeOutBack = (k) => 1 + 2.70158 * (k - 1) ** 3 + 1.70158 * (k - 1) ** 2
