/**
 * CARICIA: la mano del personaje (primera persona) se acerca a la cabeza de una mascota,
 * la acaricia moviendose de lado a lado y se retira. La mascota se pone contenta.
 *
 * Uso:  state.curTick = startPetting(dog, () => goTo('siguiente'))
 * Y al salir del paso:  stopPetting()
 */
import { meowCat } from '../three/models/catGlb.js'
import { barkDog } from '../three/models/dogGlb.js'
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { createHand } from '../three/models/hand.js'
import { armTuning, createFirstPersonArm } from '../three/models/personGlb.js'
import { setPetMood } from '../three/characters.js'
import { camera, mainScene } from '../three/renderer.js'
import { lockTour, petTuning } from './scrollTour.js'

// Duracion (segundos) de cada fase
const REACH = 0.9 // la mano se acerca
const STROKE = 1.3 // dos palmaditas a cada mascota
const RETREAT = 0.7 // se retira
const MOVE = 0.7 // pasa de una mascota a la otra
// Posicion de reposo de la mano en coordenadas de la camara (abajo a la derecha)
const REST = new THREE.Vector3(0.3, -0.5, -0.75)
const restPoint = () => (arm ? REST.set(armTuning.restX, armTuning.restY, armTuning.restZ) : REST.set(0.3, -0.5, -0.75))

let handRoot = null
let hand = null
let arm = null // el brazo del personaje (static/usuario.glb); si no cargo se usa la mano de siempre
const head = new THREE.Vector3()
const ray = new THREE.Raycaster()
const DOWN = new THREE.Vector3(0, -1, 0)
const meshesOf = (pet) => (pet.userData.petMeshes ||= (() => {
    const list = []
    // (el rayo solo toca el low poly: en una malla con huesos el rayo calcula cada vertice en la CPU, y con la capa detallada eran decenas de miles por cuadro)
    pet.traverse((o) => o.isMesh && !o.isPoints && !o.userData.hd && !o.userData.isHull && list.push(o))
    return list
})())
/** Altura de la parte de arriba de la cabeza de la mascota (con un rayo hacia abajo); null si no la encuentra. */
function topOf(pet, x, y, z) {
    ray.set(head.set(x, y + 0.5, z), DOWN)
    ray.far = 1
    const hit = ray.intersectObjects(meshesOf(pet), false).find((h) => h.object.visible)
    return hit ? hit.point.y : null
}
const target = new THREE.Vector3()
const pos = new THREE.Vector3()
const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}

function ensureHand() {
    if (handRoot) return
    handRoot = new THREE.Group() // sigue a la camara (misma posicion y rotacion)
    arm = createFirstPersonArm()
    if (arm) {
        handRoot.add(arm.root)
        hand = arm.root // (para la logica de visible)
    } else {
        hand = createHand()
        handRoot.add(hand)
    }
    handRoot.visible = false
    mainScene.add(handRoot)
}

export function stopPetting() {
    if (handRoot) handRoot.visible = false
}

/**
 * Empieza la caricia a una mascota (o a varias, una tras otra) y devuelve la funcion de cada
 * cuadro (dt). Llama onDone al terminar.
 */
export function startPetting(petOrPets, onDone, { hop = true } = {}) {
    const pets = Array.isArray(petOrPets) ? petOrPets : [petOrPets]
    ensureHand()
    lockTour()
    handRoot.visible = true
    hand.visible = false // hasta que la mano se acerque al animal
    pets.forEach((pet) => {
        const isCat = pet.userData.type === 'cat'
        setPetMood(pet, { wag: isCat ? 2.2 : 2.8, eyes: 0.55 }) // cola feliz y ojos entrecerrados
    })
    audio.ok()
    const n = pets.length
    const cycle = STROKE + MOVE
    const strokesEnd = n * STROKE + (n - 1) * MOVE
    const end = REACH + strokesEnd + RETREAT
    const targets = pets.map(() => new THREE.Vector3())
    const tops = pets.map(() => null) // altura suavizada de la cabeza de cada mascota
    let time = 0
    let cheered = false
    let finished = false
    return (dt) => {
        time += dt
        // la mano vive en coordenadas de la camara
        handRoot.position.copy(camera.position)
        handRoot.quaternion.copy(camera.quaternion)
        pets.forEach((pet, i) => {
            pet.userData.anchors.head.getWorldPosition(head)
            const hx = head.x
            const hz = head.z
            const hy = head.y - 0.1 // sobre la cabeza, no sobre la etiqueta
            // la muneca se apoya por ENCIMA de la malla de la cabeza (no la atraviesa): se mide donde esta la superficie
            const top = topOf(pet, hx, hy, hz)
            const goal = top == null ? hy : top + petTuning.handClear
            tops[i] = tops[i] == null ? goal : tops[i] + (goal - tops[i]) * Math.min(1, dt * 12)
            head.set(hx, tops[i], hz)
            targets[i].copy(camera.worldToLocal(head))
        })

        let stroking = 0 // intensidad de la caricia (0..1)
        let s = 0 // tiempo dentro de la caricia actual
        if (time < REACH) {
            pos.lerpVectors(restPoint(), targets[0], ease(time / REACH))
        } else if (time < REACH + strokesEnd) {
            const u = time - REACH
            const i = Math.min(n - 1, Math.floor(u / cycle))
            const local = u - i * cycle
            if (local < STROKE) {
                pos.copy(targets[i])
                s = local
                stroking = Math.min(1, local / 0.3, Math.max(0, (STROKE - local) / 0.3 + 0.2))
            } else {
                // pasa de una mascota a la siguiente
                pos.lerpVectors(targets[i], targets[i + 1], ease((local - STROKE) / MOVE))
            }
        } else {
            pos.lerpVectors(targets[n - 1], restPoint(), ease((time - REACH - strokesEnd) / RETREAT))
        }
        if (stroking > 0) {
            // dos palmaditas: la mano sube un poco y baja a tocar la cabeza, dos veces
            pos.y += (arm ? armTuning.patHeight : 0.07) * Math.abs(Math.sin((s / STROKE) * Math.PI * 2)) * stroking
        }
        if (arm) {
            // el brazo del personaje llega a ese punto (cinematica inversa); sube desde abajo de la pantalla.
            // Con el gato la mano gira un poco mas (su cabeza queda mas baja): se mezcla segun a quien se acerca la mano
            let catness = 0
            if (time >= REACH && time < REACH + strokesEnd) {
                const u = time - REACH
                const i = Math.min(n - 1, Math.floor(u / cycle))
                const local = u - i * cycle
                const isCat = (k) => (pets[k].userData.type === 'cat' ? 1 : 0)
                catness = local < STROKE || i + 1 >= n ? isCat(i) : isCat(i) + (isCat(i + 1) - isCat(i)) * ease((local - STROKE) / MOVE)
            } else if (time < REACH) catness = pets[0].userData.type === 'cat' ? ease(time / REACH) : 0
            arm.reach(pos, armTuning.rollCat * catness)
        } else {
            hand.rotation.z = 0
            hand.position.copy(pos)
        }
        // la mano solo aparece cuando ya se acerca al animal (no se ve en su posicion de reposo) y se esconde al retirarse
        let appear = 1
        if (time < REACH) appear = ease((time / REACH - 0.45) / 0.35)
        else if (time > REACH + strokesEnd) appear = 1 - ease((time - REACH - strokesEnd) / (RETREAT * 0.6))
        if (arm) {
            hand.visible = time < REACH + strokesEnd + RETREAT // el brazo sube desde abajo y vuelve a bajar: no hace falta esconderlo
        } else {
            hand.visible = appear > 0.02
            hand.scale.setScalar(Math.max(0.001, appear))
        }

        // al terminar: todos contentos (ladrido y maullido) y siguiente paso
        if (!cheered && time > end) {
            cheered = true
            handRoot.visible = false
            pets.forEach((pet, i) => {
                if (hop) pet.userData.hop = 1 // (en el saludo de la entrada no saltan: solo contentos, ladrando y maullando)
                setTimeout(() => {
                    // el sonido y la boca arrancan a la vez
                    if (pet.userData.type === 'cat') {
                        meowCat(pet)
                        audio.meow()
                    } else {
                        barkDog(pet)
                        audio.bark()
                    }
                }, i * 380)
            })
        }
        if (!finished && time > end + 0.9) {
            finished = true
            onDone()
        }
    }
}
