/**
 * COLLARES, PLACA, RASTREADOR, MICROCHIP Y JERINGA (modelo de Blender: static/rastreo.glb).
 * El .glb trae, sueltos y sin animacion:
 *   collar perro / collar gato        el anillo de la correa
 *   placa cacao / placa nube          la medalla con el nombre grabado (y su argolla)
 *   rastreador perro / rastreador gato  el localizador (con una patita)
 *   jeringa y microchip               para mostrar como se pone el microchip
 * Aqui se separan y se acomodan:
 *   - attachTrackGear()    pone el collar completo en el cuello de una mascota (dogGlb.js / catGlb.js)
 *   - createTrackPart()    una pieza sola, centrada, para verla de cerca y girarla (ui/miniViewer.js)
 *   - createSyringe()      la jeringa lista para la animacion (el embolo se mueve aparte del cuerpo)
 *   - createChipCapsule()  la capsula del microchip
 * Si el .glb no carga, las mascotas siguen con el collar sencillo de siempre.
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { standardizeMaterials } from '../helpers.js'

let model = null // { scene, nodes: { nombre: Object3D }, ring: { dog, cat }, syringe: {...} }

export const hasTrackModel = () => !!model

/**
 * Ajuste fino del collar de cada mascota (se edita en las paginas de depuracion y se copia como JSON):
 *   dx, dy, dz  mover (metros de la mascota: x de lado, y arriba, z al frente)
 *   rx, ry, rz  girar el collar entero (radianes) alrededor de los ejes de la mascota
 *   scale       tamano (1 = el calculado)
 */
export const COLLAR_DEFAULT = { dx: 0, dy: 0, dz: 0, rx: 0, ry: 0, rz: 0, scale: 1 }
export const collarTuning = {
    dog: { dx: 0.005, dy: 0.05, dz: -0.015, rx: 0.54, ry: 0, rz: 0, scale: 0.97 }, // ajustado en la pagina de depuracion
    cat: { dx: -0.005, dy: 0.015, dz: -0.03, rx: 0.48, ry: 0, rz: 0, scale: 1.06 }, // ajustado en la pagina de depuracion
}

const _tv = new THREE.Vector3()
const _te = new THREE.Euler()
const _tq = new THREE.Quaternion()
/** Aplica collarTuning[kind] al collar (el "holder" que devuelve attachTrackGear). Se puede llamar cuando sea. */
export function refitCollar(holder) {
    const f = holder?.userData.fit
    if (!f) return
    const t = collarTuning[f.kind]
    // posicion: el centro calculado + el desplazamiento (en los ejes de la mascota), pasado a unidades del hueso con la
    // pose de REPOSO del cuello (asi el resultado no depende de como este girada la cabeza en ese momento)
    // extra*: ajuste temporal mientras la mascota se lame la pata (el cuello se dobla y el collar debe acompanar la curva)
    const u = holder.userData
    _tv.copy(f.baseGroup).add(new THREE.Vector3(t.dx, t.dy + (u.extraDy || 0), t.dz + (u.extraDz || 0)).multiplyScalar(f.meterScale))
    holder.position.copy(_tv.applyMatrix4(f.neckRestInv))
    // giro: sobre la orientacion base (anillo vertical), alrededor de los ejes de la mascota
    holder.quaternion.copy(f.baseQ).multiply(_tq.setFromEuler(_te.set(t.rx + (u.extraRx || 0), t.ry, t.rz)))
    holder.scale.setScalar(f.baseScale * t.scale * (1 + (u.extraScale || 0))) // (extraScale: el collar se agranda un poco mientras la mascota se lame)
}

/** En el .glb el collar mide 0.97 de ancho: ese es el diametro con el que se calcula la escala de cada pieza. */
const RING = { dog: { collar: 'collar_perro', plate: 'placa_cacao', tracker: 'rastreador_perro' }, cat: { collar: 'collar_gato', plate: 'placa_nube', tracker: 'rastreador_gato' } }

const box = (obj) => new THREE.Box3().expandByObject(obj)

export async function loadTrackModel() {
    try {
        const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + 'rastreo.glb')
        const scene = gltf.scene
        scene.updateMatrixWorld(true)
        const nodes = {}
        standardizeMaterials(scene) // todo reacciona a las luces
        scene.traverse((o) => o.name && (nodes[o.name] = o))
        const ring = {}
        for (const kind of ['dog', 'cat']) {
            const b = box(nodes[RING[kind].collar])
            ring[kind] = { center: b.getCenter(new THREE.Vector3()), radius: (b.max.x - b.min.x) / 2 }
        }
        scene.traverse((o) => {
            if (!o.isMesh) return
            o.castShadow = true
            o.receiveShadow = true
            const mats = Array.isArray(o.material) ? o.material : [o.material]
            mats.forEach((m) => {
                m.roughness = Math.max(m.roughness ?? 0.5, 0.45)
            })
        })
        model = { scene, nodes, ring }
        prepareSyringe()
    } catch (error) {
        console.warn('No cargo static/rastreo.glb: se usa el collar sencillo.', error)
        model = null
    }
}

/** Copia de un nodo del archivo, con la posicion y el giro que tiene en el .glb (en el espacio del archivo). */
function cloneNode(name) {
    const src = model.nodes[name]
    const holder = new THREE.Group()
    const c = src.clone(true)
    holder.add(c)
    return holder
}

/**
 * Collar completo (correa, placa y rastreador) pegado a un hueso del cuello. Se coloca igual que el collar sencillo:
 * C = centro del collar y R = su radio, en metros de la mascota (meterScale pasa esas medidas a las del archivo de la
 * mascota) y k pasa de metros a unidades del hueso. Devuelve los puntos de interes (placa, rastreador y el lugar del
 * microchip, en la nuca) o null si el modelo no cargo.
 */
export function attachTrackGear(neck, { kind, C, R, k, meterScale = 1 }) {
    if (!model) return null
    const part = RING[kind]
    const ring = model.ring[kind]
    // el anillo queda con su eje vertical sin importar como esta girado el hueso; la placa mira al frente y el
    // rastreador queda al costado izquierdo de la mascota (en el archivo la placa esta a -x y el rastreador a +z)
    const holder = new THREE.Group()
    const worldPos = new THREE.Vector3(C.x, C.y, C.z).multiplyScalar(meterScale)
    const baseGroup = worldPos.clone() // (worldToLocal modifica el vector que recibe)
    holder.position.copy(neck.worldToLocal(worldPos))
    holder.quaternion.copy(neck.getWorldQuaternion(new THREE.Quaternion()).invert())
    holder.scale.setScalar(((R * meterScale) / ring.radius) * k)
    const outer = new THREE.Group()
    outer.rotation.y = Math.PI / 2
    const inner = new THREE.Group()
    inner.position.copy(ring.center).negate()
    outer.add(inner)
    holder.add(outer)
    inner.add(cloneNode(part.collar))
    inner.add(cloneNode(part.tracker))
    // la placa cuelga de un pivote en su argolla (la parte de arriba) y se balancea con la gravedad: ver updateCollarSwing
    const plateBox = box(model.nodes[part.plate])
    const pivot = new THREE.Object3D()
    pivot.position.set((plateBox.min.x + plateBox.max.x) / 2, plateBox.max.y, (plateBox.min.z + plateBox.max.z) / 2)
    inner.add(pivot)
    const plate = cloneNode(part.plate)
    plate.position.copy(pivot.position).negate()
    pivot.add(plate)
    // puntos de interes en el espacio del archivo (dentro de inner)
    const at = (name) => {
        const o = new THREE.Object3D()
        o.position.copy(box(model.nodes[name]).getCenter(new THREE.Vector3()))
        inner.add(o)
        return o
    }
    const tag = at(part.plate)
    const gps = at(part.tracker)
    const chip = new THREE.Object3D() // la nuca: del lado contrario a la placa
    chip.position.set(ring.center.x + ring.radius, ring.center.y + 0.04, ring.center.z)
    inner.add(chip)
    neck.add(holder)
    // para el ajuste fino (collarTuning): se guarda de donde se partio
    let root = neck
    while (root.parent) root = root.parent
    holder.userData.fit = {
        kind,
        neck,
        root,
        baseGroup, // centro del collar en el espacio de la mascota
        neckRestInv: neck.matrixWorld.clone().invert(), // del espacio de la mascota al del hueso, en reposo
        baseQ: holder.quaternion.clone(),
        baseScale: holder.scale.x,
        meterScale,
        swing: { pivot, q: new THREE.Quaternion(), w: new THREE.Vector3() }, // la placa: orientacion y velocidad angular
    }
    refitCollar(holder)
    return { tag, gps, chip, holder }
}

/**
 * Una pieza sola ("plate" o "tracker") de la mascota indicada, centrada en el origen y de frente a +z, con su lado
 * bonito (el nombre grabado, la patita) hacia la camara. size = lado mas largo en las unidades de la escena.
 */
export function createTrackPart(kind, partName, size = 1) {
    if (!model) return null
    const name = RING[kind][partName]
    const holder = cloneNode(name)
    const b = box(model.nodes[name])
    const inner = new THREE.Group()
    inner.add(holder)
    inner.position.copy(b.getCenter(new THREE.Vector3())).negate()
    const outer = new THREE.Group()
    outer.add(inner)
    // la placa tiene su cara a -x; el rastreador mira a +z en el archivo
    outer.rotation.y = partName === 'plate' ? Math.PI / 2 : 0
    const wrap = new THREE.Group()
    wrap.add(outer)
    const dim = b.getSize(new THREE.Vector3())
    wrap.scale.setScalar(size / Math.max(dim.x, dim.y, dim.z))
    return wrap
}

// ---------------------------------------------------------------- jeringa
/**
 * La jeringa es una sola malla: se parte en cuerpo (cilindro y aguja) y embolo (la varilla de abajo) para que el embolo
 * se pueda empujar. Tambien se mide donde esta la punta de la aguja.
 */
function prepareSyringe() {
    const node = model.nodes['jeringa']
    node.updateMatrixWorld(true)
    const geo = node.geometry
    const pos = geo.attributes.position
    const index = geo.index ? Array.from(geo.index.array) : Array.from({ length: pos.count }, (_, i) => i)
    const b = box(node)
    const flangeY = b.min.y + (b.max.y - b.min.y) * 0.285 // la pestana donde termina el cilindro y empieza la varilla
    const v = new THREE.Vector3()
    const yOf = (i) => v.fromBufferAttribute(pos, i).applyMatrix4(node.matrixWorld).y
    const barrel = []
    const plunger = []
    let tipIndex = 0
    let tipY = -Infinity
    for (let i = 0; i < pos.count; i++) {
        const y = yOf(i)
        if (y > tipY) {
            tipY = y
            tipIndex = i
        }
    }
    for (let f = 0; f < index.length; f += 3) {
        const cy = (yOf(index[f]) + yOf(index[f + 1]) + yOf(index[f + 2])) / 3
        ;(cy < flangeY ? plunger : barrel).push(index[f], index[f + 1], index[f + 2])
    }
    const mk = (idx) => {
        const g = new THREE.BufferGeometry()
        g.setAttribute('position', pos)
        if (geo.attributes.normal) g.setAttribute('normal', geo.attributes.normal)
        if (geo.attributes.uv) g.setAttribute('uv', geo.attributes.uv)
        g.setIndex(idx)
        return g
    }
    model.syringe = {
        barrel: mk(barrel),
        plunger: mk(plunger),
        material: node.material,
        matrix: node.matrixWorld.clone(),
        tip: new THREE.Vector3().fromBufferAttribute(pos, tipIndex).applyMatrix4(node.matrixWorld),
        length: b.max.y - b.min.y,
    }
}

/**
 * Jeringa lista para la animacion: el origen es la punta de la aguja y la aguja apunta a +Y (el cuerpo queda hacia -Y).
 * Devuelve { group, plunger, length }; plunger.position.y se sube para empujar el embolo (0 .. push).
 * length = largo total (en las unidades que pida "size"), push = cuanto sube el embolo para vaciarla.
 */
export function createSyringe(size = 1) {
    if (!model || !model.syringe) return null
    const s = model.syringe
    const file = new THREE.Group() // espacio del archivo
    file.matrixAutoUpdate = false
    file.matrix.copy(s.matrix)
    const barrel = new THREE.Mesh(s.barrel, s.material)
    const plungerHolder = new THREE.Group() // en el espacio del archivo; se desplaza en +Y para empujar
    const plunger = new THREE.Mesh(s.plunger, s.material)
    barrel.castShadow = plunger.castShadow = true
    file.add(barrel)
    plungerHolder.add(plunger)
    // el holder vive en el espacio del archivo, asi que va dentro de otro grupo sin la matriz del nodo
    const root = new THREE.Group()
    const inner = new THREE.Group()
    inner.position.copy(s.tip).negate()
    // la matriz del nodo solo se aplica al cuerpo; el embolo (mismos vertices) usa la misma matriz
    plunger.matrixAutoUpdate = false
    plunger.matrix.copy(s.matrix)
    inner.add(file)
    inner.add(plungerHolder)
    root.add(inner)
    const group = new THREE.Group()
    group.add(root)
    group.scale.setScalar(size / s.length)
    return { group, plunger: plungerHolder, push: s.length * 0.22 }
}

/** Capsula del microchip (la malla del archivo), centrada y con su lado largo en Y. size = su largo. */
export function createChipCapsule(size = 1) {
    if (!model) return null
    const name = 'microchip'
    const holder = cloneNode(name)
    const b = box(model.nodes[name])
    const inner = new THREE.Group()
    inner.add(holder)
    inner.position.copy(b.getCenter(new THREE.Vector3())).negate()
    const wrap = new THREE.Group()
    wrap.add(inner)
    const dim = b.getSize(new THREE.Vector3())
    wrap.scale.setScalar(size / Math.max(dim.x, dim.y, dim.z))
    return wrap
}

// ---------------------------------------------------------------- gravedad de la placa
const REST_DOWN = new THREE.Vector3(0, -1, 0) // la placa cuelga hacia -y en el espacio del archivo
const _gq = new THREE.Quaternion()
const _gv = new THREE.Vector3()
const _gaxis = new THREE.Vector3()
const _gdq = new THREE.Quaternion()
/**
 * La placa cuelga de la argolla y se balancea como un pendulo: siempre intenta quedar apuntando hacia abajo (la gravedad
 * del mundo) y, al mover o girar el collar, se queda atras y se mece hasta calmarse. Resorte con amortiguacion.
 * Se llama cada cuadro con el collar que devuelve attachTrackGear (holder).
 */
export function updateCollarSwing(holder, dt, plate = 1) {
    const f = holder?.userData.fit
    if (!f) return
    const sw = f.swing
    const pivot = sw.pivot
    pivot.parent.updateWorldMatrix(true, false)
    pivot.parent.getWorldQuaternion(_gq).invert() // del mundo al espacio del padre del pivote
    const gravity = _gv.set(0, -1, 0).applyQuaternion(_gq) // la gravedad vista desde el collar
    const desired = _gdq.setFromUnitVectors(REST_DOWN, gravity) // orientacion que la deja colgando recta
    // error = giro que falta para llegar a "desired"
    const err = desired.multiply(_gq.copy(sw.q).invert())
    if (err.w < 0) err.set(-err.x, -err.y, -err.z, -err.w)
    const angle = 2 * Math.acos(Math.min(1, err.w))
    const s = Math.sqrt(Math.max(1e-9, 1 - err.w * err.w))
    _gaxis.set(err.x / s, err.y / s, err.z / s)
    const step = Math.min(dt, 0.033) // pasos chicos para que el resorte sea estable
    sw.w.addScaledVector(_gaxis, (angle > 1e-5 ? angle : 0) * 70 * step) // resorte
    sw.w.multiplyScalar(Math.exp(-4.5 * step)) // amortiguacion
    const wl = sw.w.length()
    if (wl > 1e-6) {
        _gdq.setFromAxisAngle(_gaxis.copy(sw.w).divideScalar(wl), wl * step)
        sw.q.premultiply(_gdq).normalize()
    }
    pivot.quaternion.copy(sw.q)
    // plate (0 a 1): la placa se separa del collar mientras la mascota se lame (se encoge y se esconde) para no atravesar el cuerpo; vuelve al terminar
    pivot.scale.setScalar(Math.max(1e-4, plate))
    pivot.visible = plate > 0.03
}