/**
 * VISOR 3D PEQUENO: un objeto solo dentro de un recuadro (su propio canvas y su propio renderer) que el usuario puede
 * girar arrastrando. Al soltarlo sigue girando un poco por inercia y se frena; la inclinacion vuelve a su sitio.
 * Se usa en la presentacion del rastreo (placa, rastreador y microchip).
 */
import * as THREE from 'three'

export function createMiniViewer(canvas, object, { fov = 30, tilt = 0.12, margin = 1.25 } = {}) {
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true })
    renderer.outputColorSpace = THREE.LinearSRGBColorSpace
    renderer.setClearColor(0, 0)
    const scene = new THREE.Scene()
    scene.add(new THREE.HemisphereLight('#ffffff', '#a9bddf', 0.9 * Math.PI))
    const key = new THREE.DirectionalLight('#ffffff', 0.95 * Math.PI)
    key.position.set(2, 3, 4)
    const rim = new THREE.DirectionalLight('#cfe4ff', 0.5 * Math.PI)
    rim.position.set(-3, 1, -2)
    scene.add(key, rim)
    const pivot = new THREE.Group()
    pivot.add(object)
    scene.add(pivot)
    const camera = new THREE.PerspectiveCamera(fov, 1, 0.01, 100)
    const radius = new THREE.Box3().setFromObject(object).getBoundingSphere(new THREE.Sphere()).radius || 1
    camera.position.set(0, 0, (radius * margin) / Math.sin((fov * Math.PI) / 360))

    let ry = -0.5 // gira un poco al abrirse para que se note que es 3D
    let rx = tilt
    let vy = 1.6 // un impulso inicial, que se frena solo
    let vx = 0
    let dragging = false
    let lastT = 0
    let last = performance.now()
    let id = 0
    let alive = true
    const GAIN = 0.011

    const resize = () => {
        const w = canvas.clientWidth || 200
        const h = canvas.clientHeight || 200
        const dpr = Math.min(window.devicePixelRatio || 1, 2)
        if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
            renderer.setPixelRatio(dpr)
            renderer.setSize(w, h, false)
            camera.aspect = w / h
            camera.updateProjectionMatrix()
        }
    }
    let px = 0
    let py = 0
    const down = (e) => {
        dragging = true
        px = e.clientX
        py = e.clientY
        lastT = performance.now()
        vy = vx = 0
        canvas.setPointerCapture?.(e.pointerId)
        canvas.style.cursor = 'grabbing'
    }
    const move = (e) => {
        if (!dragging) return
        const now = performance.now()
        const sec = Math.max(0.008, (now - lastT) / 1000)
        lastT = now
        const dx = e.clientX - px
        const dy = e.clientY - py
        px = e.clientX
        py = e.clientY
        ry += dx * GAIN
        rx = Math.max(-1.1, Math.min(1.1, rx + dy * GAIN))
        vy = vy * 0.5 + Math.max(-5, Math.min(5, (dx * GAIN) / sec)) * 0.5
        vx = vx * 0.5 + Math.max(-5, Math.min(5, (dy * GAIN) / sec)) * 0.5
    }
    const up = () => {
        if (!dragging) return
        dragging = false
        canvas.style.cursor = 'grab'
        if (performance.now() - lastT > 90) vx = vy = 0 // lo solto estando quieto
    }
    canvas.style.cursor = 'grab'
    canvas.style.touchAction = 'none'
    canvas.addEventListener('pointerdown', down)
    addEventListener('pointermove', move)
    addEventListener('pointerup', up)
    addEventListener('pointercancel', up)

    const frame = (now) => {
        if (!alive) return
        const dt = Math.min(0.05, (now - last) / 1000)
        last = now
        resize()
        if (dragging) {
            if (now - lastT > 90) vx = vy = 0
        } else {
            ry += vy * dt
            vy *= Math.exp(-2.4 * dt)
            vx += (-14 * (rx - tilt) - 5 * vx) * dt // la inclinacion vuelve como un resorte
            rx += vx * dt
        }
        pivot.rotation.set(rx, ry, 0)
        renderer.render(scene, camera)
        id = requestAnimationFrame(frame)
    }
    id = requestAnimationFrame(frame)

    return {
        dispose() {
            alive = false
            cancelAnimationFrame(id)
            canvas.removeEventListener('pointerdown', down)
            removeEventListener('pointermove', move)
            removeEventListener('pointerup', up)
            removeEventListener('pointercancel', up)
            renderer.dispose()
            renderer.forceContextLoss() // (libera el contexto WebGL de este visor: el navegador solo permite ~16 a la vez y cada pieza que se mira abria uno nuevo)
        },
    }
}
