/**
 * SALA DE PRIMERA PERSONA: escenario exportado de Blender (static/casa.glb).
 * Se muestra solo en el modo de camara 'fp' (recorridos por scroll); el resto de la experiencia
 * usa la casa de cajas de world.js.
 *
 * El .glb no trae colores, asi que aqui se pintan por nombre de objeto (tabla COLORS). Si renombras
 * objetos en Blender, actualiza esa tabla. Medidas en metros:
 *   sala:  x -2..3.4, z -2.9..2.9    puerta de entrada: pared derecha (x 3.45, z -2), da a la terraza
 *   mesa de primeros auxilios: esquina del fondo izquierdo    sofa: mira hacia el televisor
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { DOOR_SPEED, LIGHT_SCALE } from '../config.js'
import { state } from '../core/state.js'
import { standardizeMaterials } from './helpers.js'
import { buildNeighborhood } from './neighborhood.js'
import { INTERIOR, PLANK_TILE, fabricShadow, addMirroredKnob, createCeilingSpot, applyFabric, applyWallDetail, paintPictures, shadedWall, woodMaterial, woodenFurniture } from './interiorLook.js'
import { createBackpack, createContactShadow } from './models/props.js'
import { mainScene, registerExterior, registerInterior } from './renderer.js'
import { registerRigLight } from './lightRig.js'

export const livingRoom = {
    root: new THREE.Group(),
    mixer: null, // reproduce la animacion de la puerta que viene en el .glb
    doorAction: null,
    bag: null, // el kit de emergencia sobre la mesa
    fileLights: false, // el .glb trae sus propias luces
}
livingRoom.root.visible = false
mainScene.add(livingRoom.root)

// Objetos que no se usan (en el .glb hay una cama fuera de la casa)
const HIDDEN = /^Cube006_Cube/

const POT = '#e9dcc0' // ceramica crema
const LEAVES = '#4f7f3f' // verde de hojas

// Colores por objeto: un valor, o una lista (un color por pieza del objeto, en orden)
const COLORS = {
    sofa: ['#7aa6ea', '#a4c2f2'], // azul claro: con el tejido de la tela se ve mas oscuro
    sillon: ['#7aa6ea', '#a4c2f2'],
    'mesa-primeros-auxilios': [INTERIOR.woodLight, INTERIOR.wood, '#ffffff'],
    'mesa-televisor': [INTERIOR.woodLight, '#ffffff'],
    mesita: INTERIOR.wood,
    televisor: '#14305e',
    // cuadros: el marco gris y la lamina de color
    cuadro1: INTERIOR.frame,
    cuadro2: INTERIOR.frame,
    cuadro3: INTERIOR.frame,
    imagen: '#9fd0f2',
    imagen001: '#ffd9a0',
    imagen002: '#c9dbff',
    madera_sofa: INTERIOR.wood,
    madera_sillon: INTERIOR.wood,
    matera1: POT,
    matera2: POT,
    matera3: POT,
    hojas: LEAVES,
    hojas001: LEAVES,
    hojas002: LEAVES,
    ventana1: '#e4f1ff',
    ventana2: '#e4f1ff',
    ventana3: '#e4f1ff',
    ventana4: '#e4f1ff',
    puerta1: INTERIOR.woodDark,
    puerta1001: INTERIOR.doorWood,
    reja_casa: INTERIOR.metal,
    muro: '#d6e4ff',
    reja: INTERIOR.metal, // rejas de metal gris azulado (como la textura de reja)
    puerta2: INTERIOR.woodDark,
    puerta2001: INTERIOR.doorWood,
}
const WALL = INTERIOR.wall // (las paredes de adentro llevan ademas un degradado: ver shadedWall)
const FLOOR = INTERIOR.floor
const CEILING = INTERIOR.ceiling

const materials = {}
const material = (hex, vertexColors = false, doubleSide = false) => {
    const key = hex + vertexColors + doubleSide
    return (materials[key] ||= new THREE.MeshStandardMaterial({
        color: vertexColors ? '#ffffff' : hex,
        vertexColors,
        side: doubleSide ? THREE.DoubleSide : THREE.FrontSide,
        roughness: 0.82,
        metalness: 0,
    }))
}

// Pinta una malla por vertice segun una funcion (normal, posicion) -> color
function paintVertices(mesh, pick, doubleSide = false) {
    const geo = mesh.geometry
    const pos = geo.attributes.position
    const nor = geo.attributes.normal
    const colors = new Float32Array(pos.count * 3)
    const c = new THREE.Color()
    for (let i = 0; i < pos.count; i++) {
        c.set(pick(nor.getY(i), pos.getY(i)))
        colors.set([c.r, c.g, c.b], i * 3)
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    mesh.material = material('#ffffff', true, doubleSide)
}

/** Losas de piedra clara para el piso de afuera (la terraza): losas grandes de tonos apenas distintos, con la junta mas oscura y un poco de grano. */
let paving = null
function pavingTexture() {
    if (paving) return paving
    const size = 512
    const canvas = document.createElement('canvas')
    canvas.width = canvas.height = size
    const g = canvas.getContext('2d')
    g.fillStyle = '#b8b5af' // junta
    g.fillRect(0, 0, size, size)
    const n = 2
    const tones = ['#dcdad6', '#d4d2ce', '#e0deda', '#d0cec9']
    for (let y = 0; y < n; y++)
        for (let x = 0; x < n; x++) {
            const px = (x * size) / n + 3
            const py = (y * size) / n + 3
            const side = size / n - 6
            g.fillStyle = tones[(x * 3 + y * 5 + 1) % tones.length]
            g.fillRect(px, py, side, side)
            // grano: puntitos claros y oscuros
            for (let i = 0; i < 700; i++) {
                g.fillStyle = i % 2 ? 'rgba(255,255,255,0.18)' : 'rgba(90,86,80,0.10)'
                g.fillRect(px + ((i * 97 + x * 31) % side), py + ((i * 53 + y * 17) % side), 2, 2)
            }
        }
    paving = new THREE.CanvasTexture(canvas)
    paving.wrapS = paving.wrapT = THREE.RepeatWrapping
    paving.anisotropy = 8
    return paving
}

/**
 * Los pisos del .glb: el interior ('piso interior') lleva tablones de madera con brillo; el exterior ('piso exterior', la terraza) lleva losas de
 * piedra clara. Las coordenadas de textura se calculan del plano (x, z), asi las medidas son iguales en todo el piso.
 */
const PAVING_TILE = 1.6 // m que cubre una repeticion de las losas (cada losa mide 0.8 m)
function paintFloor(mesh, outdoor = false) {
    const geo = mesh.geometry
    const pos = geo.attributes.position
    const uv = new Float32Array(pos.count * 2)
    const at = new THREE.Vector3()
    const tile = outdoor ? PAVING_TILE : PLANK_TILE
    mesh.updateMatrix() // (el nodo del piso puede traer su propia escala)
    for (let i = 0; i < pos.count; i++) {
        at.fromBufferAttribute(pos, i).applyMatrix4(mesh.matrix)
        uv.set([at.x / tile, at.z / tile], i * 2)
    }
    geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2))
    mesh.material = outdoor ? new THREE.MeshStandardMaterial({ map: pavingTexture(), roughness: 0.9, metalness: 0 }) : woodMaterial()
}
function colorize(top) {    const meshes = []
    top.traverse((o) => o.isMesh && meshes.push(o))
    const name = top.name
    meshes.forEach((mesh, i) => {
        mesh.receiveShadow = true
        mesh.castShadow = !name.startsWith('ventana') && !name.startsWith('piso')
        if (name === 'casa') {
            // suelo, techo y paredes segun la direccion de la superficie
            // (una parte del techo viene del .glb con la cara hacia arriba: con las dos caras visibles el techo queda cerrado y tapa el sol)
            paintVertices(mesh, (ny, y) => (ny > 0.8 && y < 0.2 ? FLOOR : ny < -0.8 || (ny > 0.8 && y > 2.5) ? CEILING : shadedWall(y)), true)
        } else if (name.startsWith('piso')) {
            paintFloor(mesh, name === 'piso_exterior')
        } else {
            const entry = COLORS[name] || '#ffffff'
            // las rejas son laminas delgadas: se pintan por ambos lados
            const doubleSide = /^(reja|puerta|ventana|cuadro|imagen)/.test(name) // (las puertas se pintan por las dos caras: una cara del modelo esta al reves y se veia transparente)
            mesh.material = material(
                Array.isArray(entry) ? entry[Math.min(i, entry.length - 1)] : entry,
                false,
                doubleSide,
            )
        }
    })
}

// Aspereza de cada superficie (roughness): la tela del sofa y el piso casi no brillan; la madera, un poco; el vidrio, bastante.
// (todo sigue siendo MeshStandardMaterial y conserva su color; los materiales se comparten, asi que se ajustan una vez)
const ROUGHNESS = [
    [/^(sofa|sillon)/, 0.95, true], // tela (con el tejido de static/tela.png)
    [/^mesa|^mesita|^puerta/, 0.68], // madera barnizada
    [/^ventana/, 0.6], // vidrio: no muy liso, o el sol deja un brillo blanco quemado en la ventana
    [/^televisor/, 0.35], // pantalla
    [/^matera/, 0.8],
]
function shadeSurfaces(scene) {
    scene.children.forEach((top) => {
        const hit = ROUGHNESS.find(([pattern]) => pattern.test(top.name))
        if (!hit) return
        top.traverse((o) => {
            if (o.isMesh && o.material && !Array.isArray(o.material)) {
                o.material = o.material.clone() // (el material se comparte con otros objetos del mismo color)
                o.material.roughness = hit[1]
                o.material.metalness = 0
                if (hit[2]) applyFabric(o.material, 0.3, true) // (con la sombra aligerada en las caras de frente, como el respaldo: ver updateLivingRoom)
            }
        })
    })
}

/**
 * Sombras de contacto suaves bajo los muebles de la sala (oclusion ambiental falsa): le dan peso a los muebles y los "asientan" en el
 * piso, sin las sombras gigantes o duras que dan las luces. Se calculan de la caja de cada mueble que toca el piso.
 */
function addContactShadows(scene) {
    const SKIP = /^(casa|ventana|cuadro|reja|muro|puerta)/
    const box = new THREE.Box3()
    const size = new THREE.Vector3()
    const center = new THREE.Vector3()
    scene.updateMatrixWorld(true)
    scene.children.forEach((top) => {
        if (!top.visible || SKIP.test(top.name) || HIDDEN.test(top.name)) return
        box.setFromObject(top)
        box.getSize(size)
        box.getCenter(center)
        if (box.min.y > 0.12 || box.max.y > 1.6 || size.x > 4 || size.z > 4 || size.x * size.z < 0.05) return
        const shadow = createContactShadow(size.x * 1.3, size.z * 1.3, top.name.startsWith('matera') ? 0.3 : 0.4)
        shadow.position.set(center.x, 0.012, center.z)
        livingRoom.root.add(shadow)
    })
}

/**
 * Un vidrio claro en cada ventana (el .glb solo trae el marco): casi transparente y sin sombra, asi la luz entra y las sombras de los
 * marcos y de la sala no se ven a cuadritos. Se calcula de la caja de cada ventana (el lado delgado es el de la pared).
 */
function addWindowGlass(scene) {
    const glass = new THREE.MeshStandardMaterial({
        color: '#d7eaff',
        transparent: true,
        opacity: 0.16,
        roughness: 0.05,
        metalness: 0,
        depthWrite: false,
        side: THREE.DoubleSide,
    })
    // fondo plano de las ventanas de los lados: un crema calido (distinto del azul claro del vidrio y de la pared), sin luz
    const backdrop = new THREE.MeshBasicMaterial({ color: '#f0dcbc', side: THREE.DoubleSide, fog: false })
    const box = new THREE.Box3()
    scene.updateMatrixWorld(true)
    scene.children
        .filter((top) => /^ventana/.test(top.name))
        .forEach((top) => {
            box.setFromObject(top)
            const size = box.getSize(new THREE.Vector3())
            const center = box.getCenter(new THREE.Vector3())
            const alongX = size.x > size.z // ventana en una pared de z (grande en x) o de x (grande en z)
            const w = (alongX ? size.x : size.z) - 0.14
            const h = size.y - 0.14
            const pane = new THREE.Mesh(new THREE.PlaneGeometry(w, h), glass)
            pane.position.copy(center)
            if (!alongX) pane.rotation.y = Math.PI / 2
            pane.renderOrder = 3
            livingRoom.root.add(pane)
            // las ventanas de los lados (en las paredes de z) llevan un fondo plano un poco afuera: se tapa lo feo de las casas vecinas. Es un color sin luz
            // (MeshBasicMaterial) y no proyecta sombra: no cambia la iluminacion, la luz del sol y de los focos entra igual.
            if (alongX) {
                const side = Math.sign(center.z) || 1
                const back = new THREE.Mesh(new THREE.PlaneGeometry(size.x + 0.3, size.y + 0.3), backdrop)
                back.position.set(center.x, center.y, center.z + side * 0.2)
                back.rotation.y = side > 0 ? Math.PI : 0
                back.renderOrder = 2
                livingRoom.root.add(back)
            }
        })
}

const LEAF_FIT = 1.05 // cuanto se ensancha la hoja de la puerta de entrada

export async function loadLivingRoom() {
    const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + 'casa-luces.glb')
    const scene = gltf.scene
    ;[...scene.children].forEach((top) => {
        if (HIDDEN.test(top.name)) top.visible = false
        else colorize(top)
    })
    standardizeMaterials(scene) // todo reacciona a las luces
    shadeSurfaces(scene)
    woodenFurniture(scene) // veta de madera en los muebles
    paintPictures(scene) // las ilustraciones de los cuadros
    // la casa (paredes por dentro y por fuera, techo): revoque con textura
    scene.getObjectByName('casa')?.traverse((o) => {
        if (o.isMesh && o.material && !Array.isArray(o.material)) applyWallDetail((o.material = o.material.clone()), 'muro-exterior.png', 2, 0.28)
    })

    livingRoom.root.add(scene)
    addWindowGlass(scene)
    scene.children.filter((top) => /^puerta\d001$/.test(top.name)).forEach((top) => {
            const meshes = []
            top.traverse((o) => o.isMesh && meshes.push(o))
            meshes.forEach(addMirroredKnob) // pomo en las dos caras de las hojas
        })
    // la hoja de la puerta de entrada queda un poco corta para su marco y deja una rendija por donde se ve la luz de adentro (parece que se
    // transparenta): se ensancha lo justo para que cierre del todo
    const leaf = scene.getObjectByName('puerta1001')
    if (leaf) leaf.scale.x *= LEAF_FIT
    addContactShadows(scene)

    // La puerta de entrada (pared derecha) se anima con la animacion que trae el .glb
    // ("puerta1.001_accion", hecha en Blender): se reproduce una vez al abrirla.
    livingRoom.mixer = new THREE.AnimationMixer(scene)
    if (gltf.animations.length) {
        const action = livingRoom.mixer.clipAction(gltf.animations[0])
        action.setLoop(THREE.LoopOnce, 1)
        action.clampWhenFinished = true
        action.play()
        action.paused = true
        livingRoom.doorAction = action
    }

    // El kit de emergencia sobre la mesa de primeros auxilios
    const bag = createBackpack()
    bag.scale.setScalar(0.22)
    bag.position.set(-1.75, 0.58, -2.15)
    bag.rotation.y = Math.PI / 2 // el bolsillo mira hacia la sala
    livingRoom.bag = bag
    livingRoom.root.add(bag)

    // Suelo exterior (el .glb solo trae la casa y el porche)
    const ground = new THREE.Mesh(
        new THREE.CircleGeometry(140, 48),
        new THREE.MeshStandardMaterial({ color: '#c9cdd6', roughness: 1 }),
    )
    ground.rotation.x = -Math.PI / 2
    ground.position.y = -0.03
    ground.receiveShadow = true
    livingRoom.root.add(ground)

    // Vecindario: calle, casas vecinas, arboles...
    buildNeighborhood(livingRoom.root)

    // Luces del interior: si el .glb trae luces (Blender, con la opcion de luces puntuales al exportar), se usan SOLO esas; si no trae
    // ninguna, se usan las de abajo (lamparas calidas y un foco con sombras)
    const fileLights = []
    scene.traverse((o) => o.isLight && fileLights.push(o))
    livingRoom.fileLights = fileLights.length > 0 // (con luces propias, camera.js apaga el sol y el ambiente de la casa de cajas mientras se ve la sala)
    if (fileLights.length) {
        fileLights.forEach((light) => {
            // Blender las exporta en candelas (57846 cd el foco, 5435 cd la lampara): se llevan a la escala de esta escena
            // (el foco esta a ~17 m de la casa, la lampara a ~2.4 m del piso)
            light.intensity *= light.isSpotLight ? 1 / 70 : 1 / 600
            light.castShadow = true
            light.shadow.intensity = 0.7 // sombras suaves (no negras)
            light.shadow.radius = 2.5 // bordes desenfocados
            light.shadow.bias = -0.002 // (evita las rayas horizontales de la sombra sobre la puerta y las paredes)
            light.shadow.normalBias = 0.12
            if (light.isSpotLight) {
                ;(livingRoom.sunSpots ||= []).push(light) // (su sombra se suaviza despues del kit: ver updateLivingRoom)
                light.shadow.mapSize.set(2048, 2048)
                light.shadow.camera.near = 4
                light.shadow.camera.far = 45
                registerExterior(light) // los focos son el sol (luz exterior)
            } else {
                light.shadow.mapSize.set(1024, 1024)
                light.shadow.camera.near = 0.15
                light.shadow.camera.far = 12
                registerInterior(light) // los puntos son las lamparas del techo
            }
        })
        // editables con la tecla L (grupo 'sala'): los focos son el sol que entra por las ventanas y los puntos las lamparas del techo
        let nSpot = 0
        let nPoint = 0
        fileLights.forEach((light) => {
            if (light.isSpotLight && nSpot >= 1) ((light.userData.gate = 0), (livingRoom.doorGateLights ||= []).push(light)) // (el sol 2 arranca apagado: ver updateLivingRoom)
            if (light.isSpotLight) registerRigLight('sala', 'sala-sol' + ++nSpot, 'Sol ' + nSpot + ' (foco exterior)', light)
            else registerRigLight('sala', 'sala-lampara' + ++nPoint, 'Lampara del techo ' + nPoint + ' (puntual)', light)
        })
    } else {
        // Luz calida del interior (la lampara del techo): suave y amplia, sin sombras, para que las zonas que no reciben el sol tambien se vean
        // claras (paredes, sofas, patas de los muebles) sin quemar los colores
        // Dos luces justo debajo del techo, una sobre el pasillo del kit y otra sobre el sofa: asi toda la sala (no solo el centro) queda iluminada
        // (la luz de adentro es calida y la de afuera fria: asi la casa se ve acogedora; ademas hay una lampara sobre el pasillo de las mascotas)
        ;[
            [0.7, -1.3],
            [0.7, 1.5],
            [3.4, -0.8],
        ].forEach(([x, z]) => {
            const lamp = new THREE.PointLight('#ffe2b8', 0.2 * LIGHT_SCALE, 9, 0)
            lamp.position.set(x, 2.3, z)
            livingRoom.root.add(registerInterior(lamp))
        })
        // y un foco en el techo que proyecta sombras al piso (muebles, mascotas y personaje)
        registerInterior(createCeilingSpot(livingRoom.root, -0.8, 2.4, -2.0, 0.5 * LIGHT_SCALE, [1.2, 0.6]))

    }}

/**
 * Abre la puerta de entrada reproduciendo la animacion del .glb (DOOR_SPEED = velocidad).
 * `instant` salta directo al estado final: abierta (open = true) o cerrada (open = false).
 */
export function setDoorOpen(open, instant = false) {
    const action = livingRoom.doorAction
    if (!action) return
    const end = action.getClip().duration
    if (instant) {
        action.reset()
        action.play()
        action.paused = true
        action.time = open ? end : 0
        livingRoom.mixer.update(0)
        return
    }
    if (!open || action.time >= end - 1e-3) return // solo se anima la apertura; si ya esta abierta no se repite
    action.reset()
    action.timeScale = DOOR_SPEED
    action.paused = false
    action.play()
}

/**
 * El sol 2 (compuerta userData.gate de 0 a 1):
 *  - portada e introduccion: apagado con la puerta cerrada y entra con la luz mientras la puerta se abre (sigue su animacion);
 *  - despues de ver el kit (las mascotas, el rastreo, el cierre del "Antes" en el sofa y las escenas de la sala del "Despues"): se apaga, porque ahi
 *    su luz proyectaba una segunda sombra rara sobre el sofa;
 *  - en el resto (el kit) se queda encendido.
 * El cambio es suave (la compuerta se acerca a su valor).
 */
const AFTER_KIT = new Set(['petwalk', 'track', 'trackCat', 'antesEnd', 'despIntro', 'guide', 'quiz'])
let sun2Gate = 0
let softShadow = 0
export function updateLivingRoom(dt) {
    if (livingRoom.mixer) livingRoom.mixer.update(dt)
    const action = livingRoom.doorAction
    const open = action ? Math.min(1, Math.max(0, action.time / (action.getClip().duration || 1))) : 1
    const target = state.cur === 'home' || state.cur === 'start' ? open : AFTER_KIT.has(state.cur) ? 0 : 1
    sun2Gate += (target - sun2Gate) * Math.min(1, dt * 3)
    for (const light of livingRoom.doorGateLights || []) light.userData.gate = sun2Gate
    // Sombra de los soles: despues del kit es mas suave y no se corre sobre superficies verticales como el respaldo del sofa (antes del kit se queda como siempre: 0.7 y 0.12)
    softShadow += ((AFTER_KIT.has(state.cur) ? 1 : 0) - softShadow) * Math.min(1, dt * 3)
    fabricShadow.value = softShadow // y las telas (el respaldo del sofa) aligeran la sombra en sus caras de frente
    for (const light of livingRoom.sunSpots || []) {
        light.shadow.intensity = 0.7 + (0.4 - 0.7) * softShadow
        light.shadow.normalBias = 0.12 + (0.05 - 0.12) * softShadow
    }
}