/**
 * CAMILLA Y TRANSPORTADORA (modelos de Blender: static/camilla.glb y static/transportadora.glb), en la pantalla de tamanos.
 * Cada .glb trae el accesorio animado (la camilla se arma y la transportadora abre su puerta) y un gato de muestra que se sube o entra.
 * Igual que con el arnes, ese gato no se usa: su movimiento (posicion y giro de cada cuadro) se le aplica a la mascota de la experiencia,
 * que hace lo mismo: Cacao se sube a la camilla y Nube o el perro pequeno entran a la transportadora.
 *
 *   loadAccessoryModels()                         carga los dos .glb (una vez)
 *   createAccessory({ pet, kind, home, stage, scale })   kind: 'camilla' | 'transportadora'; home = {x, z} donde esta la mascota; stage = {x, z} el lugar libre\n *                                                 del cuarto donde se muestra (la mascota pasa ahi mientras dura); scale = tamano
 *     .play()  .update(dt)  .dispose(restore)     empieza / avanza la animacion / quita el accesorio (restore = la mascota vuelve a su lugar)
 *     .active  .done
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { INTERIOR } from '../interiorLook.js'
import { mainScene } from '../renderer.js'

const sources = {}

const CONFIG = {
    camilla: {
        file: 'camilla.glb',
        // colores por pieza (el .glb no trae colores)
        colors: { palo_de_escoba: INTERIOR.wood, palo_de_escoba001: INTERIOR.wood, tela_camilla: '#ff8a6f', tela_A: '#ff8a6f' },
        duration: 5.6,
        speed: 1,
    },
    transportadora: {
        file: 'transportadora.glb',
        colors: { Cube: '#4a7fd0', Cube001: '#79a6ee', Cylinder010: '#eef1f6' },
        duration: 1.6,
        speed: 0.3, // mucho mas lenta: la mascota tarda unas 3 veces mas en entrar
    },
}
const STAND_IN = 'Cube006' // el gato de muestra (se oculta)
// donde esta el centro del cuerpo del gato de muestra respecto al origen de su malla (unidades del modelo, antes de su escala 0.13):
// los pies a y = -2.99 y el centro del cuerpo a z = -1.2 (la nariz esta en +z y la cola en -z)
const RUG_Y = 0.05 // el accesorio se apoya encima de la alfombra (que mide ~0.04 m de alto), para que no la atraviese
const FEET_Y = -2.99
const BODY_Z = -1.2
const STAND_IN_LENGTH = 0.67 // m: lo que mide el gato de muestra (de la nariz a la punta de la cola)

export async function loadAccessoryModels() {
    await Promise.all(
        Object.entries(CONFIG).map(async ([kind, cfg]) => {
            try {
                sources[kind] = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + cfg.file)
            } catch (error) {
                console.warn('No cargo static/' + cfg.file + ': no hay animacion de ' + kind, error)
            }
        }),
    )
}
export const hasAccessory = (kind) => !!sources[kind]

export function createAccessory({ pet, kind, home, stage = home, scale = 1 }) {
    const source = sources[kind]
    const cfg = CONFIG[kind]
    if (!source) return null
    const a = pet.userData
    const demo = { active: false, done: false, time: 0 }
    let root = null
    let mixer = null
    let actions = []
    let node = null
    let restYaw = 0
    const rest = new THREE.Vector3(stage.x, 0, stage.z) // donde empieza la mascota durante la demostracion
    const homeAt = new THREE.Vector3(home.x, 0, home.z) // donde esta normalmente
    const homeQuat = new THREE.Quaternion()
    const center = new THREE.Vector3()
    const p = new THREE.Vector3()
    const q = new THREE.Quaternion()
    const s = new THREE.Vector3()
    const offset = new THREE.Vector3()
    const prev = new THREE.Vector3()

    const build = () => {
        root = new THREE.Group()
        const scene = source.scene.clone(true)
        scene.traverse((o) => {
            if (!o.isMesh) return
            if (o.name === STAND_IN) {
                o.visible = false
                return
            }
            o.material = new THREE.MeshStandardMaterial({ color: cfg.colors[o.name] || '#cccccc', roughness: 0.7, metalness: 0, side: THREE.DoubleSide })
            o.castShadow = true
            o.receiveShadow = true
        })
        root.add(scene)
        root.scale.setScalar(scale)
        node = scene.getObjectByName(STAND_IN)
        mixer = new THREE.AnimationMixer(scene)
        actions = source.animations.map((clip) => {
            const action = mixer.clipAction(clip)
            action.setLoop(THREE.LoopOnce, 1)
            action.clampWhenFinished = true
            action.play()
            action.paused = true
            return action
        })
        mainScene.add(root)
    }

    /** Pone el accesorio en el tiempo t y deja en p, q (en el mundo) donde esta el centro de los pies del gato de muestra. */
    const sample = (t) => {
        actions.forEach((action) => (action.time = Math.min(t, action.getClip().duration)))
        mixer.update(0)
        root.updateMatrixWorld(true)
        node.matrixWorld.decompose(p, q, s)
        offset.set(0, FEET_Y, BODY_Z).multiply(s).applyQuaternion(q)
        p.add(offset)
    }

    demo.play = () => {
        if (!root) build()
        if (!demo.active) {
            restYaw = pet.rotation.y
            pet.rotation.order = 'YXZ'
        }
        // el accesorio se coloca para que el gato de muestra empiece justo donde empieza la mascota y el accesorio quede hacia +z (a la izquierda
        // de la pantalla, lejos de la tarjeta de texto)
        homeQuat.setFromAxisAngle(new THREE.Vector3(0, 1, 0), restYaw)
        root.position.set(0, 0, 0)
        root.rotation.y = 0
        sample(0)
        const start = p.clone()
        const box = new THREE.Box3()
        root.traverse((o) => o.isMesh && o.visible && box.expandByObject(o))
        box.getCenter(center)
        root.rotation.y = Math.atan2(0, 1) - Math.atan2(center.x - start.x, center.z - start.z) // (el angulo hacia +z es 0)
        root.position.set(0, 0, 0)
        sample(0)
        root.position.set(rest.x - p.x, RUG_Y, rest.z - p.z)
        demo.active = true
        demo.done = false
        demo.time = 0
        prev.copy(rest)
        a.faceTo = null
        a.ty = null
        if (a.contact) a.contact.visible = false // la sombra de contacto es plana: se quita mientras la mascota se acuesta o gira
    }

    demo.update = (dt) => {
        if (!demo.active || !root) return
        demo.time += dt * cfg.speed // (tiempo de la animacion del modelo)
        sample(demo.time)
        // la mascota ocupa el lugar del gato de muestra
        a.base.set(p.x, p.y, p.z)
        pet.quaternion.copy(q)
        if (demo.time < 0.35) pet.quaternion.slerpQuaternions(homeQuat, q, demo.time / 0.35) // gira poco a poco hacia donde mira el gato de muestra
        // camina mientras se desplaza
        const speed = prev.distanceTo(p) / Math.max(dt, 1e-4)
        prev.copy(p)
        a.walking = speed > 0.12 && p.y < 0.3
        if (demo.time >= cfg.duration && !demo.done) {
            demo.done = true
            a.walking = false
        }
    }

    /** Quita el accesorio; con restore = true la mascota vuelve a su lugar (al pasar a otra nota). */
    demo.dispose = (restore = false) => {
        if (root) {
            root.removeFromParent()
            root.traverse((o) => o.isMesh && o.material.dispose())
            root = null
            mixer = null
            actions = []
        }
        if (!demo.active) return
        demo.active = false
        a.walking = false
        pet.rotation.order = 'XYZ'
        pet.rotation.set(0, restYaw, 0)
        if (a.contact) a.contact.visible = true
        if (restore) {
            a.base.set(homeAt.x, 0, homeAt.z)
            a.faceTo = restYaw
        }
    }
    return demo
}
