/**
 * AYUDANTES para construir modelos 3D: materiales con cache, elipsoides, cilindros,
 * cajas redondeadas y puntos de anclaje para los hotspots.
 */
import * as THREE from 'three'

const materialCache = {}
export function getMaterial(color, opts) {
    let a = color + (opts ? JSON.stringify(opts) : '')
    return (
        materialCache[a] ||
        (materialCache[a] = new THREE.MeshStandardMaterial(
            Object.assign(
                {
                    color: color,
                    roughness: 0.78,
                    metalness: 0,
                },
                opts || {},
            ),
        ))
    )
}
/**
 * Convierte a MeshStandardMaterial cualquier material que no lo sea (Basic, Lambert, Phong, Toon: p. ej. un .glb exportado
 * como "unlit"), conservando color, textura, transparencia y lado: asi todos los objetos reaccionan a las luces.
 */
export function toStandard(material) {
    if (!material || material.isMeshStandardMaterial || material.isMeshPhysicalMaterial) return material
    if (!(material.isMeshBasicMaterial || material.isMeshLambertMaterial || material.isMeshPhongMaterial || material.isMeshToonMaterial)) {
        return material
    }
    const standard = new THREE.MeshStandardMaterial({
        name: material.name,
        color: material.color,
        map: material.map,
        vertexColors: material.vertexColors,
        transparent: material.transparent,
        opacity: material.opacity,
        alphaTest: material.alphaTest,
        side: material.side,
        roughness: 0.8,
        metalness: 0,
    })
    material.dispose()
    return standard
}
/** Aplica toStandard a todos los materiales de un modelo cargado. */
export function standardizeMaterials(root) {
    root.traverse((o) => {
        if (!o.isMesh || !o.material) return
        o.material = Array.isArray(o.material) ? o.material.map(toStandard) : toStandard(o.material)
    })
}
export function mesh(geometry, material, opts) {
    let o = new THREE.Mesh(geometry, material && material.isMaterial ? material : getMaterial(material, opts))
    o.castShadow = true
    o.receiveShadow = true
    return o
}
export function ellipsoid(radius, material, sx, sy, sz, opts) {
    let i = mesh(new THREE.SphereGeometry(radius, 20, 14), material, opts)
    i.scale.set(sx || 1, sy || 1, sz || 1)
    return i
}
export function cylinder(rTop, rBottom, height, material, segments) {
    return mesh(new THREE.CylinderGeometry(rTop, rBottom, height, segments || 16), material)
}
export function place(obj, x, y, z) {
    obj.position.set(x, y, z)
    return obj
}
export function roundedBox(width, height, depth, radius, material, opts) {
    let i = Math.max(0.004, Math.min(radius, width * 0.45, height * 0.45, depth * 0.45)),
        n = width - 2 * i,
        d = height - 2 * i,
        u = Math.min(n, d) * 0.18,
        h = -n / 2,
        p = -d / 2,
        E = new THREE.Shape()
    E.moveTo(h + u, p)
    E.lineTo(h + n - u, p)
    E.quadraticCurveTo(h + n, p, h + n, p + u)
    E.lineTo(h + n, p + d - u)
    E.quadraticCurveTo(h + n, p + d, h + n - u, p + d)
    E.lineTo(h + u, p + d)
    E.quadraticCurveTo(h, p + d, h, p + d - u)
    E.lineTo(h, p + u)
    E.quadraticCurveTo(h, p, h + u, p)
    let L = Math.max(0.002, depth - 2 * i),
        q = new THREE.ExtrudeGeometry(E, {
            depth: L,
            bevelEnabled: true,
            bevelThickness: i,
            bevelSize: i,
            bevelSegments: 3,
            curveSegments: 5,
        })
    q.translate(0, 0, -L / 2)
    return mesh(q, material, opts)
}
export function anchor(parent, x, y, z) {
    let s = new THREE.Object3D()
    s.position.set(x, y, z)
    parent.add(s)
    return s
}
