/**
 * ONDAS DE LUZ: circulos que se abren y se apagan, como una gota en el agua (el mismo efecto con que aparecen Cacao y Nube en el inicio).
 * Sirven para indicar un lugar: debajo del kit, debajo de las mascotas y en los lugares que hay que revisar en las misiones.
 */
import * as THREE from 'three'
import { mainScene } from '../three/renderer.js'

const LIFE = 1.6 // segundos que tarda cada onda en abrirse y apagarse
const GEOMETRY = new THREE.RingGeometry(0.5, 0.6, 56)
const group = new THREE.Group()
mainScene.add(group)
const spots = new Set()
const waves = []

/**
 * Pone ondas que salen sin parar de un punto del piso.
 * size: tamano final de la onda (1 = mas o menos un metro de ancho); strength: que tan fuerte se ve (0 a 1);
 * every: segundos entre una onda y la siguiente; double: sale una segunda onda pequena justo detras de la primera, como una gota;
 * glow: false para que la onda conserve su color en vez de sumar luz.
 * Devuelve un objeto con remove() para quitarlas.
 */
export function addRipple({ x, y = 0.03, z, color = '#ffd27a', size = 1, strength = 0.9, every = 1.5, double = true, glow = true }) {
    const spot = { x, y, z, color, size, strength, every, double, glow, wait: 0, remove: () => spots.delete(spot) }
    spots.add(spot)
    return spot
}
export function clearRipples() {
    spots.clear()
    waves.splice(0).forEach(dispose)
}
function dispose(wave) {
    wave.ring.removeFromParent()
    wave.ring.material.dispose()
}
function spawn(spot, delay = 0) {
    const ring = new THREE.Mesh(
        GEOMETRY,
        new THREE.MeshBasicMaterial({
            color: spot.color,
            transparent: true,
            opacity: 0,
            blending: spot.glow ? THREE.AdditiveBlending : THREE.NormalBlending, // glow: suma luz (se ve blanca sobre fondos claros); sin glow, conserva su color
            side: THREE.DoubleSide,
            depthWrite: false,
            fog: false,
        }),
    )
    ring.rotation.x = -Math.PI / 2
    ring.position.set(spot.x, spot.y, spot.z)
    ring.visible = false
    group.add(ring)
    waves.push({ ring, spot, age: -delay })
}
export function updateRipples(dt) {
    spots.forEach((spot) => {
        spot.wait -= dt
        if (spot.wait > 0) return
        spot.wait = spot.every
        spawn(spot)
        if (spot.double) spawn(spot, 0.28)
    })
    for (let i = waves.length - 1; i >= 0; i--) {
        const wave = waves[i]
        wave.age += dt
        if (wave.age < 0) continue // (la segunda onda espera un momento)
        const k = wave.age / LIFE
        if (k >= 1 || !spots.has(wave.spot)) {
            dispose(wave)
            waves.splice(i, 1)
            continue
        }
        wave.ring.visible = true
        wave.ring.scale.setScalar(wave.spot.size * 0.3 * (1 + k * 3))
        wave.ring.material.opacity = wave.spot.strength * (1 - k) ** 2
    }
}
