/**
 * PASOS de la etapa DURANTE: aviso, hub de tres experiencias, misiones con tiempo
 * y sus pantallas de cierre.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { MISSION_SECONDS, QUAKE } from '../config.js'
import { session, state } from '../core/state.js'
import { qs, qsa } from '../core/utils.js'
import { content } from '../data/content.js'
import { goTo, steps, transitionTo } from './navigation.js'
import { resetCameraEffects, setCameraMode, setOrbit, setTpZoom } from '../systems/camera.js'
import { catChase } from '../systems/catChase.js'
import { setBeacon, setInteract } from '../systems/interaction.js'
import { player, resetPlayer } from '../systems/player.js'
import { calmNerves, nervousLife } from '../systems/nerves.js'
import { quake, startQuake } from '../systems/quake.js'
import { dropBooks, resetBooks } from '../systems/quakeEffects.js'
import { cat, catHideSpots, dog, fearBubbles, person, placePet, setPetMood } from '../three/characters.js'
import { mainScene } from '../three/renderer.js'
import { LAYOUT, armFalls, openWardrobe, resetFalls, setCeilingSpotOff } from '../three/thirdRoom.js'
import { addRipple, clearRipples } from '../systems/ripples.js'
import { addHotspot } from '../ui/hotspots.js'
import { hideMoveHint, placeMoveHint, setObjective, showMoveHint, showTimer, updateTimer } from '../ui/hud.js'
import { showDynamic, showPanel } from '../ui/panels.js'

// Lugares donde puede estar escondido Cacao en la primera experiencia (ver LAYOUT en thirdRoom.js): al lado de la cama,
// junto al escritorio y frente al armario. dog = donde se ve a Cacao al encontrarlo
const SEARCH_SPOTS = LAYOUT.dogSpots
let lastHidden = null // el lugar donde estuvo escondido Cacao la ultima vez
const PET_BED = { dog: LAYOUT.bed.dog, cat: LAYOUT.bed.cat } // las mascotas sobre la cama
const START = LAYOUT.start
const MARK_COLOR = '#ffb23d' // amarillo naranja de las ondas que marcan un lugar en las misiones
const PLAY_SHAKE = 0.4 // cuanto tiembla la camara mientras se juega (1 = todo el temblor): suave, para poder ver y mover al personaje

/**
 * Resultado de una experiencia sin cortes: la camara se acerca a la mascota en la misma casa,
 * se ve donde esta y, un momento despues, aparece la tarjeta con la explicacion.
 * instant = ya con la camara cerca (al llegar con "Siguiente" desde otro paso).
 */
// Desde donde se ve a la mascota al encontrarla: hacia donde mira (la camara queda delante de ella)
const REVEAL_YAW = { hide: Math.PI / 2, still: 0, cat: Math.PI / 2 }
// Desde donde se ve a la gata segun donde termino (0 armario, 1 sobre la cama, 2 debajo del escritorio; ver catSpots en thirdRoom.js)
const CAT_REVEAL = [{}, { cam: -Math.PI / 2 }, { cam: Math.PI, view: { look: 0.2, up: 0.05, dist: 1.6 } }]
function revealPet(k, instant, camYaw, face, view) {
    const text = content.mission[k]
    session.done.add(k)
    player.locked = true
    person.visible = false
    state.hideBanner = true
    qs('#hotspots').style.visibility = 'hidden'
    setObjective(null)
    setBeacon(null)
    clearRipples()
    setInteract(null)
    showTimer(false)
    fearBubbles.forEach((b) => (b.visible = false))
    const pet = k === 'cat' ? cat : dog
    calmNerves(pet) // (la tarjeta de resultado se lee con calma: sin jadeo ni miradas nerviosas)
    state.hideAlarm = true // al encontrarla ya no hay "ALERTA SISMICA" ni tiempo ni ayuda de movimiento
    hideMoveHint()
    pet.visible = true
    const spot = pet.userData.base
    // la camara se pone de frente a la mascota (que mira hacia ella) y el temblor baja para poder verla bien
    const yaw = camYaw != null ? camYaw : REVEAL_YAW[k]
    // la mascota mira a la camara; solo el perro dentro del armario se queda de lado (face). Nube se ve de frente
    const turn = face != null ? face : yaw
    pet.userData.faceTo = turn
    if (instant) pet.rotation.y = turn
    // view: camara mas baja y cerca (para ver a la mascota debajo del escritorio)
    // en pantalla ancha la tarjeta queda a la izquierda: la camara se corre y la mascota se ve un poco a la derecha, sin que la tape
    const shift = innerWidth > innerHeight ? 0.26 : 0
    setTpZoom(new THREE.Vector3(spot.x, spot.y + (view ? view.look : 0.45), spot.z), instant, yaw, view ? view.dist : 2.3, view ? view.up : 0.5, shift)
    quake.shakeTarget = 0 // hay que leer la tarjeta: sin temblor
    // cuando Cacao se queda quieto, el foco del techo (el de las sombras) se apaga mientras se le ve de cerca y se enciende al salir
    if (k === 'still') setCeilingSpotOff(true)
    const leave = state.curExit
    state.curExit = () => {
        if (leave) leave()
        quake.shakeTarget = 1
        setCeilingSpotOff(false)
    }
    if (k === 'hide') {
        setPetMood(dog, { wag: 0, shiver: 0.9, eyes: 1.35 })
        audio.whimper()
    } else if (k === 'still') {
        setPetMood(dog, { wag: 0, shiver: 0.4, eyes: 1.4 })
        audio.whimper()
    } else {
        setPetMood(cat, { wag: 0.4, shiver: 0.3, eyes: 1.4 })
        audio.meow()
    }
    setTimeout(
        () => {
            if (!state.stepData.reveal) return
            showPanel({
                title: text.title,
                text: text.text,
                html: text.tips ? '<ul class="tips">' + text.tips.map((tip) => '<li>' + tip + '</li>').join('') + '</ul>' : '',
                cls: 'reveal',
                actions: [{ label: 'Regresar', fn: () => transitionTo('hub', null, 900) }],
            })
        },
        instant ? 300 : 1900,
    )
    state.stepData.reveal = true
}

steps.quakeIntro = {
    stage: 2,
    w: 0.04,
    prev: 'antesEnd',
    next: 'hub',
    enter() {
        setCameraMode('orbit')
        setOrbit({
            r: 10.5,
            h: 6.6,
        })
        resetBooks()
        resetPlayer(START.x, START.z, 0)
        // la habitacion de fondo se ve sin las mascotas (la tarjeta del temblor es lo que importa)
        dog.visible = cat.visible = false
        state.curExit = () => (dog.visible = cat.visible = true)
        session.done.clear()
        // Empieza a temblar el fondo (la casa), pero la tarjeta de texto se queda quieta y aparece con fundido
        audio.init()
        startQuake()
        quake.shakeTarget = 0 // la tarjeta se lee con calma: sin temblor (tiembla de nuevo al jugar)
        state.bgOverride = 'night' // el fondo detras de la habitacion se oscurece casi a negro azulado
        const intro = content.quakeIntro
        const words = intro.text
            .split(' ')
            .map((w, i) => '<span style="--i:' + i + '">' + w + '</span>')
            .join(' ')
        const panel = showPanel({
            cls: 'center quakecard',
            html:
                '<svg class="qline" viewBox="0 0 400 40" preserveAspectRatio="none" aria-hidden="true"><path pathLength="1" d="M0 20H120l8-4 8 8 8-16 8 28 8-34 8 30 8-22 8 14 8-6 8 4H400"/></svg>' +
                '<span class="qkick">' +
                intro.kick +
                '</span><h2 class="qtitle">' +
                intro.title +
                '</h2><p class="qtext">' +
                words +
                '</p>',
            actions: [
                {
                    label: intro.cta,
                    cls: 'danger',
                    fn: () => {
                        // la tarjeta se desvanece mientras la escena se funde; luego aparecen las experiencias despacio
                        panel.classList.add('leaving')
                        transitionTo('hub', null, 1100)
                    },
                },
            ],
        })
    },
}
/** Camara de las tres experiencias: PC, celular vertical y tablet. (En el celular la habitacion queda entre la barra y las tarjetas.) */
const hubOrbit = () => {
    const phone = innerWidth / innerHeight < 0.6
    const wide = innerWidth / innerHeight > 1.3 // pantalla horizontal: la habitacion se ve mas grande (las tarjetas de abajo son mas chicas)
    return {
        r: phone ? 25.5 : wide ? 12.4 : 14.9,
        h: phone ? 15.3 : wide ? 7.63 : 9.17,
        sx: 0,
        sy: phone ? 2 : wide ? 0.9 : 1.1,
        amp: 0, // sin vaiven: antes la habitacion se movia y cambiaba de tamano
    }
}
steps.hub = {
    stage: 2,
    w: 0.3,
    prev: 'quakeIntro',
    next: 'sizeIntro',
    enter() {
        setCameraMode('orbit')
        // La habitacion siempre se ve igual (mismo lugar y tamano), lo mas grande que deja el espacio entre la barra de arriba y las tarjetas
        resetCameraEffects()
        setOrbit(hubOrbit())
        state.bgOverride = 'night' // el fondo se oscurece (como en la tarjeta del temblor)
        quake.shakeTarget = 0 // en esta pantalla hay que leer: sin temblor (tiembla de nuevo al empezar cada experiencia)
        quake.target = QUAKE.intensity
        let hubText = content.hub
        placePet(dog, PET_BED.dog.x, PET_BED.dog.y, PET_BED.dog.z, 0.1, 0.62)
        setPetMood(dog, {
            wag: 0,
            shiver: 0.6,
            eyes: 1.25,
        })
        // Solo en esta pantalla la habitacion se ve sin las mascotas; al salir vuelven a estar disponibles
        dog.visible = false
        cat.visible = false
        state.curExit = () => {
            dog.visible = true
            cat.visible = true
        }
        placePet(cat, PET_BED.cat.x, PET_BED.cat.y, PET_BED.cat.z, -0.1, 0.6)
        setPetMood(cat, {
            wag: 0,
            shiver: 0.6,
            eyes: 1.25,
        })
        if (!quake.active) {
            startQuake()
            quake.shakeTarget = 0 // (startQuake lo deja en 1)
        }
        let t = showDynamic(
            '<div id="hub" class="active"><div class="wrap"><div class="hhead card"><h2>' +
                hubText.title +
                '</h2><p class="sub">' +
                hubText.sub +
                '</p><p class="limit">' +
                hubText.limit.replace('{n}', MISSION_SECONDS) +
                '</p></div><div class="cards">' +
                hubText.cards
                    .map(
                        (a, i) =>
                            '<div class="exp card" style="--d:' +
                            (0.75 + i * 0.35).toFixed(2) +
                            's">' +
                            '<img class="pet" src="' +
                            import.meta.env.BASE_URL +
                            (a.pet === 'cat' ? 'icono-gato.png' : 'icono-perro.png') +
                            '" alt="" draggable="false">' +
                            '<div class="txt"><h3>' +
                            a.t +
                            '</h3><p>' +
                            a.d +
                            '</p></div><button class="btn" data-k="' +
                            a.k +
                            '">' +
                            hubText.cta +
                            '</button>' +
                            (session.done.has(a.k) ? '<span class="badge">' + hubText.done + '</span>' : '') +
                            '</div>',
                    )
                    .join('') +
                '</div><div class="foot" style="--d:1.8s"><button class="btn" id="hubNext" ' +
                (session.done.size < 3 ? 'hidden' : '') +
                '>' +
                hubText.next +
                '</button></div></div></div>',
        )
        qsa('.exp .btn', t).forEach((a) =>
            a.addEventListener('click', () => {
                audio.blip()
                // la escena se desvanece y aparece la habitacion, sin corte
                transitionTo('mission', { k: a.dataset.k }, 1000)
            }),
        )
        qs('#hubNext', t).addEventListener('click', () => {
            audio.blip()
            goTo('sizeIntro')
        })
    },
}
steps.mission = {
    stage: 2,
    w: 0.5,
    prev: 'hub',
    next: (p) => 'close_' + p.k, // salta al resultado de esta experiencia
    enter(e) {
        let t = e.k,
            a = content.mission[t],
            o = MISSION_SECONDS
        setCameraMode('tp')
        resetCameraEffects()
        resetPlayer(START.x, START.z, 0)
        person.scale.y = 1
        resetFalls() // (la taza de la mesa y un cuadro se caen mientras dura la mision: armFalls() al empezar a jugar)
        // Antes de jugar hay una pantalla explicativa en el centro: no se puede jugar ni corre el tiempo hasta pulsar Empezar
        // (al reintentar tras perder se empieza directo). El aviso de arriba a la izquierda ya no se muestra.
        const intro = !e.retry
        let started = !intro
        if (started) armFalls()
        const onBegin = []
        const whenStarted = (fn) => (started ? fn() : onBegin.push(fn))
        state.hideBanner = true
        if (intro) {
            player.locked = true
            quake.shakeTarget = 0 // mientras se explica no tiembla (ni la camara, ni la casa, ni las luces)
        } else {
            showMoveHint()
            quake.shakeTarget = PLAY_SHAKE
        }
        qs('#stick').hidden = true // en las misiones se camina con clic en el piso (systems/clickMove.js), sin joystick
        if (e.retry) {
            resetBooks()
            dropBooks(6)
        }
        let s = 0,
            r = false,
            i = o,
            lastSecond = o,
            n = false,
            d = null,
            u = (dogAt) => {
                n = true
                if (dogAt) {
                    // Cacao aparece en el lugar donde estaba escondido, acostado (patas dobladas): asi cabe debajo de la cama o del escritorio
                    // sin verse aplastado (antes se le achataba el cuerpo)
                    placePet(dog, dogAt.x, dogAt.y || 0, dogAt.z, dogAt.ry, dogAt.size || 0.62)
                    dog.userData.lie = dogAt.wardrobe ? 0 : 1 // (en el armario se queda de pie: acostado se veia raro)
                    if (dogAt.wardrobe) openWardrobe(true) // estaba dentro del armario
                }
                // la camara se pone segun donde quedo la mascota (la gata puede terminar en el armario, sobre la cama o debajo del escritorio)
                const view = dogAt || (t === 'cat' ? CAT_REVEAL[catChase.final] : null)
                revealPet(t, false, view && view.cam, dogAt && dogAt.wardrobe ? dogAt.ry : undefined, view && view.view)
            },
            h = () => {
                n = true
                player.locked = true
                quake.shakeTarget = 0 // la tarjeta de "no pudiste salir" se lee sin temblor
                setInteract(null)
                setBeacon(null)
                setObjective(null)
                showTimer(false)
                audio.no()
                audio.whimper()
                // todo se funde a negro despacio y solo queda la tarjeta, que aparece con un desvanecimiento lento
                qs('#blackout').classList.add('on')
                let p = content.mission.fail
                showPanel({
                    title: p.t,
                    text: p.s,
                    cls: 'center fail',
                    actions: [
                        {
                            label: p.cta,
                            fn: () => {
                                // todo se va a negro del todo y entonces empieza de nuevo la experiencia
                                qs('#panel').classList.add('leaving')
                                qs('#blackout').classList.add('full')
                                setTimeout(
                                    () =>
                                        state.cur === 'mission' &&
                                        goTo('mission', {
                                            k: t,
                                            retry: true,
                                        }),
                                    1000,
                                )
                            },
                        },
                    ],
                })
            }
        if (!intro) {
            showTimer(true)
            updateTimer(i, o)
        }
        if (t === 'hide') {
            // Cacao esta escondido en uno de tres lugares marcados en la casa; hay que ir a revisarlos
            cat.visible = false
            dog.visible = false
            // cada vez se marcan 3 lugares de los cinco que hay (siempre el armario y dos al azar), y Cacao nunca se esconde dos veces seguidas en el mismo
            const wardrobeSpot = SEARCH_SPOTS.find((s) => s.dog.wardrobe)
            const others = SEARCH_SPOTS.filter((s) => s !== wardrobeSpot).sort(() => Math.random() - 0.5)
            const chosen = [wardrobeSpot, others[0], others[1]].sort(() => Math.random() - 0.5) // el armario siempre es uno de los tres
            const options = chosen.filter((spot) => spot !== lastHidden)
            const hidingSpot = options[Math.floor(Math.random() * options.length)]
            lastHidden = hidingSpot
            const hidingIn = chosen.indexOf(hidingSpot)
            const markers = chosen.map((spot, k) => {
                const marker = new THREE.Group()
                const ring = new THREE.Mesh(
                    new THREE.RingGeometry(0.62, 0.78, 40),
                    new THREE.MeshStandardMaterial({
                        color: '#ffe0a0', // amarillo suave (antes #ffc24d, muy intenso)
                        emissive: '#ffe0a0',
                        emissiveIntensity: 0.3,
                        roughness: 0.6,
                        transparent: true,
                        opacity: 0.85,
                        side: THREE.DoubleSide,
                    }),
                )
                ring.rotation.x = -Math.PI / 2
                ring.position.y = 0.04
                marker.add(ring) // (sin la flecha que flotaba arriba: el lugar se marca con el aro y las ondas)
                marker.scale.setScalar(0.6) // el cuarto es chico
                marker.position.set(spot.x, 0, spot.z)
                mainScene.add(marker)
                // ondas de luz suaves, amarillo naranja como el aro, que marcan los lugares que hay que revisar
                const ripple = addRipple({ x: spot.x, y: 0.05, z: spot.z, color: MARK_COLOR, size: 0.85, strength: 0.8, every: 1.8, glow: false })
                return { marker, ring, ripple, label: null, spot, k, checked: false }
            })
            state.curExit = () => markers.forEach((m) => mainScene.remove(m.marker))
            const refreshTargets = () =>
                setInteract(
                    markers
                        .filter((m) => !m.checked)
                        .map((m) => ({
                            x: m.spot.x,
                            z: m.spot.z,
                            r: m.spot.r,
                            label: a.open,
                            fn: () => {
                                if (m.k === hidingIn) {
                                    markers.forEach((other) => (other.marker.visible = false))
                                    return u(m.spot.dog)
                                }
                                // lugar vacio: se marca como revisado y se avisa
                                m.checked = true
                                m.ripple.remove() // un lugar ya revisado deja de brillar
                                m.ring.material.color.set('#9aa8c4')
                                // una marca pequena queda sobre el lugar ya revisado
                                m.label = addHotspot({ cls: 'pill', label: '✓ Vacío', anchor: m.ring })
                                m.label.classList.add('search', 'checked', 'small')
                                audio.no()
                                setObjective(a.empty.t, a.empty.s)
                                setTimeout(() => state.cur === 'mission' && setObjective(null), 2200)
                                refreshTargets()
                            },
                        })),
                )
            whenStarted(refreshTargets)
            d = (p) => {
                s += p
                if (s > 4 && !r) {
                    r = true
                    audio.whimper()
                }
                // Cacao, escondido, ladra bajito de vez en cuando (se oye, pero no se ve): una pista de que esta cerca
                nervousLife(dog, p, { base: 0.5, volume: 0.45, every: [5, 8] })
                markers.forEach((m) => {
                    m.ring.scale.setScalar(m.checked ? 1 : 1 + Math.sin(state.time * 3 + m.k) * 0.12)
                })
            }
        } else if (t === 'still') {
            cat.visible = false
            dog.visible = true
            placePet(dog, PET_BED.dog.x, PET_BED.dog.y, PET_BED.dog.z, 0.1, 0.62)
            setPetMood(dog, {
                wag: 0,
                shiver: 0.35,
                eyes: 1.35,
            })
            // ondas de luz debajo de Cacao, que esta sobre la cama (en vez de una flecha)
            addRipple({ x: PET_BED.dog.x, y: PET_BED.dog.y + 0.04, z: PET_BED.dog.z, color: MARK_COLOR, size: 0.85, strength: 0.8, every: 1.8, glow: false })
            // temblando, mirando a todos lados (y a ti si te acercas), jadeando, con saltitos de susto y ladrando bajito
            d = (p) => nervousLife(dog, p, { base: 0.55, volume: 0.6, every: [4, 7], watch: player.pos, startle: [7, 12] })
            whenStarted(() =>
                setInteract({
                    x: PET_BED.dog.x,
                    z: PET_BED.dog.z,
                    r: 2.2,
                    label: a.open,
                    fn: u,
                }),
            )
        } else {
            dog.visible = false
            cat.visible = true
            catChase.reset()
            setPetMood(cat, {
                wag: 1,
                shiver: 0.5,
                eyes: 1.4,
            })
            d = (p) => {
                catChase.update(p)
                // nerviosa: tiembla, mira a los lados, mueve la cola a tirones y maulla bajito (corriendo no hace falta)
                if (!catChase.dash) nervousLife(cat, p, { base: catChase.cornered ? 0.85 : 0.65, volume: 0.55, every: [3.5, 6.5], watch: player.pos, startle: catChase.spot === 2 ? null : [6, 10] }) // (debajo del escritorio no hay lugar para saltar)
                if (catChase.cornered && !catChase.dash) {
                    setInteract({
                        x: cat.userData.base.x,
                        z: cat.userData.base.z,
                        r: 2.3,
                        label: a.open,
                        fn: u,
                    })
                } else {
                    setInteract(null)
                }
            }
        }
        state.curTick = (p) => {
            placeMoveHint() // (la ayuda de movimiento va justo debajo de la habitacion)
            if (!started) return // pantalla explicativa: nada avanza todavia
            if (!n) {
                if (d) {
                    d(p)
                }
                if (!n) {
                    i -= p
                    updateTimer(i, o)
                    // en los ultimos 5 segundos suena un tic muy leve cada segundo
                    const whole = Math.ceil(i)
                    if (whole !== lastSecond && whole >= 1 && whole <= 5) audio.tick()
                    lastSecond = whole
                    if (i <= 0) {
                        h()
                    }
                }
            }
        }
        if (intro) {
            const banner = content.banner.strong
            // se adelanta la ayuda de movimiento: ya se ve (resaltada) debajo de la tarjeta de "Empezar", para que se sepa
            // como moverse antes de arrancar; al empezar se queda igual, abajo, pero con su estilo de siempre (sin resaltar)
            showMoveHint()
            qs('#moveHint').classList.add('intro')
            const begin = () => {
                started = true
                armFalls()
                player.locked = false
                quake.shakeTarget = PLAY_SHAKE // al empezar vuelve a temblar (con suavidad)
                qs('#panel').hidden = true
                showTimer(true)
                updateTimer(i, o)
                showMoveHint()
                qs('#moveHint').classList.remove('intro')
                onBegin.forEach((fn) => fn())
            }
            // poco texto: el titulo, una frase corta de que hacer y el tiempo
            showPanel({
                cls: 'center missionintro',
                title: banner.t,
                text: a.obj.s,
                html: '<p class="blimit">' + content.banner.pick.limit.replace('{n}', MISSION_SECONDS) + '</p>',
                actions: [{ label: 'Empezar', fn: begin }],
            })
        }
    },
}
;['hide', 'still', 'cat'].forEach((e) => {
    steps['close_' + e] = {
        stage: 2,
        w: 0.6,
        prev: 'hub',
        next: () => (session.done.size >= 3 ? 'sizeIntro' : 'hub'),
        // Llegar aqui con "Siguiente" muestra el mismo resultado, ya con la camara cerca de la mascota
        enter() {
            setCameraMode('tp')
            resetPlayer(START.x, START.z, 0)
            if (e === 'hide') {
                const spot = SEARCH_SPOTS[0].dog
                cat.visible = false
                placePet(dog, spot.x, 0, spot.z, spot.ry, 0.62)
                dog.userData.lie = 1 // acostado
            } else if (e === 'still') {
                cat.visible = false
                placePet(dog, PET_BED.dog.x, PET_BED.dog.y, PET_BED.dog.z, 0.1, 0.62)
            } else {
                dog.visible = false
                const spot = catHideSpots[0]
                placePet(cat, spot[0], spot[1], spot[2], 0, 0.6)
                openWardrobe(true, true) // Nube esta dentro del armario
            }
            revealPet(e, true, e === 'hide' ? SEARCH_SPOTS[0].dog.cam : undefined)
        },
    }
})
