/**
 * PASOS de CIERRE: final y pagina Acerca de.
 */
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { icon } from '../data/icons.js'
import { goTo, playRestartWipe, steps } from './navigation.js'
import { setCameraMode, showCam, showRoom } from '../systems/camera.js'
import { setPetMood } from '../three/characters.js'
import { showrooms } from '../three/showrooms.js'
import { showDynamic } from '../ui/panels.js'

steps.close = {
    stage: 4,
    w: 0.6,
    prev: 'quiz',
    next: 'about',
    enter() {
        setCameraMode('show')
        showRoom('fin')
        state.bgOverride = 'dawn'
        const phone = innerWidth / innerHeight < 0.6 // celular vertical: las mascotas mas lejos y abajo, para que el texto no las tape
        showCam.d = phone ? 21 : 15
        showCam.rate = 1.1
        showCam.offY = phone ? -0.3 : -0.16 // con el texto corto queda espacio: la camara baja y las mascotas se ven completas
        let closeText = content.close,
            finRoom = showrooms.fin
        setPetMood(finRoom.dog, {})
        setPetMood(finRoom.cat, {})
        let o = showDynamic(
            '<div class="fin"><span class="kick">' +
                closeText.kicker +
                '</span><div class="words">' +
                closeText.words.map((u) => '<span class="w">' + u + '</span>').join('') +
                '</div><p class="line">' +
                closeText.text +
                '</p><button class="btn big cta" id="finBtn">' +
                closeText.cta +
                '</button></div>',
        )
        qs('#finBtn', o).addEventListener('click', () => {
            audio.blip()
            goTo('about')
        })
        let s = qs('#flash')
        s.classList.remove('on')
        s.offsetWidth
        s.classList.add('on')
        audio.swell()
        let r = 0,
            i = 0,
            n = 0,
            d = 0
        state.curTick = (u) => {
            r += u
            if (!i && r > 1.6) {
                i = 1
                finRoom.dog.userData.hop = 1
                audio.bark()
            }
            if (!n && r > 2.8) {
                n = 1
                finRoom.cat.userData.hop = 1
                audio.meow()
            }
            if (r > 6) {
                d += u
                if (d > 3) {
                    d = 0
                    ;(Math.random() < 0.5 ? finRoom.dog : finRoom.cat).userData.hop = 1
                }
            }
        }
    },
}
steps.about = {
    stage: 4,
    w: 0.9,
    prev: 'close',
    enter() {
        setCameraMode('show')
        showRoom('fin')
        state.bgOverride = 'dawn'
        showCam.offY = -0.13 // la camara baja: las mascotas se ven completas debajo del cuadro, sin cortarse abajo
        let aboutText = content.about,
            t = showDynamic(
                '<div class="about dawn card"><div class="logo-c">' +
                    icon('paw') +
                    '</div><h2>' +
                    aboutText.title +
                    '</h2><p>' +
                    aboutText.text +
                    '</p><button class="btn" id="restart">' +
                    aboutText.cta +
                    '</button></div>',
            )
        qs('#restart', t).addEventListener('click', (s) => {
            audio.blip()
            playRestartWipe(s.currentTarget)
        })
        let a = 0,
            o = 0
        state.curTick = (s) => {
            a += s
            o += s
            if (o > 3) {
                o = 0
                ;(Math.random() < 0.5 ? showrooms.fin.dog : showrooms.fin.cat).userData.hop = 1
            }
        }
    },
}
