/**
 * CIERRE DE LA ETAPA "ANTES": la camara sale de la cabeza del usuario, retrocede hasta una vista de tercera
 * persona y desde ahi el personaje camina hasta el sofa, se da la vuelta y se sienta en medio de Cacao y Nube.
 * Todo ocurre en la misma sala. Al final aparece el texto de cierre.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { session, state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { steps, transitionTo } from './navigation.js'
import { cineGo, cineSet, cineStart, cine, setCameraMode } from '../systems/camera.js'
import { cat, dog, person, placePet, setPetMood, walkPath } from '../three/characters.js'
import { setDoorOpen } from '../three/livingRoom.js'
import { showDynamic } from '../ui/panels.js'
import {
    CAT_SCALE,
    CAT_X,
    DOG_SCALE,
    DOG_X,
    SEAT_X,
    SEAT_Z,
    SOFA_FRONT,
    PET_Z,
    SOFA_Z,
    PERSON_SCALE,
    resetPerson,
    rigSeat,
    seatY,
    seatedY,
    sitPose,
} from './sofaScene.js'

const WALK_SPEED = 1.5 // m/s
const PULL_TIME = 2.2 // segundos que tarda la camara en salir de la cabeza y retroceder
const WALK_AT = 1.2 // segundo en que el personaje empieza a caminar
const SIT_TIME = 1.4 // segundos que tarda en darse la vuelta y sentarse
// Vista final: de frente a los tres, desde la sala
// (mas cerca y desplazada: la escena queda a la derecha de la pantalla, libre del cuadro de texto de la izquierda)
export const END_CAM = { pos: new THREE.Vector3(2.76, 1.22, 1.1), look: new THREE.Vector3(2.02, 0.8, 2.34) }
// En celular y tablet (angosta o vertical) el cuadro de texto va abajo, no a la izquierda: la vista queda centrada, mas atras y mirando un poco
// mas abajo, para que los tres se vean enteros en la parte de arriba (delante del televisor, que esta en z -0.9 a -0.7)
const END_CAM_NARROW = { pos: new THREE.Vector3(1.5, 1.35, -0.4), look: new THREE.Vector3(1.5, 0.5, 2.3) }
const endCam = () => (innerWidth <= 900 || innerHeight > innerWidth ? END_CAM_NARROW : END_CAM)

const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}
const lerp = (a, b, k) => a + (b - a) * k

steps.antesEnd = {
    stage: 1,
    w: 0.95,
    prev: () => (session.trackFirst === 'cat' ? 'track' : 'trackCat'), // vuelve a lo ultimo que vio
    next: 'quakeIntro',
    enter() {
        setCameraMode('cine')
        cineStart() // arranca exactamente donde estaba la camara del usuario
        setDoorOpen(true, true)

        // El personaje siempre entra por el mismo lugar: el lado derecho de la sala (visto desde las mascotas), por el pasillo
        // libre entre la mesita y el sofa, y camina hacia el centro del sofa (sin cruzar la mesa ni pasar frente a las mascotas)
        const start = { x: 0.2, z: 1.5 }
        const dx = SOFA_FRONT.x - start.x
        const dz = SOFA_FRONT.z - start.z
        const dist = Math.hypot(dx, dz)
        const travelYaw = Math.atan2(dx, dz)
        const startYaw = travelYaw
        const walkTime = dist / WALK_SPEED
        const sitAt = WALK_AT + walkTime
        // camara de tercera persona: desde el lado de la sala donde esta el usuario, mirando al personaje y al sofa (el personaje
        // entra por el lado derecho de la pantalla); sigue su avance sin meterse en el televisor
        const chasePos = (p) => new THREE.Vector3(p.x * 0.4 + 0.9, 1.75, -0.7)
        const chaseLook = (p) => new THREE.Vector3(p.x, 1.0, p.z)

        const limbs = person.userData
        person.visible = false
        person.scale.setScalar(limbs.rig ? 1 : PERSON_SCALE) // el modelo con huesos ya mide 1.7 m
        person.userData.pack.visible = true
        person.position.set(start.x, 0, start.z)
        person.rotation.y = startYaw
        dog.visible = cat.visible = true
        setPetMood(dog, { wag: 1.6, eyes: 1.05 })
        setPetMood(cat, { wag: 1.4, eyes: 1.05 })
        // Cacao y Nube parten de sus lugares del rastreo y se juntan un poco para dejar sitio en medio
        placePet(dog, 1.15, seatY(), PET_Z, Math.PI, DOG_SCALE)
        placePet(cat, 1.85, seatY(), PET_Z, Math.PI, CAT_SCALE)
        state.curExit = () => {
            resetPerson()
            placePet(dog, 1.15, seatY(), PET_Z, Math.PI, DOG_SCALE)
            placePet(cat, 1.85, seatY(), PET_Z, Math.PI, CAT_SCALE)
        }

        const text = content.antesEnd
        const el = showDynamic(
            '<div class="closefx"><span class="kick">' +
                text.kick +
                '</span>' +
                '<h2>' +
                text.title +
                '</h2><p>' +
                text.text +
                '</p>' +
                '<button class="btn big cta">' +
                text.cta +
                '</button></div>',
        )
        qs('.cta', el).addEventListener('click', () => {
            audio.blip()
            transitionTo('quakeIntro')
        })

        const cam0 = cine.pos.clone()
        const look0 = cine.look.clone()
        const here = new THREE.Vector3()
        let time = 0
        let seated = false
        let scooted = false
        let hopTimer = 0

        state.curTick = (dt) => {
            time += dt

            // ---- personaje ----
            if (time < sitAt) {
                const w = ease((time - WALK_AT) / Math.max(walkTime, 0.01))
                here.set(lerp(start.x, SOFA_FRONT.x, w), 0, lerp(start.z, SOFA_FRONT.z, w))
                person.position.copy(here)
                // primero gira hacia donde va, y camina
                person.rotation.y = lerp(startYaw, startYaw + Math.atan2(Math.sin(travelYaw - startYaw), Math.cos(travelYaw - startYaw)), ease((time - 0.6) / 0.8))
                const walking = time > WALK_AT && time < sitAt
                limbs.walking = walking
                limbs.sit = 0
                const swing = walking ? Math.sin(time * 8) * 0.65 : 0
                limbs.legL.rotation.x = swing
                limbs.legR.rotation.x = -swing
                limbs.armL.rotation.x = -swing * 0.8
                limbs.armR.rotation.x = swing * 0.8
                person.visible = time > 0.3 // aparece cuando la camara ya salio de su cabeza
            } else {
                // se da la vuelta, retrocede hasta el asiento y se sienta con las piernas al frente
                const s = ease((time - sitAt) / SIT_TIME)
                const seat = seatedY()
                if (s > 0.2) person.userData.pack.visible = false // sin mochila: no atraviesa el respaldo
                // (con huesos los pies siguen en el piso y la cadera queda sobre el asiento: el cuerpo se mueve hacia atras solo,
                // por eso la raiz queda un poco adelante del asiento)
                const rigSit = limbs.rig ? rigSeat() : null
                person.position.set(
                    lerp(SOFA_FRONT.x, SEAT_X, s),
                    rigSit ? rigSit.y * ease((s - 0.4) / 0.6) : seat * ease((s - 0.4) / 0.6),
                    lerp(SOFA_FRONT.z, rigSit ? rigSit.z : SEAT_Z, s),
                )
                limbs.walking = false
                person.rotation.y = lerp(travelYaw, Math.PI, ease(s * 1.6))
                const bend = ease((s - 0.3) / 0.7)
                sitPose(bend) // muslos al frente sobre el asiento, pantorrillas colgando
                here.copy(person.position)
                if (!scooted && s > 0.3) {
                    scooted = true
                    walkPath(dog, [{ x: DOG_X, z: PET_Z, y: seatY(), ry: Math.PI }], 0.5)
                    walkPath(cat, [{ x: CAT_X, z: PET_Z, y: seatY(), ry: Math.PI }], 0.5)
                }
                // sentado en medio: las mascotas celebran
                if (!seated && s >= 1) {
                    seated = true
                    audio.ok()
                    setPetMood(dog, { wag: 2.8, eyes: 1.15 })
                    setPetMood(cat, { wag: 2.4, eyes: 1.15 })
                    dog.userData.hop = 1
                    audio.bark()
                    setTimeout(() => {
                        cat.userData.hop = 1
                        audio.meow()
                    }, 350)
                }
                if (seated) {
                    hopTimer += dt
                    if (hopTimer > 2.2) {
                        hopTimer = 0
                        ;(Math.random() < 0.5 ? dog : cat).userData.hop = 1
                        audio.blip()
                    }
                }
            }

            // ---- camara ----
            const eyes = here.clone()
            if (time < PULL_TIME) {
                // sale de la cabeza del usuario y retrocede hasta la vista de tercera persona
                const k = ease(time / PULL_TIME)
                cineSet(cam0.clone().lerp(chasePos(eyes), k), look0.clone().lerp(chaseLook(eyes), k))
            } else if (time < sitAt + SIT_TIME * 0.3) {
                cineGo(chasePos(eyes), chaseLook(eyes), 3.2) // lo sigue mientras camina
            } else {
                cineGo(endCam().pos, endCam().look, 1.1) // y se abre a una vista de frente de los tres
            }
        }
    },
}
