/**
 * MOVER CON EL MOUSE (o el dedo) en las misiones del sismo: se hace clic en un punto del piso y el personaje camina hasta
 * alli; si se hace clic en un circulo (o cerca de el), va directo a ese lugar. Reemplaza al teclado y al joystick.
 * player.js llama a steer() cada cuadro y recibe la direccion en que debe caminar.
 */
import * as THREE from 'three'
import { state } from '../core/state.js'
import { isTouch } from '../core/utils.js'
import { camera, canvas, mainScene } from '../three/renderer.js'
import { ROOM } from '../three/thirdRoom.js'

const SNAP_PX = isTouch ? 70 : 52 // a cuantos pixeles de un circulo cuenta como "clic en el circulo"
const SNAP_METERS = 0.8 // o a cuantos metros del centro, si se hizo clic en el piso
const ARRIVE = 0.12 // distancia a la que se considera que ya llego
const STUCK_SECONDS = 0.45 // si un mueble lo frena este tiempo, se queda donde esta (no empuja para siempre)

const ndc = new THREE.Vector2()
const ray = new THREE.Raycaster()
const floor = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0)
const hit = new THREE.Vector3()
const probe = new THREE.Vector3()

// Marca en el piso donde se hizo clic: un aro que se abre y se desvanece
const ripple = new THREE.Mesh(
    new THREE.RingGeometry(0.14, 0.2, 32),
    new THREE.MeshBasicMaterial({ color: '#ffffff', transparent: true, opacity: 0, depthWrite: false }),
)
ripple.rotation.x = -Math.PI / 2
ripple.position.y = 0.05
ripple.visible = false
mainScene.add(ripple)
let rippleAge = 1

export const clickMove = {
    goal: null, // { x, z }
    /** Solo se maneja con el mouse en las misiones (en los demas pasos el personaje no camina). */
    get active() {
        return state.cur === 'mission' && state.mode === 'tp'
    },
    /**
     * Direccion [x, z] (ya normalizada) en que debe caminar el personaje este cuadro, o null si esta quieto.
     * pos = su posicion; locked = no se puede mover (pantalla explicativa o tarjeta de resultado).
     */
    steer(pos, locked, dt) {
        if (rippleAge < 1) {
            rippleAge = Math.min(1, rippleAge + dt / 0.7)
            ripple.scale.setScalar(1 + rippleAge * 1.6)
            ripple.material.opacity = 0.85 * (1 - rippleAge)
            ripple.visible = rippleAge < 1
        }
        if (locked || !this.active) {
            this.goal = null
            return null
        }
        const goal = this.goal
        if (!goal) return null
        const dx = goal.x - pos.x
        const dz = goal.z - pos.z
        const dist = Math.hypot(dx, dz)
        if (dist < ARRIVE) {
            this.goal = null
            return null
        }
        // si casi no avanza (un mueble en el camino), se detiene
        if (goal.last) {
            const moved = Math.hypot(pos.x - goal.last.x, pos.z - goal.last.z)
            goal.slow = moved < 3 * dt * 0.2 ? goal.slow + dt : 0
            if (goal.slow > STUCK_SECONDS) {
                this.goal = null
                return null
            }
        }
        goal.last = { x: pos.x, z: pos.z }
        return [dx / dist, dz / dist]
    },
    stop() {
        this.goal = null
    },
}

/** Punto del piso (y = 0) bajo el puntero, o null si el puntero apunta por encima del horizonte. */
function floorPoint(clientX, clientY) {
    ndc.set((clientX / innerWidth) * 2 - 1, -(clientY / innerHeight) * 2 + 1)
    ray.setFromCamera(ndc, camera)
    return ray.ray.intersectPlane(floor, hit)
}

/** El circulo (lugar de interaccion) mas cercano al clic, o null. Se mira en pantalla (aro y flecha) y en el piso. */
function snapTarget(clientX, clientY, point) {
    if (!state.interact) return null
    const list = Array.isArray(state.interact) ? state.interact : [state.interact]
    let best = null
    let bestScore = Infinity
    for (const target of list) {
        let score = Infinity
        // en pantalla: el aro del piso y la flecha que flota encima
        for (const y of [0, 0.9]) {
            probe.set(target.x, y, target.z).project(camera)
            const px = (probe.x * 0.5 + 0.5) * innerWidth
            const py = (-probe.y * 0.5 + 0.5) * innerHeight
            const d = Math.hypot(px - clientX, py - clientY)
            if (d < SNAP_PX) score = Math.min(score, d / SNAP_PX)
        }
        // en el piso
        if (point) {
            const d = Math.hypot(point.x - target.x, point.z - target.z)
            if (d < SNAP_METERS) score = Math.min(score, d / SNAP_METERS)
        }
        if (score < bestScore) {
            best = target
            bestScore = score
        }
    }
    return best
}

canvas.addEventListener('pointerdown', (event) => {
    if (!clickMove.active || (event.pointerType === 'mouse' && event.button !== 0)) return
    const point = floorPoint(event.clientX, event.clientY)
    const target = snapTarget(event.clientX, event.clientY, point)
    let x
    let z
    if (target) {
        x = target.x
        z = target.z
    } else if (point) {
        x = Math.min(ROOM.x1 - 0.4, Math.max(ROOM.x0 + 0.4, point.x))
        z = Math.min(ROOM.z1 - 0.4, Math.max(ROOM.z0 + 0.4, point.z))
    } else {
        return
    }
    clickMove.goal = { x, z, last: null, slow: 0 }
    ripple.position.set(x, 0.05, z)
    rippleAge = 0
})
