/**
 * UTILIDADES pequenas: selectores DOM, matematicas (clamp, lerp...), aleatorios.
 */
export const qs = (selector, t = document) => t.querySelector(selector)
export const qsa = (selector, t = document) => Array.prototype.slice.call(t.querySelectorAll(selector))
export const clamp = (value, min, max) => Math.min(max, Math.max(min, value))
export const lerp = (from, to, k) => from + (to - from) * k
export const damp = (from, to, rate, dt) => from + (to - from) * (1 - Math.exp(-rate * dt))
export const rand = (min, max) => min + Math.random() * (max - min)
export const createEl = (tag, className, html) => {
    let o = document.createElement(tag)
    if (className) {
        o.className = className
    }
    if (html != null) {
        o.innerHTML = html
    }
    return o
}
export const angleDiff = (from, to) => {
    let a = to - from
    for (; a > Math.PI;) a -= 2 * Math.PI
    for (; a < -Math.PI;) a += 2 * Math.PI
    return a
}
export const shuffle = (list) => {
    list = list.slice()
    for (let t = list.length - 1; t > 0; t--) {
        let a = Math.floor(Math.random() * (t + 1))
        ;[list[t], list[a]] = [list[a], list[t]]
    }
    return list
}
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches
export const isTouch = matchMedia('(pointer: coarse)').matches
/** Celular o tablet (pantalla angosta o vertical): las tarjetas van abajo y las escenas se encuadran al centro, no a un lado. (Un celular acostado, de poca altura, usa el diseno ancho: no cabria una tarjeta abajo.) */
export const isCompact = () => innerHeight > innerWidth || (innerWidth <= 820 && innerHeight > 520)
export const motionScale = reducedMotion ? 0.3 : 1
