/**
 * PIEZA DEL RASTREO EN 3D: un recuadro (a la izquierda de la pantalla) con la pieza en 3D que se puede girar con el mouse.
 * El titulo y el texto van en la tarjeta de siempre (#tip, la misma del kit; ver startInfoTour en steps/helpers.js).
 * Para el microchip el recuadro es un circulo verde con la capsula y un cono de luz lo une con el lugar del cuerpo donde se
 * pone (como en la imagen de referencia).
 */
import * as THREE from 'three'
import { isCompact } from '../core/utils.js'
import { camera } from '../three/renderer.js'
import { createMiniViewer } from './miniViewer.js'

const NS = 'http://www.w3.org/2000/svg'
const v = new THREE.Vector3()

/**
 * opts: { object (lo que se ve en 3D), round (circulo verde + cono), anchor (de donde sale el cono) }
 * Devuelve { update(), close() }; update() se llama cada cuadro (mueve el cono) y close() quita todo.
 */
export function showTrackInfo({ object, round = false, anchor = null }) {
    const el = document.createElement('div')
    el.id = 'trackInfo'
    el.className = 'tframe' + (round ? ' round' : '')
    el.innerHTML = '<canvas></canvas><span class="hint">Arrastra con el mouse para girar</span>'
    document.body.appendChild(el)
    requestAnimationFrame(() => el.classList.add('on'))
    const viewer = createMiniViewer(el.querySelector('canvas'), object, round ? { fov: 28, tilt: 0.25, margin: 1.7 } : {})

    // cono de luz desde el lugar del cuerpo hasta el circulo (solo el microchip)
    let svg = null
    let poly = null
    let dot = null
    if (round && anchor) {
        svg = document.createElementNS(NS, 'svg')
        svg.id = 'trackCone'
        svg.innerHTML =
            '<defs><linearGradient id="coneGrad" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#2fe58a" stop-opacity="0.75"/><stop offset="1" stop-color="#2fe58a" stop-opacity="0.12"/></linearGradient></defs><polygon fill="url(#coneGrad)"/><circle r="9" fill="#27e28a" stroke="#fff" stroke-width="3"/>'
        document.body.appendChild(svg)
        poly = svg.querySelector('polygon')
        dot = svg.querySelector('circle')
        requestAnimationFrame(() => svg.classList.add('on'))
    }
    const update = () => {
        if (!svg) return
        anchor.getWorldPosition(v).project(camera)
        if (v.z > 1) return
        const px = (v.x * 0.5 + 0.5) * innerWidth
        const py = (-v.y * 0.5 + 0.5) * innerHeight
        // si el lugar del cuerpo queda debajo del recuadro, el recuadro se corre hacia un lado: asi el cono y el punto siempre se ven
        if (!isCompact()) {
            const half = el.offsetWidth / 2
            const base = innerWidth * 0.24 // donde va normalmente (ver .tframe)
            let center = base
            if (px > base - half - 50 && px < base + half + 50) {
                center = px - half - 70 > half + 16 ? px - half - 70 : px + half + 70
            }
            el.style.left = center + 'px'
        }
        const r = el.getBoundingClientRect()
        const cx = r.left + r.width / 2
        const cy = r.top + r.height / 2
        if (px > r.left - 4 && px < r.right + 4 && py > r.top - 4 && py < r.bottom + 4) return
        // el cono sale del punto y se apoya en las dos esquinas del cuadrado que lo "abrazan" (las de mayor y menor angulo)
        const toCenter = Math.atan2(cy - py, cx - px)
        let a = null
        let b = null
        let lo = Infinity
        let hi = -Infinity
        ;[
            [r.left, r.top],
            [r.right, r.top],
            [r.right, r.bottom],
            [r.left, r.bottom],
        ].forEach((corner) => {
            let diff = Math.atan2(corner[1] - py, corner[0] - px) - toCenter
            diff = Math.atan2(Math.sin(diff), Math.cos(diff))
            if (diff < lo) {
                lo = diff
                a = corner
            }
            if (diff > hi) {
                hi = diff
                b = corner
            }
        })
        poly.setAttribute('points', `${px},${py} ${a[0]},${a[1]} ${b[0]},${b[1]}`)
        const g = svg.querySelector('linearGradient')
        g.setAttribute('x1', px)
        g.setAttribute('y1', py)
        g.setAttribute('x2', cx)
        g.setAttribute('y2', cy)
        dot.setAttribute('cx', px)
        dot.setAttribute('cy', py)
    }
    return {
        update,
        close() {
            viewer.dispose()
            el.remove()
            svg?.remove()
        },
    }
}
