/**
 * ACABADO DEL INTERIOR (la sala de primera persona y el cuarto de tercera persona): paredes casi blancas con un degradado suave en
 * las esquinas (oclusion falsa), piso de tablones de madera con brillo y maderas oscuras, como en una imagen de referencia de un
 * cuarto isometrico. Aqui estan los colores y las funciones comunes; cada habitacion las usa al pintar su .glb.
 */
import * as THREE from 'three'

export const INTERIOR = {
    wall: '#dde0e6',
    ceiling: '#eceef2',
    floor: '#c9915a', // color de base bajo los tablones
    woodLight: '#b88255',
    wood: '#9a6538',
    woodDark: '#8d5a34',
    doorWood: '#7b4b29',
    metal: '#3f4857', // rejas de metal gris azulado
    frame: '#4b4d52', // marcos de los cuadros (gris oscuro mate)
}

const wallColor = new THREE.Color(INTERIOR.wall)
/**
 * Color de la pared a la altura y: un poco mas oscura junto al piso y junto al techo (como la luz que no llega a las esquinas).
 * Devuelve un THREE.Color nuevo (paintVertices lo acepta).
 */
export function shadedWall(y, ceilingY = 2.55) {
    const low = Math.min(1, Math.max(0, y / 0.7)) // 0 en el piso, 1 a 0.7 m
    const high = Math.min(1, Math.max(0, (y - (ceilingY - 0.4)) / 0.4)) // 0 a 0.4 m del techo, 1 en el techo
    const k = 0.84 + 0.16 * low - 0.08 * high
    return wallColor.clone().multiplyScalar(k)
}

// ---- shaders propios de los materiales de este archivo (piso, tela, madera de los muebles)
// Dos cosas de three.js a tener en cuenta: (1) onBeforeCompile solo se llama con el primer material de cada programa (clave de cache), asi que
// cada material necesita su propia clave o los demas se quedan sin sus uniforms (la textura se ve negra); (2) material.clone() no copia
// onBeforeCompile (el vecindario clona los materiales de la escena): por eso se recuerda como armar el shader de cada uno y se vuelve a poner
// en las copias.
let shaderCount = 0
const shaderOf = new WeakMap()
function registerShader(material, prefix) {
    const onBeforeCompile = material.onBeforeCompile
    const set = (m) => {
        const key = prefix + '-' + ++shaderCount
        m.onBeforeCompile = onBeforeCompile
        m.customProgramCacheKey = () => key
        m.needsUpdate = true
        shaderOf.set(m, set)
    }
    set(material)
}
const baseCopy = THREE.Material.prototype.copy
THREE.Material.prototype.copy = function (source) {
    baseCopy.call(this, source)
    const set = shaderOf.get(source)
    if (set) set(this)
    return this
}
let woodTexture = null
/** Lado (m) que cubre una repeticion de la textura del piso (static/piso-madera.webp, 10 hileras de tablones: cada tablon mide ~0.16 m de ancho). */
export const PLANK_TILE = 1.6
/** Textura del piso de madera (una imagen que se repite sin costuras). */
export function plankTexture() {
    if (woodTexture) return woodTexture
    woodTexture = new THREE.TextureLoader().load(import.meta.env.BASE_URL + 'piso-madera.webp')
    woodTexture.colorSpace = THREE.SRGBColorSpace
    woodTexture.wrapS = woodTexture.wrapT = THREE.RepeatWrapping
    woodTexture.anisotropy = 8
    return woodTexture
}

/**
 * Material del piso de madera. Una textura que se repite cada 1.6 m deja ver el patron (los mismos tablones una y otra vez): para
 * que se vea natural, el color se varia con un ruido suave segun el lugar del piso (mas claro y oscuro por zonas, estirado a lo largo
 * de los tablones, y un poco mas calido o frio), asi dos repeticiones nunca se ven iguales.
 */
export function woodMaterial(extra = {}) {
    const material = new THREE.MeshStandardMaterial({ map: plankTexture(), roughness: 0.4, metalness: 0, ...extra })
    material.onBeforeCompile = (shader) => {
        shader.vertexShader = shader.vertexShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vWoodPos;')
            .replace('#include <begin_vertex>', '#include <begin_vertex>\nvWoodPos = (modelMatrix * vec4(transformed, 1.0)).xyz;')
        shader.fragmentShader = shader.fragmentShader
            .replace(
                '#include <common>',
                `#include <common>
varying vec3 vWoodPos;
float woodHash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float woodNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(woodHash(i), woodHash(i + vec2(1.0, 0.0)), f.x), mix(woodHash(i + vec2(0.0, 1.0)), woodHash(i + vec2(1.0, 1.0)), f.x), f.y);
}`,
            )
            .replace(
                '#include <map_fragment>',
                `#include <map_fragment>
{
    vec2 q = vec2(vWoodPos.x * 0.22, vWoodPos.z * 0.9);
    float n = woodNoise(q) * 0.6 + woodNoise(q * 2.7 + 5.3) * 0.4; // 0..1
    float plank = woodHash(vec2(floor(vWoodPos.z / 0.16), 3.0)); // cada hilera de tablones, un poco distinta
    float k = (n - 0.5) * 0.2 + (plank - 0.5) * 0.07;
    diffuseColor.rgb *= vec3(1.0 + k * 1.15, 1.0 + k, 1.0 + k * 0.8);
    float luma = dot(diffuseColor.rgb, vec3(0.299, 0.587, 0.114));
    diffuseColor.rgb = mix(vec3(luma), diffuseColor.rgb, 0.62) * vec3(1.02, 1.0, 0.97); // menos saturado, mas neutro
}`,
            )
    }
    registerShader(material, 'woodFloor')
    return material
}

let fabricMap = null
/** Textura de tela tejida en grises (static/tela.png): da el relieve del tejido sin cambiar el color de la pieza. */
export function fabricTexture() {
    if (fabricMap) return fabricMap
    fabricMap = new THREE.TextureLoader().load(import.meta.env.BASE_URL + 'tela.png')
    fabricMap.colorSpace = THREE.NoColorSpace // (es un dato que multiplica el color, no un color: sin conversion)
    fabricMap.wrapS = fabricMap.wrapT = THREE.RepeatWrapping
    fabricMap.anisotropy = 8
    return fabricMap
}

/**
 * Le pone el tejido de tela a un material (el sofa, el sillon, la sabana): conserva su color y le suma las hebras. Las piezas no tienen
 * coordenadas de textura utiles, asi que la textura se proyecta desde las tres direcciones segun el lugar y la orientacion de cada punto.
 * tile = lado (m) que cubre una repeticion. Devuelve el mismo material.
 */
/** 0..1: cuanto se aligera la sombra de los soles y focos sobre las caras verticales de las telas con softVertical (el respaldo del sofa). Lo mueve livingRoom.js. */
export const fabricShadow = { value: 0 }
let softLights = null
/** La luz de three.js con las sombras de focos, soles y lamparas mezcladas segun la orientacion de la cara: arriba (asiento) se queda igual, de frente (respaldo) se aligera. */
function softLightsChunk() {
    if (softLights) return softLights
    softLights = THREE.ShaderChunk.lights_fragment_begin.replace(
        /directLight\.color \*= \( directLight\.visible && receiveShadow \) \? (get(?:Point)?Shadow\([^;]*?\)) : 1\.0;/g, // (focos, soles y lamparas puntuales)
        'directLight.color *= mix(1.0, ( directLight.visible && receiveShadow ) ? $1 : 1.0, shadowKeep);',
    )
    return softLights
}
export function applyFabric(material, tile = 0.3, softVertical = false) {
    material.onBeforeCompile = (shader) => {
        shader.uniforms.fabricMap = { value: fabricTexture() }
        shader.uniforms.fabricTile = { value: tile }
        shader.uniforms.fabricShadow = fabricShadow
        if (softVertical) {
            // las caras que miran de frente (el respaldo) reciben la sombra mucho mas suave que las de arriba (el asiento): sin cambiar las luces
            shader.fragmentShader = shader.fragmentShader
                .replace('#include <common>', '#include <common>\nuniform float fabricShadow;')
                .replace(
                    '#include <lights_fragment_begin>',
                    `float shadowKeep = mix(1.0, mix(0.12, 1.0, smoothstep(0.45, 0.85, abs(normalize(vFabNor).y))), fabricShadow);\n${softLightsChunk()}`,
                )
        }
        shader.vertexShader = shader.vertexShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vFabPos;\nvarying vec3 vFabNor;')
            .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\nvFabNor = normalize(mat3(modelMatrix) * objectNormal);')
            .replace('#include <begin_vertex>', '#include <begin_vertex>\nvFabPos = (modelMatrix * vec4(transformed, 1.0)).xyz;')
        shader.fragmentShader = shader.fragmentShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vFabPos;\nvarying vec3 vFabNor;\nuniform sampler2D fabricMap;\nuniform float fabricTile;')
            .replace(
                '#include <map_fragment>',
                `#include <map_fragment>
{
    vec3 w = pow(abs(normalize(vFabNor)) + 0.001, vec3(4.0));
    w /= (w.x + w.y + w.z);
    vec3 p = vFabPos / fabricTile;
    float t = texture2D(fabricMap, p.zy).r * w.x + texture2D(fabricMap, p.xz).r * w.y + texture2D(fabricMap, p.xy).r * w.z;
    diffuseColor.rgb *= t * 1.22;
}`,
            )
    }
    registerShader(material, 'fabric')
    return material
}

let grainMap = null
const WOOD_COLORS = new Set([INTERIOR.floor, INTERIOR.woodLight, INTERIOR.wood, INTERIOR.woodDark, INTERIOR.doorWood, '#c99a68'].map((c) => new THREE.Color(c).getHexString()))
/** Veta de madera en grises (static/madera.png: un tablon de la imagen del piso, reflejado para repetirse sin costuras). */
export function grainTexture() {
    if (grainMap) return grainMap
    grainMap = new THREE.TextureLoader().load(import.meta.env.BASE_URL + 'madera.png')
    grainMap.colorSpace = THREE.NoColorSpace
    grainMap.wrapS = grainMap.wrapT = THREE.RepeatWrapping
    grainMap.anisotropy = 8
    return grainMap
}

/**
 * Le pone la veta de la madera del piso a un material de mueble (conserva su tono: oscuro en las puertas, claro en los cuerpos). La veta se
 * proyecta desde las tres direcciones segun el lugar de cada punto (las piezas no traen coordenadas de textura utiles): corre a lo largo de x
 * en las tapas y las caras de frente, y a lo largo de z en las caras de lado; con vertical = true (puertas y armarios) corre hacia arriba.
 */
export function applyWoodGrain(material, vertical = false) {
    material.onBeforeCompile = (shader) => {
        shader.uniforms.grainMap = { value: grainTexture() }
        shader.uniforms.grainVertical = { value: vertical ? 1 : 0 }
        shader.vertexShader = shader.vertexShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vGrainPos;\nvarying vec3 vGrainNor;')
            .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\nvGrainNor = normalize(mat3(modelMatrix) * objectNormal);')
            .replace('#include <begin_vertex>', '#include <begin_vertex>\nvGrainPos = (modelMatrix * vec4(transformed, 1.0)).xyz;')
        shader.fragmentShader = shader.fragmentShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vGrainPos;\nvarying vec3 vGrainNor;\nuniform sampler2D grainMap;\nuniform float grainVertical;')
            .replace(
                '#include <map_fragment>',
                `#include <map_fragment>
{
    vec3 w = pow(abs(normalize(vGrainNor)) + 0.001, vec3(4.0));
    w /= (w.x + w.y + w.z);
    // la veta mide 2.4 m de largo y 0.3 m de ancho por repeticion
    vec2 side = grainVertical > 0.5 ? vec2(vGrainPos.y / 2.4, vGrainPos.z / 0.3) : vec2(vGrainPos.z / 2.4, vGrainPos.y / 0.3);
    vec2 front = grainVertical > 0.5 ? vec2(vGrainPos.y / 2.4, vGrainPos.x / 0.3) : vec2(vGrainPos.x / 2.4, vGrainPos.y / 0.3);
    vec2 top = vec2(vGrainPos.x / 2.4, vGrainPos.z / 0.3);
    float t = texture2D(grainMap, side).r * w.x + texture2D(grainMap, top).r * w.y + texture2D(grainMap, front).r * w.z;
    diffuseColor.rgb *= t * 1.08;
}`,
            )
    }
    registerShader(material, 'grain')
    return material
}

/** Pone la veta a todos los muebles de madera de una escena (los que tienen alguno de los tonos de madera). Las puertas y armarios, con la veta hacia arriba. */
export function woodenFurniture(root) {
    root.traverse((o) => {
        if (!o.isMesh || !o.material || Array.isArray(o.material) || o.material.vertexColors || o.material.map) return
        if (!WOOD_COLORS.has(o.material.color.getHexString())) return
        let top = o
        while (top.parent && top.parent !== root) top = top.parent
        const vertical = /^(puerta|armario)/.test(top.name) || /^(puerta|armario)/.test(o.name)
        o.material = applyWoodGrain(o.material.clone(), vertical)
    })
}

// Las tres laminas de los cuadros y la imagen de cada una (static/cuadro-1.png ... cuadro-3.png)
const PICTURES = { imagen: 'cuadro-1.png', imagen001: 'cuadro-2.png', imagen002: 'cuadro-3.png' }
/**
 * Pone una ilustracion en cada lamina de cuadro de una escena. Las laminas son un rectangulo vertical con coordenadas de textura que no
 * sirven, asi que se calculan de nuevo: u hacia la derecha de quien mira la cara de frente, v hacia arriba.
 */
export function paintPictures(root) {
    const loader = new THREE.TextureLoader()
    root.traverse((o) => {
        const file = PICTURES[o.name]
        if (!o.isMesh || !file) return
        const geo = o.geometry
        const pos = geo.attributes.position
        const idx = geo.index
        const at = (i) => new THREE.Vector3().fromBufferAttribute(pos, idx ? idx.getX(i) : i)
        const normal = new THREE.Vector3().crossVectors(at(1).sub(at(0)), at(2).sub(at(0))).normalize() // (la cara de frente mira hacia la sala)
        const right = new THREE.Vector3(0, 1, 0).cross(normal).normalize()
        const box = new THREE.Box3().setFromBufferAttribute(pos)
        let uMin = Infinity
        let uMax = -Infinity
        const p = new THREE.Vector3()
        for (let i = 0; i < pos.count; i++) {
            const d = p.fromBufferAttribute(pos, i).dot(right)
            uMin = Math.min(uMin, d)
            uMax = Math.max(uMax, d)
        }
        const uv = new Float32Array(pos.count * 2)
        for (let i = 0; i < pos.count; i++) {
            p.fromBufferAttribute(pos, i)
            uv[i * 2] = (p.dot(right) - uMin) / (uMax - uMin || 1)
            uv[i * 2 + 1] = (p.y - box.min.y) / (box.max.y - box.min.y || 1)
        }
        geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2))
        const map = loader.load(import.meta.env.BASE_URL + file)
        map.colorSpace = THREE.SRGBColorSpace
        map.anisotropy = 8
        // (un poco de brillo propio: una lamina en la pared no queda oscura ni lavada con la luz de la sala)
        o.material = new THREE.MeshStandardMaterial({ map, emissiveMap: map, emissive: '#ffffff', emissiveIntensity: 0.22, roughness: 0.6, metalness: 0, side: THREE.DoubleSide })
        o.castShadow = false
    })
}

const detailMaps = {}
/**
 * Le suma a un material (paredes pintadas por vertice) el grano de un revoque: `file` es una textura en grises de static/ (muro-interior.png:
 * pared lisa; muro-exterior.png: pared con textura) que multiplica el color sin cambiarlo. Se proyecta desde las tres direcciones (como la
 * tela). tile = lado (m) de una repeticion; strength = cuanto se nota (0 nada, 1 completo). Devuelve el mismo material.
 */
export function applyWallDetail(material, file, tile = 1.2, strength = 1) {
    const map = (detailMaps[file] ||= (() => {
        const tex = new THREE.TextureLoader().load(import.meta.env.BASE_URL + file)
        tex.colorSpace = THREE.NoColorSpace
        tex.wrapS = tex.wrapT = THREE.RepeatWrapping
        tex.anisotropy = 8
        return tex
    })())
    material.onBeforeCompile = (shader) => {
        shader.uniforms.wallMap = { value: map }
        shader.vertexShader = shader.vertexShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vWallPos;\nvarying vec3 vWallNor;')
            .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\nvWallNor = normalize(mat3(modelMatrix) * objectNormal);')
            .replace('#include <begin_vertex>', '#include <begin_vertex>\nvWallPos = (modelMatrix * vec4(transformed, 1.0)).xyz;')
        shader.fragmentShader = shader.fragmentShader
            .replace('#include <common>', '#include <common>\nvarying vec3 vWallPos;\nvarying vec3 vWallNor;\nuniform sampler2D wallMap;')
            .replace(
                '#include <color_fragment>',
                `#include <color_fragment>
{
    vec3 w = pow(abs(normalize(vWallNor)) + 0.001, vec3(4.0));
    w /= (w.x + w.y + w.z);
    vec3 p = vWallPos / ${tile.toFixed(3)};
    float t = texture2D(wallMap, p.zy).r * w.x + texture2D(wallMap, p.xz).r * w.y + texture2D(wallMap, p.xy).r * w.z;
    diffuseColor.rgb *= mix(1.0, t * 1.08, ${strength.toFixed(3)});
}`,
            )
    }
    registerShader(material, 'wall' + file)
    return material
}
/** Piso de tablones sobre el piso de la malla: plano de x0..x1 por z0..z1, apenas por encima de y. Brilla un poco con las luces. */
export function addWoodFloor(parent, { x0, x1, z0, z1, y }, clip = null) {
    const w = x1 - x0
    const d = z1 - z0
    const texture = plankTexture().clone()
    texture.needsUpdate = true
    texture.repeat.set(w / PLANK_TILE, d / PLANK_TILE)
    const floor = new THREE.Mesh(
        new THREE.PlaneGeometry(w, d),
        woodMaterial({ map: texture, clippingPlanes: clip }),
    )
    floor.rotation.x = -Math.PI / 2
    floor.position.set((x0 + x1) / 2, y + 0.004, (z0 + z1) / 2)
    floor.receiveShadow = true
    parent.add(floor)
    return floor
}

/**
 * Lampara del techo que proyecta sombras hacia abajo (como la sombra del perro con el sol, pero vista desde arriba): un foco apuntando
 * al piso, ancho y de borde suave. Los muebles, las mascotas y el personaje dejan su sombra en el piso de la habitacion.
 */
export function createCeilingSpot(parent, x, y, z, intensity, aim = [x, z], color = '#fff1dc') {
    const spot = new THREE.SpotLight(color, intensity, 0, 1.25, 1, 0) // (distancia 0 = sin limite; decay 0 = no se apaga con la distancia)
    spot.position.set(x, y, z)
    spot.target.position.set(aim[0], 0, aim[1]) // (apunta algo en diagonal: asi las sombras se alargan sobre el piso y se ven desde arriba)
    spot.castShadow = true
    spot.shadow.intensity = 0.55 // sombras suaves, no negras
    spot.shadow.radius = 3
    spot.shadow.mapSize.set(2048, 2048)
    spot.shadow.camera.near = 0.15
    spot.shadow.camera.far = 8
    spot.shadow.bias = -0.0004
    spot.shadow.normalBias = 0.02
    parent.add(spot, spot.target)
    return spot
}
/**
 * El pomo de las puertas del .glb solo esta de un lado de la hoja: del otro se ve la hoja lisa (o el pomo medio hundido). Esta funcion
 * copia las piezas del pomo reflejadas al otro lado, para que la puerta se vea bien desde las dos caras. `leaf` es la malla de la hoja;
 * el pomo se detecta por sus normales (las de una esfera no apuntan a un eje) y el grosor de la hoja (0.014 m) viene del modelo.
 */
export function addMirroredKnob(leaf) {
    if (leaf.userData.mirroredKnob) return null // (el pomo reflejado no se vuelve a reflejar)
    leaf.userData.mirroredKnob = true
    const geo = leaf.geometry
    const pos = geo.attributes.position
    const nor = geo.attributes.normal
    const index = geo.index ? Array.from(geo.index.array) : Array.from({ length: pos.count }, (_, i) => i)
    const round = new THREE.Box3()
    const point = new THREE.Vector3()
    for (let i = 0; i < pos.count; i++) {
        if (Math.max(Math.abs(nor.getX(i)), Math.abs(nor.getY(i)), Math.abs(nor.getZ(i))) < 0.95) round.expandByPoint(point.fromBufferAttribute(pos, i))
    }
    if (round.isEmpty()) return null
    const base = round.min.x
    const mirror = base - 0.007 // plano medio de la hoja
    const inKnob = (i) =>
        pos.getX(i) >= base - 0.001 &&
        pos.getY(i) >= round.min.y - 0.01 && pos.getY(i) <= round.max.y + 0.01 &&
        pos.getZ(i) >= round.min.z - 0.01 && pos.getZ(i) <= round.max.z + 0.01
    const positions = []
    const normals = []
    for (let t = 0; t < index.length; t += 3) {
        const tri = [index[t], index[t + 1], index[t + 2]]
        if (!tri.every(inKnob)) continue
        // reflejado: la x cambia de lado y el orden de los vertices se invierte (para que la cara mire hacia afuera)
        ;[tri[0], tri[2], tri[1]].forEach((i) => {
            positions.push(2 * mirror - pos.getX(i), pos.getY(i), pos.getZ(i))
            normals.push(-nor.getX(i), nor.getY(i), nor.getZ(i))
        })
    }
    if (!positions.length) return null
    const copy = new THREE.BufferGeometry()
    copy.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    copy.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3))
    const knob = new THREE.Mesh(copy, leaf.material)
    knob.userData.mirroredKnob = true
    knob.castShadow = leaf.castShadow
    knob.receiveShadow = leaf.receiveShadow
    leaf.add(knob)
    return knob
}