/**
 * EFECTOS DEL SISMO: luces que parpadean, libros que caen,
 * cuadros que se mueven y polvo.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { LIGHT_SCALE } from '../config.js'
import { state } from '../core/state.js'
import { clamp, lerp, motionScale, qs, rand } from '../core/utils.js'
import { quake } from './quake.js'
import { rigK, updateRig } from '../three/lightRig.js'
import { camera, exteriorLights, fillLight, hemiLight, interiorLights, LIGHT_LEVELS, lampLight, lightDim, lightTuning, sunLight } from '../three/renderer.js'
import { livingRoom } from '../three/livingRoom.js'
import { neighborhoodGlow, setSideHouseGhost } from '../three/neighborhood.js'
import { updatePetGlows } from '../three/petGlow.js'
import { world } from '../three/world.js'
import { setBackground } from '../ui/hud.js'

const CALM_HEMI = new THREE.Color('#d4e5ff')
const QUAKE_HEMI = new THREE.Color('#8a8ec9') // ambiente del sismo: azul lila
const CALM_SUN = new THREE.Color('#eef4ff') // sol calido de la ventana
const QUAKE_SUN = new THREE.Color('#aab6ff')
export function dropBooks(count) {
    let t = 0
    world.books.forEach((a) => {
        if (a.state === 0 && t < count) {
            a.state = 1
            a.t = -a.delay
            t++
        }
    })
}
export function resetBooks() {
    world.books.forEach((e) => {
        e.state = 0
        e.m.position.copy(e.home)
        e.m.rotation.copy(e.homeRot)
        if (e.m.parent !== e.parent) {
            e.parent.add(e.m)
        }
    })
}
export function updateBooks(dt) {
    world.books.forEach((t) => {
        if (t.state === 1) {
            t.t += dt
            if (t.t > 0) {
                t.state = 2
                let a = new THREE.Vector3()
                t.m.getWorldPosition(a)
                t.parent.remove(t.m)
                t.m.position.copy(a)
                world.root.add(t.m)
                t.v.set(rand(-0.6, 0.6), rand(0.3, 1), rand(0.8, 2))
                t.rv.set(rand(-5, 5), rand(-3, 3), rand(-5, 5))
                audio.crash()
            }
        } else {
            if (t.state === 2) {
                t.v.y -= 9.8 * dt
                t.m.position.addScaledVector(t.v, dt)
                t.m.rotation.x += t.rv.x * dt
                t.m.rotation.z += t.rv.z * dt
                if (t.m.position.y < 0.08) {
                    t.m.position.y = 0.08
                    t.state = 3
                    t.m.rotation.set(Math.PI / 2, rand(0, 6), rand(-0.4, 0.4))
                }
            }
        }
    })
}
export function updateQuakeEffects(dt) {
    let t = quake.shakeK * motionScale, // sacudida de la casa (baja al ver a la mascota)
        a = quake.k // luz, polvo y cuadros: no cambian
    world.root.position.set((Math.random() - 0.5) * 0.06 * t, 0, (Math.random() - 0.5) * 0.06 * t)
    world.pics.forEach((r, i) => {
        r.rotation.z = Math.sin(state.time * 7 + i * 2) * 0.22 * a
    })
    world.plant.rotation.z = Math.sin(state.time * 11) * 0.06 * a
    world.shade.rotation.z = Math.sin(state.time * 8) * 0.16 * a
    // las luces parpadean menos cuanto mas suave es el temblor (en los tamanos casi no parpadean)
    let o = a > 0.3 ? 0.55 + 0.45 * Math.abs(Math.sin(state.time * 23) * Math.sin(state.time * 7.3)) : 1
    o = 1 - (1 - o) * Math.min(1, quake.shake)
    lightDim.v += (lightDim.t - lightDim.v) * Math.min(1, dt * 2.5)
    // Luces: pasan de colores calidos a frios y parpadean con la intensidad del sismo
    hemiLight.color.copy(CALM_HEMI).lerp(QUAKE_HEMI, a)
    hemiLight.intensity = lerp(LIGHT_LEVELS.hemi[0], LIGHT_LEVELS.hemi[1], a) * o * LIGHT_SCALE * lightDim.v
    sunLight.color.copy(CALM_SUN).lerp(QUAKE_SUN, a)
    sunLight.intensity = lerp(LIGHT_LEVELS.sun[0], LIGHT_LEVELS.sun[1], a) * o * LIGHT_SCALE * lightDim.v
    lampLight.intensity = 0.5 * LIGHT_SCALE * (a > 0.3 ? o : 1) * lightDim.v
    // intensidad de la luz de afuera y de adentro (ajustable con F2)
    updateRig() // (aplica los ajustes guardados de la tecla L a las luces que ya estan en la escena)
    hemiLight.intensity *= lightTuning.outdoor * rigK(hemiLight)
    if (livingRoom.fileLights && livingRoom.root.visible) hemiLight.intensity *= 0.35 // con las luces del .glb solo queda un ambiente tenue (sin el, las sombras quedan negras)
    sunLight.intensity *= lightTuning.outdoor * rigK(sunLight)
    fillLight.intensity = 0.22 * LIGHT_SCALE * lightTuning.outdoor * rigK(fillLight)
    lampLight.intensity *= lightTuning.indoor * rigK(lampLight)
    updatePetGlows(dt, state.time) // contorno de luz de las mascotas que se pueden tocar
    // con las luces propias del .glb de la sala (la sala y tambien la portada, que muestra su entrada) se apagan el sol y el relleno de la casa de cajas
    const ownLight = livingRoom.fileLights && livingRoom.root.visible
    sunLight.visible = fillLight.visible = !ownLight
    // luz general de afuera (todo el vecindario) y casas de los lados transparentes solo cuando la camara esta dentro de la casa
    const inside = livingRoom.root.visible && camera.position.x < 3.3 && camera.position.x > -2.2 && Math.abs(camera.position.z) < 3.05
    setSideHouseGhost(inside, dt)
    const glow = livingRoom.fileLights && livingRoom.root.visible ? 0.4 * lightTuning.outdoor : 0
    neighborhoodGlow.forEach((m) => (m.emissiveIntensity = glow))
    exteriorLights.forEach((light) => (light.intensity = light.userData.base * lightTuning.outdoor * lightDim.v * rigK(light) * (light.userData.gate ?? 1)))
    interiorLights.forEach((light) => (light.intensity = light.userData.base * lightTuning.indoor * (a > 0.3 ? o : 1) * rigK(light) * (light.userData.gate ?? 1)))
    // Polvo que cae durante el temblor
    world.dust.material.opacity = clamp(a * 1.3, 0, 0.7)
    world.dust.visible = a > 0.02
    if (world.dust.visible) {
        let r = world.dust.geometry.attributes.position
        for (let i = 0; i < r.count; i++) {
            let n = r.getY(i) - dt * (0.3 + (i % 5) * 0.15)
            if (n < 0) {
                n = 3
            }
            r.setY(i, n)
        }
        r.needsUpdate = true
    }
    let s = state.mode !== 'show' && quake.k > 0.2
    setBackground(state.bgOverride || (state.mode === 'show' ? 'show' : s ? 'dusk' : 'day'))
    qs('#fx').classList.toggle('quake', quake.k > 0.35 && quake.shake > 0.6) // sin el borde rojo cuando el temblor es suave
}
