/**
 * RENDERER, escenas, camara y luces.
 * mainScene = la casa. showScene = escenarios de 'vitrina' (kit, tamanos, guia...).
 */
import * as THREE from 'three'
import { LIGHT_SCALE } from '../config.js'
import { registerRigLight } from './lightRig.js'
import { state } from '../core/state.js'
import { qs } from '../core/utils.js'

// Compatibilidad: la demo se hizo con three r128. Desde r152/r155 three cambia el manejo
// de color y las unidades de luz; estas lineas mantienen el aspecto original.
THREE.ColorManagement.enabled = false

export const canvas = qs('#gl')
export const renderer = new THREE.WebGLRenderer({
    canvas: canvas,
    antialias: true,
    alpha: true,
})
renderer.outputColorSpace = THREE.LinearSRGBColorSpace
renderer.localClippingEnabled = true // los objetos del kit se recortan con el borde de la maleta (ver kitGlb.js)
// (tope de 1.5: en pantallas de alta densidad dibujar a 2x cuesta casi el doble y casi no se nota; main.js lo baja solo si va lento)
// (equipos con poca memoria o con ahorro de datos: tope de 1, que cuesta menos de la mitad; main.js lo baja solo si aun asi va lento)
const LOW_END = (navigator.deviceMemory && navigator.deviceMemory <= 2) || navigator.connection?.saveData === true
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, LOW_END ? 1 : 1.5))
renderer.shadowMap.enabled = true
renderer.shadowMap.type = THREE.PCFSoftShadowMap // bordes suaves, sin cuadritos (con esta el desenfoque lo pone three: shadow.radius ya no hace falta)
// Suaviza los brillos fuertes (blancos quemados) sin cambiar los colores medios: solo comprime lo que pasa de blanco
renderer.toneMapping = THREE.NeutralToneMapping
renderer.toneMappingExposure = 0.92
renderer.setClearColor(0, 0)
export const mainScene = new THREE.Scene()
export const showScene = new THREE.Scene()
export const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 120)
camera.rotation.order = 'YXZ'
Object.assign(state, {
    scene: mainScene,
})
// La luz se veia plana por tres razones: (1) la luz ambiental (hemisferio) era casi tan fuerte como el sol, asi que las caras que no miran
// al sol quedaban igual de claras que las que si; (2) el sol caia casi desde arriba (53 grados), sin un lado de sombra claro y sin
// relacion con las ventanas; (3) las paredes y el techo de la sala no proyectaban sombra. Ahora el ambiente es suave (solo para que las
// zonas en sombra se sigan viendo), el sol entra desde el lado de la ventana de la derecha (x = 3.4) con un angulo de ~40 grados, y
// los muebles tienen sombras de contacto suaves (ver livingRoom.js y characters.js).
// (Estos son los valores base: quakeEffects.js los mueve con el sismo.)
// UNICA fuente de los niveles de luz: quakeEffects.js los lee cada cuadro (calma -> sismo) y reescribe la intensidad de estas dos luces.
// (Antes los numeros estaban escritos en dos archivos y el de aqui se pisaba solo: por eso algunos cambios de luz "no se notaban".)
export const LIGHT_LEVELS = {
    hemi: [0.8, 0.34], // (mas ambiente y menos sol: el contraste entre luz y sombra es mas suave) // [en calma, durante el sismo]
    sun: [0.5, 0.3], // en calma el sol es mas fuerte y de un blanco frio y amable (sombras largas)
}
// Intensidad de la luz de afuera (sol, ambiente y relleno) y de la de adentro (lamparas): multiplicadores que se editan en vivo con F2
// (ver ui/walkTuner.js) y que quakeEffects.js aplica cada cuadro. Los ajustes guardados solo se leen en desarrollo.
export const LIGHT_TUNING_DEFAULT = { outdoor: 1.05, indoor: 0.65 }
export const lightTuning = { ...LIGHT_TUNING_DEFAULT }
if (import.meta.env.DEV) {
    try {
        Object.assign(lightTuning, JSON.parse(localStorage.getItem('petalert.light') || '{}'))
    } catch (e) {}
}
export const saveLightTuning = () => {
    try {
        localStorage.setItem('petalert.light', JSON.stringify(lightTuning))
    } catch (e) {}
}
/** Luces de adentro de la casa: cada una guarda su intensidad base y el multiplicador de interior se aplica encima. */
export const interiorLights = []
export function registerInterior(light) {
    light.userData.base = light.intensity
    interiorLights.push(light)
    return light
}
/** Luces de afuera que trae el .glb de la sala (el sol): igual, guardan su intensidad base y se les aplica el multiplicador de exterior. */
export const exteriorLights = []
export function registerExterior(light) {
    light.userData.base = light.intensity
    exteriorLights.push(light)
    return light
}
// Atenuado extra de las luces del dia (1 = normal): el inicio lo baja para que la escena no se confunda con el texto (v se acerca a t poco a poco)
export const lightDim = { v: 1, t: 1 }
export const hemiLight = new THREE.HemisphereLight('#d4e5ff', '#e6dccd', LIGHT_LEVELS.hemi[0] * LIGHT_SCALE)
export const sunLight = new THREE.DirectionalLight('#eef4ff', LIGHT_LEVELS.sun[0] * LIGHT_SCALE)
export const lampLight = new THREE.PointLight('#ffd9a0', 0.5 * LIGHT_SCALE, 7, 0)
export const hallLight = new THREE.PointLight('#ffd9a0', 0, 9, 0)
hallLight.position.set(-10.2, 2.4, 0.5)
mainScene.add(hemiLight, sunLight, lampLight, hallLight, sunLight.target)
sunLight.position.set(10, 6.8, 5.5) // entra desde la ventana de la derecha (x = 3.4) y un poco desde el fondo: ~42 grados de altura
sunLight.castShadow = true
sunLight.shadow.mapSize.set(2048, 2048) // (2048 tambien en pantallas tactiles: con 1024 las sombras se veian pixeladas)
// El area de la sombra se ajusta al tamano real de la escena (la sala y el cuarto miden ~6 m; el porche llega hasta x = 6): 15 m de lado
// bastan y dan sombras mas nitidas que un area mayor. (updateProjectionMatrix: sin esa llamada three ignora estos valores.)
Object.assign(sunLight.shadow.camera, {
    left: -7.5,
    right: 7.5,
    top: 7.5,
    bottom: -7.5,
    near: 4,
    far: 32,
})
sunLight.shadow.camera.updateProjectionMatrix()
sunLight.shadow.intensity = 0.65 // sombras menos oscuras
sunLight.shadow.radius = 2
sunLight.shadow.bias = -3e-4
sunLight.shadow.normalBias = 0.03 // quita las rayas (acne) en suelos y paredes sin separar la sombra de los objetos
// Luz de relleno suave desde el lado contrario, sin sombras (barata): da volumen y evita que las caras opuestas al sol queden planas
export const fillLight = new THREE.DirectionalLight('#a9c4f2', 0.18 * LIGHT_SCALE)
fillLight.position.set(-6, 5, -5)
mainScene.add(fillLight)
// Luces editables con la tecla L (ver lightRig.js y ui/lightEditor.js): el cielo, el sol, el relleno y la lampara de la casa de cajas
registerRigLight('mundo', 'cielo', 'Cielo (luz ambiente)', hemiLight)
registerRigLight('mundo', 'sol', 'Sol (direccional)', sunLight)
registerRigLight('mundo', 'relleno', 'Relleno frio (direccional)', fillLight)
registerRigLight('mundo', 'lampara', 'Lampara de la casa (puntual)', lampLight)
// Las escenas aparte (kit, cierre...) usan la misma luz que la experiencia: el mismo ambiente, el mismo sol frio y de lado y el mismo relleno suave;
// asi las mascotas se ven con el mismo volumen y los mismos colores (con una luz blanca y de frente se veian planas y lavadas).
// (ambiente bajo y luz principal fuerte y de lado: asi el cuerpo de las mascotas tiene lado claro y lado en sombra, con volumen)
showScene.add(new THREE.HemisphereLight('#d4e5ff', '#e6dccd', 0.38 * LIGHT_SCALE))
const showKeyLight = new THREE.DirectionalLight('#fff3e2', 1.25 * LIGHT_SCALE)
showKeyLight.position.set(7, 4.5, 3) // de lado y no muy alto, para que se marque la sombra del cuerpo
showScene.add(showKeyLight)
const showFillLight = new THREE.DirectionalLight('#a9c4f2', 0.12 * LIGHT_SCALE)
showFillLight.position.set(-6, 3, 4)
showScene.add(showFillLight)
export function resize() {
    const w = innerWidth
    const h = innerHeight
    renderer.setSize(w, h, false)
    camera.aspect = w / h
    camera.updateProjectionMatrix()
}
