/**
 * Ayudas para pintar mallas detalladas (capas high poly del perro y del gato): promediar un valor por vertice con el de sus vecinos
 * para que el borde entre zonas de color salga como un degradado limpio y no como escalones.
 */
export const clamp01 = (v) => Math.min(1, Math.max(0, v))
export const smooth01 = (a, b, x) => {
    const t = clamp01((x - a) / (b - a))
    return t * t * (3 - 2 * t)
}

/**
 * Cuando la capa detallada esta puesta, el low poly no se dibuja pero sigue en la escena como "molde" barato: proyecta la sombra y de el sale el contorno
 * luminoso de las mascotas (si el contorno y la sombra salieran de la malla detallada, costarian decenas de miles de triangulos de mas, varias veces).
 */
export function setShadowOnly(meshes, on) {
    for (const mesh of meshes) {
        mesh.visible = true
        for (const m of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) {
            m.colorWrite = !on
            m.depthWrite = !on
        }
    }
}

/** Vecinos de cada vertice (los que comparten una arista), en formato compacto: { start, list }. */
export function neighbours(geo) {
    const index = geo.index.array
    const n = geo.attributes.position.count
    const count = new Uint32Array(n + 1)
    for (let t = 0; t < index.length; t++) count[index[t] + 1] += 2
    for (let i = 0; i < n; i++) count[i + 1] += count[i]
    const fill = count.slice(0, n)
    const list = new Uint32Array(count[n])
    for (let t = 0; t < index.length; t += 3) {
        for (let k = 0; k < 3; k++) {
            const a = index[t + k]
            list[fill[a]++] = index[t + ((k + 1) % 3)]
            list[fill[a]++] = index[t + ((k + 2) % 3)]
        }
    }
    return { start: count, list }
}

/** Promedia un valor por vertice con el de sus vecinos (varias pasadas). Cambia el arreglo recibido. */
export function smoothOver(values, { start, list }, passes) {
    let from = values
    let to = new Float32Array(values.length)
    for (let p = 0; p < passes; p++) {
        for (let i = 0; i < from.length; i++) {
            let sum = 0
            for (let e = start[i]; e < start[i + 1]; e++) sum += from[list[e]]
            const m = start[i + 1] - start[i]
            to[i] = m ? from[i] * 0.5 + (sum / m) * 0.5 : from[i]
        }
        ;[from, to] = [to, from]
    }
    if (from !== values) values.set(from)
}
