/**
 * RECURSOS EN SEGUNDO PLANO: lo que solo se usa mas adelante (la habitacion de la etapa "Durante", el arnes y la camilla de los tamanos) se descarga
 * DESPUES de abrir la pagina, asi la pantalla de carga no espera por ello y se puede empezar antes. navigation.goTo() espera a que esten listos
 * si alguien llega a esa etapa antes de que terminen (muestra la pantalla de carga otra vez, solo un momento).
 */
export const lazyAssets = { ready: true, promise: Promise.resolve() }
export function setLazy(promise) {
    lazyAssets.ready = false
    lazyAssets.promise = Promise.resolve(promise)
        .catch((error) => console.warn('Algunos recursos en segundo plano no cargaron.', error))
        .finally(() => {
            lazyAssets.ready = true
        })
    return lazyAssets.promise
}
