/**
 * NERVIOSISMO: mientras dura el sismo, Cacao y Nube se ven asustados, no solo quietos: el temblor sube y baja, miran de lado a lado,
 * el perro jadea con la lengua afuera, la gata mueve la cola a tirones y, de vez en cuando, ladran o maullan bajito.
 * Se llama cada cuadro con nervousLife(mascota, dt, opciones); calmNerves(mascota) lo apaga.
 */
import { audio } from '../audio/audio.js'
import { angleDiff, rand } from '../core/utils.js'

const states = new WeakMap()

/**
 * opts: base = cuanto tiembla (0 a 1), volume = volumen del ladrido o maullido (1 = el normal), every = [min, max] segundos entre uno y otro,
 *       speak = false para que no ladre ni maulle.
 */
export function nervousLife(pet, dt, { base = 0.5, volume = 0.6, every = [4, 8], speak = true, watch = null, startle = null, look = true } = {}) {
    const a = pet.userData
    let n = states.get(pet)
    if (!n) {
        n = { t: Math.random() * 6, glanceT: 0.5, goal: 0, nextSpeak: rand(1.5, 3.5), pantT: 0, nextPant: rand(0.8, 2.5), nextStartle: startle ? rand(startle[0], startle[1]) : rand(6, 10) }
        states.set(pet, n)
    }
    n.t += dt
    // el temblor sube y baja (nunca se queda parejo) y de vez en cuando se sacude mas fuerte
    const burst = Math.max(0, Math.sin(n.t * 0.9)) ** 3
    a.shiver = Math.max(0.2, base * (0.85 + 0.25 * Math.sin(n.t * 1.7) + 0.15 * Math.sin(n.t * 4.3) + 0.35 * burst))
    if (!look) {
        // solo temblor: sin miradas a los lados, sin jadeo ni saltitos (los pasos de los tamanos)
        a.glance = 0
        a.pantOn = false
        a.wag = a.type === 'dog' ? 0.15 : 0.4
        return
    }
    // miradas nerviosas: de pronto mira hacia un lado, luego hacia el otro y a veces vuelve al frente; si el jugador esta cerca, lo mira a el
    n.glanceT -= dt
    if (n.glanceT <= 0) {
        n.glanceT = rand(0.7, 2)
        n.goal = Math.random() < 0.25 ? 0 : rand(-0.6, 0.6)
    }
    let goal = n.goal
    if (watch) {
        const dx = watch.x - a.base.x
        const dz = watch.z - a.base.z
        if (Math.hypot(dx, dz) < 3.4) {
            // hacia donde esta el jugador, respecto a hacia donde mira la mascota (con un poco de temblor para que no se vea fijo)
            goal = Math.max(-0.9, Math.min(0.9, angleDiff(pet.rotation.y, Math.atan2(dx, dz)) * 0.8)) + n.goal * 0.25
        }
    }
    a.glance = (a.glance || 0) + (goal - (a.glance || 0)) * Math.min(1, dt * 7)
    // sobresalto: un saltito de susto de vez en cuando
    if (startle) {
        n.nextStartle -= dt
        if (n.nextStartle <= 0 && !(a.hop > 0)) {
            n.nextStartle = rand(startle[0], startle[1])
            a.hop = 1
        }
    }
    if (a.type === 'dog') {
        // jadea por rachas de unos segundos
        if (n.pantT > 0) {
            n.pantT -= dt
            a.pantOn = true
        } else {
            a.pantOn = false
            n.nextPant -= dt
            if (n.nextPant <= 0) {
                n.pantT = rand(2, 3.5)
                n.nextPant = rand(2.5, 5)
            }
        }
        a.wag = 0.15
    } else {
        // la gata mueve la cola a tirones
        a.wag = 0.35 + 0.9 * Math.max(0, Math.sin(n.t * 2.1)) ** 2
    }
    if (speak) {
        n.nextSpeak -= dt
        if (n.nextSpeak <= 0) {
            n.nextSpeak = rand(every[0], every[1])
            a.bark = 1 // la boca se mueve igual que el sonido
            if (a.type === 'dog') audio.bark(volume)
            else audio.meow(volume)
        }
    }
}

/** Apaga el nerviosismo (la mascota deja de mirar a los lados y de jadear). */
export function calmNerves(pet) {
    const a = pet.userData
    a.glance = 0
    a.pantOn = false
    states.delete(pet)
}
