/**
 * SOMBRA REAL DE LA SILUETA de una mascota, para los lugares donde ninguna luz la proyecta (p. ej. dentro del armario, bajo el techo del mueble): cada cuadro
 * se dibuja la mascota vista desde arriba, en negro, en una textura chica; esa textura se pone como una calcomania sobre la repisa o el piso, debajo de ella.
 * Como la textura es de baja resolucion y se estira, los bordes salen suaves, y la sombra tiene la forma verdadera del cuerpo, las patas y la cola
 * (en vez de la mancha redonda de la sombra de contacto).
 *
 *   const shadow = createPetShadow(renderer, scene, pet)
 *   shadow.update(true, planeY)     // cada cuadro: true = dibujarla sobre el plano a la altura planeY (m); false = apagarla
 */
import * as THREE from 'three'

const LAYER = 5 // capa que solo ve la camara de la sombra
const HALF = 0.9 // la calcomania cubre 1.8 x 1.8 m alrededor de la mascota
const SIZE = 96
const BLUR = 1.5 // desenfoque, en texeles (1.5 de 96 sobre 1.8 m = unos 3 cm)
const WHITE = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }) // (la silueta se dibuja en blanco sobre negro y se usa como mapa de transparencia)
const camera = new THREE.OrthographicCamera(-HALF, HALF, HALF, -HALF, 0.01, 6)
camera.layers.set(LAYER)
camera.up.set(0, 0, -1)

// desenfoque gaussiano en dos pasadas (horizontal y vertical) sobre la silueta (canal verde)
const blurCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)
const blurMaterial = new THREE.ShaderMaterial({
    uniforms: { map: { value: null }, dir: { value: new THREE.Vector2() } },
    vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }',
    fragmentShader: `uniform sampler2D map; uniform vec2 dir; varying vec2 vUv;
        void main(){
            float a = texture2D(map, vUv).g * 0.18;
            a += (texture2D(map, vUv + dir).g + texture2D(map, vUv - dir).g) * 0.15;
            a += (texture2D(map, vUv + dir * 2.0).g + texture2D(map, vUv - dir * 2.0).g) * 0.12;
            a += (texture2D(map, vUv + dir * 3.0).g + texture2D(map, vUv - dir * 3.0).g) * 0.09;
            a += (texture2D(map, vUv + dir * 4.0).g + texture2D(map, vUv - dir * 4.0).g) * 0.05;
            gl_FragColor = vec4(a, a, a, 1.0);
        }`,
    depthTest: false,
    depthWrite: false,
})
const blurScene = new THREE.Scene()
blurScene.add(new THREE.Mesh(new THREE.PlaneGeometry(2, 2), blurMaterial))
/** `skew` mueve la sombra en x y z (m) como si la luz viniera de ese lado; `strength` es su oscuridad (0 a 1). */
export function createPetShadow(renderer, scene, pet, { skew = [0, 0], strength = 0.55 } = {}) {
    const options = { minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, depthBuffer: true }
    const target = new THREE.WebGLRenderTarget(SIZE, SIZE, options) // la silueta, y al final la silueta ya desenfocada
    const temp = new THREE.WebGLRenderTarget(SIZE, SIZE, options)
    const decal = new THREE.Mesh(
        new THREE.PlaneGeometry(HALF * 2, HALF * 2),
        new THREE.MeshBasicMaterial({
            alphaMap: target.texture,
            color: '#100a08',
            transparent: true,
            opacity: strength,
            depthWrite: false,
            polygonOffset: true,
            polygonOffsetFactor: -4,
            polygonOffsetUnits: -4,
        }),
    )
    decal.rotation.x = -Math.PI / 2
    decal.renderOrder = 1
    decal.visible = false
    scene.add(decal)
    let ready = false
    const worldPos = new THREE.Vector3()
    const clear = new THREE.Color()

    function mark() {
        // las piezas de la mascota (low poly, que siempre estan en la escena aunque la capa detallada este puesta) entran tambien en la capa de la sombra
        pet.traverse((o) => o.isSkinnedMesh && !o.userData.hd && !o.userData.isHull && o.layers.enable(LAYER))
        ready = true
    }

    return {
        decal,
        update(active, planeY = 0) {
            decal.visible = active && pet.visible
            if (!decal.visible) return
            if (!ready) mark()
            pet.getWorldPosition(worldPos)
            camera.position.set(worldPos.x, planeY + 3, worldPos.z)
            camera.lookAt(worldPos.x, planeY, worldPos.z)
            // solo las piezas que estan sobre el plano cuentan (lo que queda debajo no da sombra hacia arriba): el plano de recorte lo da el cercano de la camara
            camera.near = 0.01
            camera.far = 3 + 0.02
            camera.updateProjectionMatrix()
            const background = scene.background
            const shadowsOn = renderer.shadowMap.enabled
            const alpha = renderer.getClearAlpha()
            renderer.getClearColor(clear)
            scene.background = null
            scene.overrideMaterial = WHITE
            renderer.shadowMap.enabled = false // (sin esto el dibujo extra volveria a calcular los mapas de sombras de las luces)
            renderer.setClearColor(0x000000, 1)
            renderer.setRenderTarget(target)
            renderer.clear()
            renderer.render(scene, camera)
            // desenfoque: silueta -> temp (horizontal) -> target (vertical)
            const step = BLUR / SIZE
            blurMaterial.uniforms.map.value = target.texture
            blurMaterial.uniforms.dir.value.set(step, 0)
            renderer.setRenderTarget(temp)
            renderer.clear()
            renderer.render(blurScene, blurCamera)
            blurMaterial.uniforms.map.value = temp.texture
            blurMaterial.uniforms.dir.value.set(0, step)
            renderer.setRenderTarget(target)
            renderer.clear()
            renderer.render(blurScene, blurCamera)
            renderer.setRenderTarget(null)
            renderer.setClearColor(clear, alpha)
            renderer.shadowMap.enabled = shadowsOn
            scene.overrideMaterial = null
            scene.background = background
            decal.position.set(worldPos.x + skew[0], planeY + 0.012, worldPos.z + skew[1])
        },
        dispose() {
            decal.removeFromParent()
            target.dispose()
            temp.dispose()
        },
    }
}
