/**
 * ANIMACION DEL MICROCHIP: la jeringa aparece junto a la nuca de la mascota, se acerca, la aguja entra, se empuja el
 * embolo (aqui va el microchip), sale y se va. Al terminar llama onDone.
 *
 *   const inj = startInjection(mascota, { size, onDone })     // size = largo de la jeringa en metros de la mascota
 *   en cada cuadro:  inj.tick(dt)       y para cortarla:  inj.cancel()
 */
import * as THREE from 'three'
import { createSyringe } from '../three/models/trackGlb.js'

const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}
const UP = new THREE.Vector3(0, 1, 0)
const site = new THREE.Vector3()

// tiempos (s): aparece, se acerca y entra, empuja el embolo, se retira
const T_IN = 0.9
const T_PUSH = 1.9
const T_HOLD = 2.9
const T_END = 3.8

export function startInjection(pet, { size = 0.3, onDone } = {}) {
    const syr = createSyringe(size)
    const chip = pet.userData.anchors.chip
    let t = 0
    let finished = false
    if (!syr || !chip) {
        setTimeout(() => onDone && onDone(), 300)
        return { tick() {}, cancel() {} }
    }
    // la aguja apunta hacia abajo y un poco hacia adelante, entrando por la nuca (ejes de la mascota: +z es el frente)
    const dir = new THREE.Vector3(0, -0.62, 0.78).normalize()
    syr.group.quaternion.setFromUnitVectors(UP, dir)
    const baseScale = syr.group.scale.x
    syr.group.visible = false
    pet.add(syr.group)

    const finish = (call) => {
        if (finished) return
        finished = true
        pet.remove(syr.group)
        if (call && onDone) onDone()
    }
    return {
        tick(dt) {
            if (finished) return
            t += dt
            chip.getWorldPosition(site)
            pet.worldToLocal(site) // la nuca (puede moverse un poco con la respiracion)
            let off // cuanto se separa la punta de la piel a lo largo de la aguja (negativo = afuera)
            let appear = 1
            let push = 0
            if (t < T_IN) {
                appear = ease(t / T_IN)
                off = -0.85 * size
            } else if (t < T_PUSH) {
                off = -0.85 * size + 1.05 * size * ease((t - T_IN) / (T_PUSH - T_IN)) // llega a la piel y entra un poco
            } else if (t < T_HOLD) {
                off = 0.2 * size
                push = ease((t - T_PUSH) / (T_HOLD - T_PUSH)) * syr.push
            } else {
                const u = ease((t - T_HOLD) / (T_END - T_HOLD))
                off = 0.2 * size - 1.05 * size * u
                push = syr.push
                appear = 1 - ease((u - 0.45) / 0.55)
            }
            syr.group.visible = appear > 0.02
            syr.group.scale.setScalar(Math.max(0.001, baseScale * appear))
            syr.group.position.copy(site).addScaledVector(dir, off)
            syr.plunger.position.y = push
            if (t >= T_END) finish(true)
        },
        cancel() {
            finish(false)
        },
    }
}
