/**
 * ARNES Y CORREA (modelo de Blender: static/arnes.glb).
 * El .glb trae DOS arneses animados que se colocan solos sobre un perro de referencia (2.4 s): el azul va sobre el perro
 * grande y el rojo, mas chico, sobre el pequeno. Los perros de referencia del archivo no se usan: aqui solo se toman las piezas
 * del arnes con su animacion y se acomodan sobre el perro o el gato de la experiencia (con todos sus huesos y animaciones).
 *
 *   loadHarnessModel()          carga el .glb (una vez)
 *   createHarness(pet, fit)     arnes listo para ponerle a la mascota (fit: 'dogLarge' | 'dogSmall' | 'cat')
 *     .play()                   oculta el collar y empieza la animacion
 *     .update(dt)               avanza la animacion (cada cuadro)
 *     .dispose()                quita el arnes y devuelve el collar
 *
 * Las piezas estan en el espacio de su perro de referencia (que mira hacia +x, de pie sobre y = 0): el grupo se escala
 * (HARNESS_FIT.S, a lo largo, alto y ancho del perro), se gira para que el frente sea +z y se centra en el pecho de la mascota.
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'

let source = null

// Piezas de cada arnes (los nombres ya sin puntos, como los deja el cargador): [piezas del perro grande, piezas del pequeno]
const SETS = {
    large: ['anilla001', 'arnes001', 'arnes006', 'arnes007', 'arnes008', 'arnes009', 'correa001'],
    small: ['anilla', 'arnes', 'arnes002', 'arnes003', 'arnes004', 'arnes005', 'correa'],
}

/**
 * Como se acomoda cada arnes en la mascota (medidas en metros del modelo de la mascota, con el frente en +z):
 *   set     que arnes se usa
 *   ref     [x, z] del pecho en el perro de referencia (donde cae el aro del lomo del arnes)
 *   S       escala [a lo largo, alto, ancho]: el perro de la experiencia es mas grande que el de referencia (casi uniforme: asi las\n *           piezas, que giran al ponerse, no se deforman)
 *   z, y    donde queda el centro del arnes en la mascota (z = detras del cuello; y = cuanto sube sobre el piso: el pecho\n *           del perro de referencia esta mas abajo que el de la mascota, por eso el arnes se sube con y)
 */
export const HARNESS_FIT = {
    dogLarge: { set: 'large', ref: [0.66, 0.165], S: [1.3, 1.3, 1.3], x: 0.01, y: 0.07, z: 0, rot: 0.06 },
    dogSmall: { set: 'small', ref: [0.68, -0.485], S: [2.2, 2.2, 2.34], x: 0, y: 0.04, z: 0.02, rot: 0 }, // perro pequeno: el arnes rojo, mas chico
    cat: { set: 'small', ref: [0.68, -0.485], S: [1.62, 1.4, 1.5], x: -0.01, y: 0, z: 0.065, rot: 0 },
}

// Valores de fabrica y ajustes guardados en el navegador (se editan en vivo con F2, ver ui/walkTuner.js)
export const HARNESS_DEFAULT = JSON.parse(JSON.stringify(HARNESS_FIT))
try {
    const saved = JSON.parse(localStorage.getItem('petalert.harness') || '{}')
    Object.keys(HARNESS_FIT).forEach((name) => saved[name] && Object.assign(HARNESS_FIT[name], saved[name]))
} catch (e) {}
export const saveHarnessFit = () => {
    try {
        localStorage.setItem('petalert.harness', JSON.stringify(HARNESS_FIT))
    } catch (e) {}
}

export async function loadHarnessModel() {
    if (source) return source
    try {
        source = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + 'arnes.glb')
    } catch (error) {
        console.warn('No cargo static/arnes.glb: no hay animacion del arnes.', error)
    }
    return source
}
export const hasHarnessModel = () => !!source

export function createHarness(pet, fitName) {
    if (!source) return null
    const fit = HARNESS_FIT[fitName]
    const names = SETS[fit.set]
    // grupo exterior: gira el frente del perro de referencia (+x) hacia +z y lo centra en el pecho de la mascota
    const outer = new THREE.Group()
    outer.name = 'arnes'
    // grupo interior: escala (a lo largo, alto, ancho) y lleva el pecho de referencia al origen
    const inner = new THREE.Group()
    outer.add(inner)
    // (se vuelve a calcular cada cuadro: asi los ajustes en vivo se ven al instante)
    const placeFit = () => {
        outer.rotation.y = -Math.PI / 2 + (fit.rot || 0)
        outer.position.set(fit.x || 0, fit.y, fit.z)
        inner.scale.set(...fit.S)
        inner.position.set(-fit.ref[0] * fit.S[0], 0, -fit.ref[1] * fit.S[2])
    }
    placeFit()
    names.forEach((name) => {
        const node = source.scene.getObjectByName(name)
        if (!node) return
        const piece = node.clone()
        piece.traverse((o) => {
            if (o.isMesh) o.castShadow = true
        })
        inner.add(piece)
    })
    // animaciones de esas piezas (una por pieza, de 2.4 s)
    const clips = source.animations.filter((clip) => names.includes(clip.tracks[0].name.split('.')[0]))
    const mixer = new THREE.AnimationMixer(inner)
    const actions = clips.map((clip) => {
        const action = mixer.clipAction(clip)
        action.setLoop(THREE.LoopOnce, 1)
        action.clampWhenFinished = true
        action.play()
        action.paused = true
        action.time = 0
        return action
    })
    mixer.update(0)
    outer.visible = false // aparece al empezar la animacion
    pet.add(outer)
    const duration = Math.max(...clips.map((c) => c.duration))
    const harness = {
        group: outer,
        duration,
        playing: false,
        done: false,
        play() {
            if (harness.playing && !harness.done) return // (si ya termino, se puede ver otra vez)
            harness.playing = true
            harness.done = false
            outer.visible = true
            if (pet.userData.collar) pet.userData.collar.visible = false // con el arnes se le quita el collar
            actions.forEach((action) => {
                action.reset()
                action.paused = false
                action.play()
            })
        },
        update(dt) {
            placeFit()
            if (!harness.playing || harness.done) return
            mixer.update(dt)
            if (actions.every((action) => action.time >= action.getClip().duration - 1e-3)) harness.done = true
        },
        /** Quita el arnes y devuelve el collar: la mascota queda como antes de ponerselo (se puede volver a ver). */
        reset() {
            harness.playing = false
            harness.done = false
            outer.visible = false
            actions.forEach((action) => {
                action.reset()
                action.paused = true
                action.time = 0
            })
            mixer.update(0)
            if (pet.userData.collar) pet.userData.collar.visible = true
        },
        dispose() {
            outer.removeFromParent()
            if (pet.userData.collar) pet.userData.collar.visible = true
        },
    }
    return harness
}
